            #suggestEmployeesDrawer .form-group label,
            #editSuggestedEmployeeDrawer .form-group label {
                color: var(--ma-text);
                font-size: 12px;
                font-weight: 800;
            }

            /* =========================================================
               CUSTOM MODALS / OVERLAYS
            ========================================================= */

            .cmodal,
            .cp-overlay,
            .sn-overlay,
            #objDrawerRoot {
                position: fixed;
                inset: 0;
                z-index: 9999;
                display: none;
            }

            .cp-overlay,
            .sn-overlay {
                align-items: center;
                justify-content: center;
                padding: 24px;
                background: rgba(55, 65, 81, .45);
                z-index: 20000;
            }

            .sn-overlay {
                padding: 18px;
                z-index: 99999;
            }

            .cmodal.is-open,
            #objDrawerRoot.is-visible {
                display: block;
            }

            .cp-overlay.is-open,
            .sn-overlay.is-open,
            #serialsOverlay.sn-overlay.is-open {
                display: flex;
            }

            .cmodal__backdrop,
            #objDrawerBackdrop {
                position: absolute;
                inset: 0;
                background: rgba(55, 65, 81, .45);
            }

            #objDrawerBackdrop {
                opacity: 0;
                transition: opacity .3s ease;
            }

            #objDrawerRoot.is-visible #objDrawerBackdrop {
                opacity: 1;
            }

            .cmodal__dialog,
            .cp-dialog,
            .sn-dialog,
            #objDrawerPanel {
                position: relative;
                overflow: hidden;
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-lg);
                background: var(--ma-bg);
                box-shadow: none;
            }

            .cmodal__dialog {
                width: min(1547px, calc(100% - 32px));
                margin: 48px auto;
                opacity: .98;
                transform: translateY(10px);
            }

            .cmodal.is-open .cmodal__dialog {
                opacity: 1;
                transform: none;
            }

            .cp-dialog {
                width: min(980px, 96vw);
                max-height: 90vh;
                overflow: auto;
                outline: none;
            }

            .sn-dialog {
                width: min(920px, 100%);
                max-height: calc(100vh - 40px);
                opacity: 0;
                transform: translateY(10px);
                animation: snIn .14s ease-out forwards;
            }

            #serialsOverlay.sn-overlay {
                z-index: 20000;
                pointer-events: auto;
            }

            #serialsOverlay .sn-dialog {
                width: min(920px, 95vw);
                max-height: 85vh;
                overflow: auto;
                pointer-events: auto;
            }

            #serialsOverlay input,
            #serialsOverlay button,
            #serialsOverlay .sn-dialog {
                pointer-events: auto;
            }

            body.sn-open .modal.show {
                pointer-events: none;
            }

            #objDrawerPanel {
                position: absolute;
                top: 0;
                right: 0;
                display: flex;
                flex-direction: column;
                width: min(900px, 100%);
                height: 100%;
                border-radius: 0;
                transform: translateX(100%);
                transition: transform .3s cubic-bezier(.25, 1, .5, 1);
            }

            #objDrawerRoot.is-visible #objDrawerPanel {
                transform: translateX(0);
            }

            .cmodal__header,
            .cmodal__footer,
            .cp-header,
            .cp-footer,
            .sn-header,
            .sn-footer {
                display: flex;
                align-items: center;
                justify-content: space-between;
                padding: 14px 16px;
                border-bottom: 1px solid var(--ma-border);
                background: var(--ma-bg);
            }

            .cmodal__footer,
            .cp-footer,
            .sn-footer {
                justify-content: flex-end;
                gap: 10px;
                border-top: 1px solid var(--ma-border);
                border-bottom: 0;
            }

            .cp-header,
            .cp-footer {
                position: sticky;
                z-index: 2;
            }

            .cp-header {
                top: 0;
            }

            .cp-footer {
                bottom: 0;
            }

            .cmodal__title,
            .cp-title,
            .sn-title {
                margin: 0;
                font-size: 16px;
                font-weight: 900;
            }

            .cmodal__close {
                width: 36px;
                height: 36px;
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-sm);
                background: var(--ma-bg);
                color: var(--ma-heading);
                font-size: 22px;
                line-height: 1;
            }

            .cmodal__body,
            .cp-body,
            .sn-body {
                overflow: auto;
                padding: 14px 16px;
            }

            .cmodal__body {
                max-height: calc(100vh - 200px);
            }

            .sn-body {
                max-height: calc(100vh - 180px);
            }

            body.cmodal-open,
            html.cp-modal-open,
            body.cp-modal-open {
                overflow: hidden;
            }

            .cp-overlay .select2-container {
                z-index: 20010;
            }

            .sn-info {
                display: flex;
                flex-wrap: wrap;
                align-items: center;
                gap: 10px;
                margin-bottom: 12px;
                padding: 10px 12px;
                border-radius: var(--ma-radius-sm);
                background: var(--ma-soft-bg, #f8fbfd);
            }

            .sn-sep {
                opacity: .6;
            }

            /* =========================================================
               OBJECT DRAWER CARDS
            ========================================================= */

            .obj-card {
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-md);
                background: var(--ma-bg);
                box-shadow: none;
                transition: all .2s;
            }

            .obj-card-header {
                padding: 12px;
                border-bottom: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-md) var(--ma-radius-md) 0 0;
                background: var(--ma-soft-bg, #f8fbfd);
            }

            .obj-dropzone {
                min-height: 120px;
                padding: 10px;
                border-radius: 0 0 var(--ma-radius-md) var(--ma-radius-md);
                background: var(--ma-soft-bg, #f8fbfd);
            }

            .prod-card {
                margin-bottom: 8px;
                padding: 10px;
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-sm);
                background: var(--ma-bg);
                cursor: grab;
            }

            .prod-card:active {
                cursor: grabbing;
                box-shadow: none;
            }

            #serialsOverlay {
                pointer-events: auto;
            }

            /* =========================================================
               FW FORM CLASSES
            ========================================================= */

            .partial-form {
                width: 100%;
                color: var(--ma-text);
            }

            .fw-shell {
                overflow: hidden;
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-xl);
                background: var(--ma-bg);
            }

            .fw-header {
                display: flex;
                align-items: flex-start;
                justify-content: space-between;
                gap: 16px;
                padding: 24px;
                border-bottom: 1px solid var(--ma-border);
                background: var(--ma-bg);
            }

            .fw-header-title {
                margin: 0;
                font-size: 30px;
                line-height: 1.05;
                font-weight: 900;
                letter-spacing: -.03em;
            }

            .fw-header-subtitle {
                margin-top: 8px;
                font-size: 14px;
                font-weight: 500;
            }

            .fw-header-box,
            .fw-section,
            .fw-note-box,
            .fw-roof-card {
                border: 1px solid var(--ma-border);
                border-radius: var(--ma-radius-lg);
                background: var(--ma-bg);
                box-shadow: none;
            }

            .fw-header-box {
                min-width: 150px;
                padding: 12px 14px;
            }

            .fw-body {
                padding: 24px;
            }

            .fw-grid-2 {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 24px;
            }

            .fw-col,
            .fw-fields,
            .fw-roof-list {
                display: flex;
                flex-direction: column;
            }

            .fw-col {
                gap: 24px;
            }

            .fw-fields,
            .fw-roof-list {
                gap: 18px;
            }

            .fw-section {
                padding: 20px;
            }

            .fw-section-head {
                display: flex;
                align-items: center;
                gap: 12px;
                margin-bottom: 20px;
                padding-bottom: 12px;
                border-bottom: 1px solid var(--ma-border);
            }

            .fw-grid-2-inner {
                display: grid;
                grid-template-columns: 1fr 1fr;
                gap: 18px;
            }

            .fw-field {
                display: flex;
                flex-direction: column;
                gap: 6px;
            }

            .fw-label {
                font-size: 13px;
                font-weight: 900;
                line-height: 1.35;
            }

            .fw-full {
                margin-top: 24px;
            }

            .fw-footer {
                display: flex;
                align-items: center;
                justify-content: flex-end;
                gap: 12px;
                padding: 18px 24px;
                border-top: 1px solid var(--ma-border);
                background: var(--ma-bg);
            }

            .fw-btn {
                display: inline-flex;
                align-items: center;
                justify-content: center;
                gap: 10px;
                padding: 13px 22px;
                border-radius: var(--ma-radius-sm);
                font-size: 14px;
                font-weight: 900;
                text-decoration: none;
            }

            .has-tooltip {
                position: relative;
                cursor: help;
            }

            .has-tooltip[data-tooltip]:hover::after {
                content: attr(data-tooltip);
                position: absolute;
                top: calc(100% + 8px);
                left: 0;
                z-index: 40;
                width: 260px;
                padding: 10px 12px;
                border-radius: var(--ma-radius-sm);
                background: var(--ma-heading);
                color: #ffffff;
                font-size: 12px;
                font-weight: 500;
                line-height: 1.45;
                box-shadow: none;
            }

            .has-tooltip[data-tooltip]:hover::before {
                content: "";
                position: absolute;
                top: 100%;
                left: 14px;
                z-index: 41;
                border: 6px solid transparent;
                border-bottom-color: var(--ma-heading);
            }

            .fw-empty-state {
                margin-bottom: 20px;
                padding: 48px 24px;
                border: 1px dashed var(--ma-border);
                border-radius: var(--ma-radius-lg);
                background: var(--ma-soft-bg, #f8fbfd);
                text-align: center;
            }

            .fw-empty-state i {
                display: block;
                margin-bottom: 14px;
                color: var(--ma-muted);
                font-size: 34px;
            }

            .fw-empty-title {
                margin: 0;
                color: var(--ma-text);
                font-weight: 900;
            }

            .fw-actions-row {
                display: flex;
                align-items: center;
                justify-content: space-between;
                flex-wrap: wrap;
                gap: 12px;
                margin-bottom: 20px;
            }

            .fw-roof-card {
                overflow: hidden;
            }

            .fw-roof-header {
                display: flex;
                align-items: center;
                justify-content: space-between;
                gap: 16px;
                padding: 16px 20px;
                border-bottom: 1px solid var(--ma-border);
                background: var(--ma-soft-bg, #f8fbfd);
                cursor: pointer;
                transition: background .2s ease;
            }

            .fw-roof-header:hover {
                background: var(--ma-blue-soft);
            }

            .fw-roof-header-left {
                display: flex;
                align-items: center;
                gap: 12px;
                min-width: 0;
            }

            .fw-roof-toggle {
                display: flex;
                align-items: center;
                justify-content: center;
                color: var(--ma-muted);
                font-size: 18px;
                transition: transform .28s ease;
            }

            .fw-roof-card.is-collapsed .fw-roof-toggle {
                transform: rotate(-90deg);
            }

            .fw-roof-card.is-collapsed .fw-roof-body {
                display: none;
            }

            .fw-roof-title {
                margin: 0;
                font-size: 17px;
                font-weight: 900;
                line-height: 1.25;
            }

            .fw-icon-btn {
                width: 34px;
                height: 34px;
                display: inline-flex;
                align-items: center;
                justify-content: center;
                flex-shrink: 0;
                border: 0;
                border-radius: var(--ma-radius-sm);
                background: transparent;
                color: var(--ma-muted);
            }

            .fw-icon-btn:hover {
                background: rgba(229, 6, 86, .10) !important;
                color: var(--ma-pink) !important;
            }

            .fw-roof-body {
                padding: 22px;
            }

            .fw-note-box {
                padding: 16px;
            }

            /* =========================================================
               RESPONSIVE EXTRAS
            ========================================================= */

            @media (min-width: 768px) {
                .custom-responsive-card {
                    flex: 1 1 calc(50% - 1rem);
                    max-width: calc(50% - 1rem);
                }
            }

            @media (max-width: 1100px) {
                .fw-grid-2 {
                    grid-template-columns: 1fr;
                }
            }

            @media (max-width: 1024px) {
                .oc-item-row {
                    grid-template-columns: 50px 1.5fr 1.8fr 2.6fr 150px !important;
                    gap: 12px;
                    overflow-x: auto;
                }

                .oc-cell-title {
                    display: block;
                }
            }

            @media (max-width: 991.98px) {
                .custom-responsive-card {
                    flex: 1 1 100%;
                    max-width: 100%;
                }

                .fw-grid-2,
                .fw-grid-2-inner {
                    grid-template-columns: 1fr;
                }

                .phase-sidebar,
                .report-sidebar,
                .nx-drawer-panel,
                .customer-drawer-panel,
                #objDrawerPanel {
                    width: 100% !important;
                    max-width: 100% !important;
                }
            }

            @media (max-width: 768px) {
                .product-card-header {
                    flex-direction: column;
                    align-items: flex-start;
                    gap: .3rem;
                }

                .product-card-actions {
                    margin-top: .5rem;
                }

                .fw-header,
                .fw-footer,
                .fw-body {
                    padding: 18px;
                }

                .fw-header {
                    flex-direction: column;
                }

                .fw-header-title {
                    font-size: 24px;
                }

                .fw-roof-header,
                .fw-roof-body {
                    padding: 16px;
                }

                .fw-actions-row {
                    align-items: stretch;
                }

                .fw-actions-row .fw-btn {
                    width: 100%;
                }
            }

            @media (max-width: 576px) {
                .kanban-column {
                    width: 90vw;
                }

                .kanban-card {
                    padding: 12px;
                }

                .kanban-title {
                    font-size: 14px;
                }

                .cp-overlay,
                .sn-overlay {
                    padding: 12px;
                }

                .cmodal__dialog {
                    width: calc(100% - 20px);
                    margin: 20px auto;
                }

                .cmodal__body {
                    max-height: calc(100vh - 150px);
                }
            }

            @keyframes maPulse {
                0% {
                    transform: scale(1);
                    background-color: var(--ma-blue-soft);
                }

                50% {
                    transform: scale(1.015);
                    background-color: var(--ma-green-soft);
                }

                100% {
                    transform: scale(1);
                    background-color: inherit;
                }
            }

            @keyframes snIn {
                to {
                    opacity: 1;
                    transform: translateY(0);
                }
            }
        </style>
        <style>
        /* =========================================================
           CUSTOMER NOTE COMPOSER
           Hidden by default, opens as centered animated modal
        ========================================================= */

        .note-backdrop {
            position: fixed;
            inset: 0;
            display: none;
            background: rgba(15, 23, 42, .38);
            backdrop-filter: blur(2px);
            z-index: 1048;
        }

        .note-backdrop.is-open {
            display: block;
            animation: noteBackdropIn .18s ease forwards;
        }

        .note-composer {
            position: fixed;
            top: 50%;
            left: 50%;
            width: min(520px, calc(100vw - 28px));
            max-height: calc(100vh - 80px);
            display: flex;
            flex-direction: column;
            background: #ffffff;
            border-radius: 22px;
            z-index: 1049;
            overflow: hidden;
            opacity: 0;
            visibility: hidden;
            pointer-events: none;
            transform: translate(-50%, -46%) scale(.96);
            transition:
                opacity .2s ease,
                visibility .2s ease,
                transform .22s ease;
        }

        .note-composer.open {
            opacity: 1;
            visibility: visible;
            pointer-events: auto;
            transform: translate(-50%, -50%) scale(1);
        }

        .note-composer-header {
            display: flex;
            align-items: center;
            justify-content: space-between;
            gap: 12px;
            padding: 14px 16px;
            background: #ffffff;
            border-bottom: 1px solid rgba(192, 216, 234, .45);
        }

        .note-composer-title {
            margin: 0;
            color: var(--ma-heading, #74b2d4);
            font-size: 15px;
            font-weight: 900;
            letter-spacing: .04em;
        }

        .note-composer-close {
            width: 34px;
            height: 34px;
            border: 0;
            border-radius: 999px;
            background: var(--ma-blue-soft, #c0d8ea);
            color: var(--ma-heading, #74b2d4);
            display: inline-flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
        }

        .note-composer-close:hover {
            background: var(--ma-heading, #74b2d4);
            color: #ffffff;
        }

        .note-composer-body {
            padding: 16px;
            background: #ffffff;
        }

        .note-composer textarea {
            width: 100%;
            min-height: 130px;
            resize: vertical;
            border: 1px solid rgba(192, 216, 234, .65) !important;
            border-radius: 18px !important;
            padding: 14px 16px;
            background: #ffffff !important;
            color: var(--ma-text, #374151) !important;
            box-shadow: none !important;
        }

        .note-composer textarea:focus {
            outline: 2px solid rgba(116, 178, 212, .35);
            outline-offset: 2px;
        }

        .note-composer-footer {
            display: flex;
            justify-content: flex-end;
            gap: 10px;
            padding: 0 16px 16px;
            background: #ffffff;
        }

        .note-composer-footer .btn {
            border-radius: 999px !important;
            box-shadow: none !important;
        }

        body.note-composer-open {
            overflow: hidden;
        }

        @keyframes noteBackdropIn {
            from {
                opacity: 0;
            }

            to {
                opacity: 1;
            }
        }

        @media (max-width: 575.98px) {
            .note-composer {
                width: calc(100vw - 20px);
                max-height: calc(100dvh - 40px);
            }

            .note-composer textarea {
                min-height: 160px;
            }
        }
    </style>

    <style>
