                                <script>
                                    document.addEventListener("DOMContentLoaded", function () {
                                        feather.replace();
                                    });
                                </script>

                                    <script>
                                    document.addEventListener('DOMContentLoaded', function () {
                                        const layout = document.querySelector('.layout');
                                        const sidebar = document.getElementById('customerSidebar');
                                        const contentStation = document.querySelector('.contentStation');
                                        const rightPanel = document.querySelector('.right-panel');

                                        const mainBtn = document.getElementById('mainContentToggle');
                                        const noteFullscreenBtn = document.getElementById('btnToggleRightPanelFullscreen');
                                        const noteHideBtn = document.getElementById('btnToggleRightPanelHidden');
                                        const noteShowBtn = document.getElementById('showRightPanelBtn');

                                        if (!layout || !sidebar || !contentStation || !rightPanel) return;

                                        let sidebarManuallyChanged = false;

                                        function refreshIcons() {
                                            if (window.feather) {
                                                window.feather.replace();
                                            }
                                        }

                                        function setIcon(button, featherName, fallbackClass) {
                                            if (!button) return;

                                            const oldIcon = button.querySelector('i, svg');
                                            if (!oldIcon) return;

                                            const icon = document.createElement('i');
                                            icon.setAttribute('data-feather', featherName);

                                            if (fallbackClass) {
                                                icon.className = 'feather ' + fallbackClass;
                                            }

                                            oldIcon.replaceWith(icon);
                                            refreshIcons();
                                        }

                                        function closeSidebarLists() {
                                            document.querySelectorAll('.product-list').forEach(function (el) {
                                                el.classList.remove('show');
                                                el.style.display = 'none';
                                                el.setAttribute('aria-expanded', 'false');
                                            });

                                            document.querySelectorAll('.sub-nav').forEach(function (el) {
                                                el.classList.remove('show');
                                                el.style.display = 'none';
                                                el.setAttribute('aria-expanded', 'false');
                                            });

                                            document.querySelectorAll('.project-link').forEach(function (el) {
                                                el.classList.remove('active');
                                            });
                                        }

                                        function minimizeCustomerSidebar() {
                                            resetFullscreenModes(false);

                                            layout.classList.add('sidebar-minimized');
                                            sidebar.classList.add('minimized');
                                            contentStation.classList.add('expanded');

                                            closeSidebarLists();

                                            setIcon(sidebar.querySelector('.minimize-btn'), 'chevrons-right', 'icon-chevrons-right');

                                            sidebarManuallyChanged = true;
                                            refreshIcons();
                                        }

                                        function expandCustomerSidebar() {
                                            layout.classList.remove('sidebar-minimized');
                                            sidebar.classList.remove('minimized');
                                            contentStation.classList.remove('expanded');

                                            setIcon(sidebar.querySelector('.minimize-btn'), 'chevrons-left', 'icon-chevrons-left');

                                            sidebarManuallyChanged = true;
                                            refreshIcons();
                                        }

                                        window.togglecustomerSidebar = function () {
                                            if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                                expandCustomerSidebar();
                                            } else {
                                                minimizeCustomerSidebar();
                                            }
                                        };

                                        function autoSidebarMode() {
                                            if (sidebarManuallyChanged) return;

                                            if (window.innerWidth < 992) {
                                                minimizeCustomerSidebar();
                                                sidebarManuallyChanged = false;
                                            } else {
                                                expandCustomerSidebar();
                                                sidebarManuallyChanged = false;
                                            }
                                        }

                                        function resetFullscreenModes(restoreIcons = true) {
                                            layout.classList.remove('main-fullscreen-mode');
                                            layout.classList.remove('notes-fullscreen-mode');

                                            contentStation.classList.remove('main-fullscreen');
                                            rightPanel.classList.remove('notes-fullscreen');

                                            sidebar.classList.remove('fullscreen-hidden');
                                            contentStation.classList.remove('fullscreen-hidden');
                                            rightPanel.classList.remove('fullscreen-hidden');

                                            if (restoreIcons) {
                                                setIcon(mainBtn, 'maximize-2', 'icon-maximize-2');
                                                setIcon(noteFullscreenBtn, 'maximize-2', 'icon-maximize-2');
                                            }
                                        }

                                        function showNotesPanel() {
                                            layout.classList.remove('notes-hidden-mode');
                                            rightPanel.classList.remove('right-hidden');

                                            if (noteShowBtn) {
                                                noteShowBtn.classList.add('d-none');
                                            }

                                            setIcon(noteHideBtn, 'sidebar', 'icon-sidebar');
                                            refreshIcons();
                                        }

                                        function hideNotesPanel() {
                                            resetFullscreenModes();

                                            layout.classList.add('notes-hidden-mode');
                                            rightPanel.classList.add('right-hidden');

                                            if (noteShowBtn) {
                                                noteShowBtn.classList.remove('d-none');
                                            }

                                            setIcon(noteHideBtn, 'message-square', 'icon-message-square');
                                            refreshIcons();
                                        }

                                        window.resetCustomerProfileFullscreen = resetFullscreenModes;
                                        window.showCustomerNotesPanel = showNotesPanel;
                                        window.hideCustomerNotesPanel = hideNotesPanel;
                                        window.minimizeCustomerSidebar = minimizeCustomerSidebar;
                                        window.expandCustomerSidebar = expandCustomerSidebar;

                                        if (mainBtn) {
                                            mainBtn.addEventListener('click', function (event) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                const isAlreadyFullscreen = layout.classList.contains('main-fullscreen-mode');

                                                resetFullscreenModes();

                                                if (!isAlreadyFullscreen) {
                                                    showNotesPanel();

                                                    layout.classList.add('main-fullscreen-mode');
                                                    contentStation.classList.add('main-fullscreen');

                                                    sidebar.classList.add('fullscreen-hidden');
                                                    rightPanel.classList.add('fullscreen-hidden');

                                                    setIcon(mainBtn, 'minimize-2', 'icon-minimize-2');
                                                }
                                            });
                                        }

                                        if (noteFullscreenBtn) {
                                            noteFullscreenBtn.addEventListener('click', function (event) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                const isAlreadyFullscreen = layout.classList.contains('notes-fullscreen-mode');

                                                resetFullscreenModes();

                                                if (!isAlreadyFullscreen) {
                                                    showNotesPanel();

                                                    layout.classList.add('notes-fullscreen-mode');
                                                    rightPanel.classList.add('notes-fullscreen');

                                                    sidebar.classList.add('fullscreen-hidden');
                                                    contentStation.classList.add('fullscreen-hidden');

                                                    setIcon(noteFullscreenBtn, 'minimize-2', 'icon-minimize-2');
                                                }
                                            });
                                        }

                                        if (noteHideBtn) {
                                            noteHideBtn.addEventListener('click', function (event) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                if (layout.classList.contains('notes-hidden-mode')) {
                                                    showNotesPanel();
                                                } else {
                                                    hideNotesPanel();
                                                }
                                            });
                                        }

                                        if (noteShowBtn) {
                                            noteShowBtn.addEventListener('click', function (event) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                showNotesPanel();
                                            });
                                        }

                                        document.addEventListener('click', function (event) {
                                            const shouldExpandSidebar =
                                                event.target.closest('.object-header') ||
                                                event.target.closest('.dashboard-btn');

                                            if (
                                                shouldExpandSidebar &&
                                                (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized'))
                                            ) {
                                                expandCustomerSidebar();
                                            }
                                        });

                                        window.toggleObject = function (id) {
                                            const target = document.getElementById(id);
                                            if (!target) return;

                                            if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                                expandCustomerSidebar();
                                            }

                                            const isOpen = target.classList.contains('show') || target.style.display === 'block';

                                            document.querySelectorAll('.product-list').forEach(function (el) {
                                                el.classList.remove('show');
                                                el.style.display = 'none';
                                            });

                                            document.querySelectorAll('.sub-nav').forEach(function (el) {
                                                el.classList.remove('show');
                                                el.style.display = 'none';
                                            });

                                            document.querySelectorAll('.project-link').forEach(function (el) {
                                                el.classList.remove('active');
                                            });

                                            if (!isOpen) {
                                                target.classList.add('show');
                                                target.style.display = 'block';
                                                target.setAttribute('aria-expanded', 'true');
                                            } else {
                                                target.classList.remove('show');
                                                target.style.display = 'none';
                                                target.setAttribute('aria-expanded', 'false');
                                            }

                                            refreshIcons();
                                        };

                                        window.toggleProduct = function (productKey) {
                                            const subNav = document.getElementById(productKey);
                                            const clicked = document.querySelector(`.project-link[data-product-key="${productKey}"]`);
                                            const parentId = productKey.match(/product(\d+)_\d+/)?.[1];
                                            const parentObjectList = document.getElementById(`object${parentId}`);
                                            const title = document.getElementById('note_title');

                                            if (title) title.textContent = 'NOTIZEN';

                                            if (!subNav || !clicked || !parentObjectList) return;

                                            if (layout.classList.contains('sidebar-minimized') || sidebar.classList.contains('minimized')) {
                                                expandCustomerSidebar();
                                            }

                                            const isOpen = subNav.classList.contains('show') || subNav.style.display === 'block';

                                            document.querySelectorAll('.sub-nav').forEach(function (el) {
                                                el.classList.remove('show');
                                                el.style.display = 'none';
                                            });

                                            document.querySelectorAll('.project-link').forEach(function (el) {
                                                el.classList.remove('active');
                                            });

                                            if (!isOpen) {
                                                parentObjectList.classList.add('show');
                                                parentObjectList.style.display = 'block';

                                                subNav.classList.add('show');
                                                subNav.style.display = 'block';

                                                clicked.classList.add('active');

                                                const customerId = clicked.dataset.objectCustomerId;
                                                const alternativeId = clicked.dataset.objectAlternativeId;
                                                const uniqueProductId = clicked.dataset.plId || clicked.dataset.objectProduct;
                                                const genericProductId = clicked.dataset.objectProduct;
                                                const noteList = document.getElementById('note-list');

                                                if (noteList && customerId && alternativeId && uniqueProductId) {
                                                    noteList.innerHTML = '<div class="text-muted p-3">Lade Notizen...</div>';

                                                    fetch(`/customer-notes/${customerId}/${alternativeId}/${uniqueProductId}`)
                                                        .then(function (res) {
                                                            if (!res.ok) throw new Error('Bad response');
                                                            return res.text();
                                                        })
                                                        .then(function (html) {
                                                            noteList.innerHTML = html;

                                                            noteList.dataset.customerId = customerId;
                                                            noteList.dataset.alternativeId = alternativeId;
                                                            noteList.dataset.uniqueId = uniqueProductId;
                                                            noteList.dataset.genericId = genericProductId;
                                                            noteList.dataset.noteType = 'product';

                                                            refreshIcons();

                                                            if (typeof initNoteListeners === 'function') {
                                                                initNoteListeners();
                                                            }
                                                        })
                                                        .catch(function () {
                                                            noteList.innerHTML = '<div class="text-danger p-3">Fehler beim Laden.</div>';
                                                        });
                                                }
                                            }

                                            refreshIcons();
                                        };

                                        document.querySelectorAll('.project-link[data-product-key]').forEach(function (link) {
                                            link.addEventListener('click', function (event) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                window.toggleProduct(this.dataset.productKey);
                                            });
                                        });

                                        window.addEventListener('resize', function () {
                                            autoSidebarMode();

                                            if (window.innerWidth < 992) {
                                                rightPanel.classList.add('right-hidden');
                                                layout.classList.add('notes-hidden-mode');

                                                if (noteShowBtn) {
                                                    noteShowBtn.classList.remove('d-none');
                                                }
                                            }
                                        });

                                        document.addEventListener('keydown', function (event) {
                                            if (event.key === 'Escape') {
                                                resetFullscreenModes();
                                            }
                                        });

                                        closeSidebarLists();
                                        autoSidebarMode();
                                        refreshIcons();
                                    });
                                    </script>
                                <!-- Maximize Toggle Buttons  -->
                                <script>
                                    function loadSectionPartial(customer_id, alternative_id, product_id, section) {
                                        const url = `/customer/partial/${customer_id}/${alternative_id}/${product_id}/${section}`;

                                        fetch(url)
                                            .then(response => {
                                                if (!response.ok) throw new Error('Fehler beim Laden des Abschnitts');
                                                return response.text();
                                            })
                                            .then(html => {
                                                document.getElementById('mainContent').innerHTML = html;

                                                // Optional: load extra sub-sections (partial wrappers)
                                            })
                                            .catch(error => {
                                                document.getElementById('mainContent').innerHTML =
                                                    `<div class="alert alert-danger">${error.message}</div>`;
                                            });
                                    }

                                </script>

                                <!-- Object Daten Script start.  -->
                                <script id="wizard-object-script">
                                    (() => {
                                        'use strict';

                                        // =========================================================
                                        // 1. KONFIGURATION
                                        // =========================================================

                                        const MAX_STEP = 6;

                                        // 1 = Übersicht, 2 = Objektdaten, 3 = Dach, 4 = Heizung, 5 = E-Mobilität, 6 = Energie
                                        const PRODUCT_TAB_MAP = {
                                            '17': [1, 2, 3, 6], // Photovoltaik
                                            '16': [1, 2, 4, 6], // Wärmepumpe
                                            '18': [1, 2, 5, 6], // Wallbox
                                            '31': [1, 2, 6],    // Batteriespeicher
                                            'default': [1, 2, 3, 4, 5, 6]
                                        };

                                        const SECTION_STEP_MAP = {
                                            object_data: 2,
                                            roof_info: 3,
                                            heating_info: 4,
                                            e_mobility: 5,
                                            energy_usage: 6
                                        };

                                        const FIELD_LABEL_MAP = {
                                            object_type: 'Objektart',
                                            building_condition: 'Zustand',
                                            usage_type: 'Nutzungsart',
                                            heated_area: 'Wohnfläche',
                                            number_we: 'Wohneinheiten',
                                            story_count: 'Geschosse',
                                            person_count: 'Personen',
                                            owner_count: 'Details zum Eigentümer',
                                            building_year: 'Baujahr',
                                            masonry: 'Mauerwerk',
                                            external_insulation_thickness: 'Dämmung',
                                            window_glazing: 'Fenster Verglasung',
                                            window_frame: 'Fenster Rahmen',
                                            window_year: 'Fenster Bj.',
                                            door_year: 'Tür Bj.',
                                            door_condition: 'Tür Zustand',
                                            object_remark: 'Bemerkung',

                                            heating_system_type: 'Technologie',
                                            heating_type: 'Wärmeübergabe',
                                            heating_load_calculation: 'Heizlast (kW)',
                                            heating_system_age: 'Alter (Jahre)',
                                            heating_circuits_count: 'Heizkreise',
                                            pipe_system_material: 'Rohrmaterial',
                                            pipe_system_count: 'Rohranzahl',
                                            chimney: 'Kamin',
                                            total_heat_consumption: 'Wärmebedarf p.a.',
                                            total_electricity_consumption: 'Strombedarf p.a.',
                                            consumption: 'Verbrauch',
                                            quantity: 'Menge',
                                            wood_consumption: 'Holz p.a.',
                                            hot_water_generation: 'Warmwasser',
                                            solar_thermal: 'Solarthermie',
                                            bathroom_count: 'Bäderanzahl',
                                            bathtub_count: 'Badewannen',
                                            installation_location: 'Aufstellungsort',
                                            installation_location_extra: 'Aufstellungsort Sonstiges',
                                            income_level: 'Einkommen',
                                            heating_remark: 'Bemerkung',

                                            electric_car: 'Elektroauto',
                                            electric_car_count: 'Anzahl Autos',
                                            car_kilo: 'Fahrleistung (p.a.)',
                                            company_vehicle: 'Firmenfahrzeug',
                                            bidirectional_car: 'Bidirektionales Laden',
                                            wallbox_count: 'Wallboxen',
                                            wallbox_location: 'Montageort',
                                            heavy_current_cable: 'Starkstromkabel',
                                            network_cable: 'Netzwerk / LAN',
                                            groundwork: 'Erdarbeiten',
                                            car_remark: 'Bemerkung',

                                            power_household: 'Haushaltsstrom (kWh)',
                                            power_heatpump: 'WP-Strom (kWh)',
                                            power_electric_car: 'E-Auto-Strom (kWh)',
                                            power_other: 'Sonstiges (kWh)',
                                            power_total: 'Gesamtverbrauch',
                                            meter_cabinet: 'Zählerschrank',
                                            meter_count: 'Anzahl Zähler',
                                            tenant_model: 'Mieterstrommodell',
                                            installation_location_power: 'Aufstellungsort (Technik)',
                                            network_wlan: 'Netzwerk / WLAN',
                                            energy_remark: 'Bemerkung'
                                        };

                                        const ROOF_FIELD_LABEL_MAP = {
                                            designation: 'Name der Fläche',
                                            type: 'Dachform',
                                            roof_type: 'Dachtyp',
                                            roof_orientation: 'Ausrichtung',
                                            roof_pitch: 'Neigung',
                                            roof_height: 'Traufhöhe (in Metern)',
                                            roof_covering_name: 'Eindeckung',
                                            roof_covering_company: 'Hersteller',
                                            roof_covering_model: 'Model',
                                            roof_age: 'Alter (Jahre)',
                                            roof_renovation: 'Sanierung nötig?',
                                            pv_existing: 'PV vorhanden?',
                                            kwp_size: 'Größe (kWp)',
                                            intention: 'Weiteres Vorgehen',
                                            notes: 'Bemerkungen zur Dachfläche'
                                        };

                                        // =========================================================
                                        // 2. HILFSFUNKTIONEN
                                        // =========================================================

                                        function refreshFeather() {
                                            if (typeof feather !== 'undefined') {
                                                feather.replace();
                                            }
                                        }

                                        function getStepButton(stepId) {
                                            return document.getElementById(`nav-${stepId}`);
                                        }

                                        function getStepContent(stepId) {
                                            return document.getElementById(`step-${stepId}`);
                                        }

                                        function getCurrentStepId() {
                                            const activeBtn = document.querySelector('.tab-btn.active');
                                            if (!activeBtn || !activeBtn.id) return 1;
                                            const match = activeBtn.id.match(/^nav-(\d+)$/);
                                            return match ? parseInt(match[1], 10) : 1;
                                        }

                                        function normalizeNumberString(value) {
                                            if (value === undefined || value === null) return 0;
                                            const parsed = parseFloat(String(value).trim().replace(',', '.'));
                                            return isNaN(parsed) || parsed < 0 ? 0 : parsed;
                                        }

                                        function getGermanFieldLabel(field) {
                                            if (!field) return 'Feld';

                                            const formGroup = field.closest('.form-group');
                                            if (formGroup) {
                                                const label = formGroup.querySelector('label.form-label');
                                                if (label) {
                                                    const cloned = label.cloneNode(true);
                                                    cloned.querySelectorAll('small, i').forEach(el => el.remove());
                                                    const text = (cloned.textContent || '').trim();
                                                    if (text) return text;
                                                }
                                            }

                                            if (field.id) {
                                                const explicitLabel = document.querySelector(`label[for="${field.id}"]`);
                                                if (explicitLabel) {
                                                    const cloned = explicitLabel.cloneNode(true);
                                                    cloned.querySelectorAll('small, i').forEach(el => el.remove());
                                                    const text = (cloned.textContent || '').trim();
                                                    if (text) return text;
                                                }
                                            }

                                            const rawName = field.name || field.id || 'Feld';
                                            const roofMatch = rawName.match(/^roofs\[\d+\]\[(.+)\]$/);
                                            if (roofMatch) {
                                                return ROOF_FIELD_LABEL_MAP[roofMatch[1]] || roofMatch[1];
                                            }

                                            return FIELD_LABEL_MAP[rawName] || rawName;
                                        }

                                        function findFieldByNameOrId(nameOrId) {
                                            try {
                                                return document.getElementById(nameOrId) || document.querySelector(`[name="${CSS.escape(nameOrId)}"]`);
                                            } catch (e) {
                                                return document.getElementById(nameOrId) || document.querySelector(`[name="${nameOrId}"]`);
                                            }
                                        }

                                        function showStepContent(stepId) {
                                            document.querySelectorAll('.step-content-box').forEach(el => el.classList.add('hidden'));
                                            const target = getStepContent(stepId);
                                            if (target) target.classList.remove('hidden');
                                        }

                                        function setActiveTab(stepId) {
                                            document.querySelectorAll('.tab-btn').forEach(btn => btn.classList.remove('active'));
                                            const targetBtn = getStepButton(stepId);
                                            if (targetBtn && !targetBtn.classList.contains('hidden')) {
                                                targetBtn.classList.add('active');
                                            }
                                        }

                                        function scrollStepWrapperToTop() {
                                            const wrapper = document.querySelector('.step-wrapper');
                                            if (wrapper) wrapper.scrollTop = 0;
                                        }

                                        function getNextVisibleStep(currentStep) {
                                            for (let i = currentStep + 1; i <= MAX_STEP; i++) {
                                                const btn = getStepButton(i);
                                                if (btn && !btn.classList.contains('hidden')) return i;
                                            }
                                            return null;
                                        }

                                        function getPrevVisibleStep(currentStep) {
                                            for (let i = currentStep - 1; i >= 1; i--) {
                                                const btn = getStepButton(i);
                                                if (btn && !btn.classList.contains('hidden')) return i;
                                            }
                                            return null;
                                        }

                                        function isFieldFilled(field) {
                                            if (!field) return false;

                                            if (field.type === 'checkbox' || field.type === 'radio') {
                                                return !!field.checked;
                                            }

                                            return !!(field.value && String(field.value).trim() !== '');
                                        }

                                        function toggleMissingSidebarIfMobile() {
                                            const sidebar = document.getElementById('missingDataSidebar');
                                            if (!sidebar) return;

                                            if (window.innerWidth <= 768 && sidebar.classList.contains('is-open')) {
                                                sidebar.classList.remove('is-open');
                                            }
                                        }

                                        function getSelectedProductIds(input) {
                                            if (!input) return [];

                                            if (Array.isArray(input)) {
                                                return input.map(v => String(v).trim()).filter(Boolean);
                                            }

                                            if (typeof input === 'string') {
                                                const trimmed = input.trim();
                                                if (!trimmed) return [];

                                                try {
                                                    const parsed = JSON.parse(trimmed);
                                                    if (Array.isArray(parsed)) {
                                                        return parsed.map(v => String(v).trim()).filter(Boolean);
                                                    }
                                                } catch (e) { }

                                                if (trimmed.includes(',')) {
                                                    return trimmed.split(',').map(v => String(v).trim()).filter(Boolean);
                                                }

                                                return [trimmed];
                                            }

                                            if (input instanceof HTMLSelectElement) {
                                                if (input.multiple) {
                                                    return Array.from(input.selectedOptions).map(opt => String(opt.value).trim()).filter(Boolean);
                                                }
                                                return input.value ? [String(input.value).trim()] : [];
                                            }

                                            if (typeof input === 'object' && input.value !== undefined) {
                                                return input.value ? [String(input.value).trim()] : [];
                                            }

                                            return [String(input).trim()].filter(Boolean);
                                        }

                                        function getAllowedTabsForProducts(productIds) {
                                            const ids = getSelectedProductIds(productIds);

                                            if (!ids.length) {
                                                return [...PRODUCT_TAB_MAP.default];
                                            }

                                            const merged = new Set();

                                            ids.forEach(productId => {
                                                const tabs = PRODUCT_TAB_MAP[String(productId)] || PRODUCT_TAB_MAP.default;
                                                tabs.forEach(step => merged.add(step));
                                            });

                                            return Array.from(merged).sort((a, b) => a - b);
                                        }

                                        function detectSelectedProductsFromDOM() {
                                            const productSelect = document.querySelector('.product-select');
                                            if (productSelect) {
                                                return getSelectedProductIds(productSelect);
                                            }

                                            const checkedProducts = Array.from(document.querySelectorAll('.product-select-checkbox:checked, input[name="product_id[]"]:checked, input[name="product_ids[]"]:checked'));
                                            if (checkedProducts.length) {
                                                return checkedProducts.map(el => String(el.value).trim()).filter(Boolean);
                                            }

                                            return [];
                                        }

                                        // =========================================================
                                        // 3. SMART TABS
                                        // =========================================================

                                        function applySmartTabs(productInput) {
                                            const allowedTabs = getAllowedTabsForProducts(productInput);

                                            document.querySelectorAll('.tab-btn').forEach((btn, index) => {
                                                const stepNum = index + 1;

                                                if (allowedTabs.includes(stepNum)) {
                                                    btn.classList.remove('hidden');
                                                } else {
                                                    btn.classList.add('hidden');
                                                }
                                            });

                                            const currentStep = getCurrentStepId();
                                            if (!allowedTabs.includes(currentStep)) {
                                                window.goToStep(1);
                                            } else {
                                                window.goToStep(currentStep);
                                            }

                                            setTimeout(window.updateProgressCounts, 100);
                                        }

                                        // =========================================================
                                        // 4. NAVIGATION
                                        // =========================================================

                                        window.goToStep = function (stepId) {
                                            const numericStep = parseInt(stepId, 10);
                                            if (isNaN(numericStep) || numericStep < 1 || numericStep > MAX_STEP) return;

                                            const btn = getStepButton(numericStep);
                                            if (btn && btn.classList.contains('hidden')) return;

                                            showStepContent(numericStep);
                                            setActiveTab(numericStep);
                                            scrollStepWrapperToTop();
                                            refreshFeather();
                                            window.updateProgressCounts();
                                        };

                                        window.goNext = function () {
                                            const currentStep = getCurrentStepId();
                                            const nextStep = getNextVisibleStep(currentStep);
                                            if (nextStep) window.goToStep(nextStep);
                                        };

                                        window.goPrev = function () {
                                            const currentStep = getCurrentStepId();
                                            const prevStep = getPrevVisibleStep(currentStep);
                                            if (prevStep) window.goToStep(prevStep);
                                        };

                                        window.toggleMissingSidebar = function () {
                                            const sidebar = document.getElementById('missingDataSidebar');
                                            if (sidebar) sidebar.classList.toggle('is-open');
                                        };

                                        window.focusField = function (nameOrId) {
                                            setTimeout(() => {
                                                const field = findFieldByNameOrId(nameOrId);
                                                if (!field) return;

                                                field.focus();
                                                field.scrollIntoView({ behavior: 'smooth', block: 'center' });

                                                const originalBackground = field.style.backgroundColor;
                                                const originalTransition = field.style.transition;

                                                field.style.transition = 'background-color 0.25s ease';
                                                field.style.backgroundColor = '#fef08a';

                                                setTimeout(() => {
                                                    field.style.backgroundColor = originalBackground;
                                                    field.style.transition = originalTransition;
                                                }, 1200);
                                            }, 300);
                                        };

                                        // =========================================================
                                        // 5. FEHLENDE DATEN + FORTSCHRITT
                                        // =========================================================

                                        window.updateProgressCounts = function () {
                                            const missingDataList = document.getElementById('missingDataList');
                                            const toggleBtn = document.getElementById('toggleMissingBtn');

                                            let missingHtml = '';
                                            let totalMissingAcrossWizard = 0;

                                            document.querySelectorAll('form.partial-form').forEach(form => {
                                                const section = form.dataset.section;
                                                const stepNum = SECTION_STEP_MAP[section];
                                                const tabBtn = getStepButton(stepNum);

                                                if (!stepNum || !tabBtn || tabBtn.classList.contains('hidden')) return;

                                                const counterEl = document.getElementById(`step${stepNum}-count`);
                                                const progressBar = document.getElementById(`step${stepNum}-progress`);
                                                const contentBox = form.closest('.step-content-box');

                                                const wasHidden = contentBox && contentBox.classList.contains('hidden');
                                                if (wasHidden) contentBox.classList.remove('hidden');

                                                const fields = form.querySelectorAll('input:not([type="hidden"]), select, textarea');
                                                let total = 0;
                                                let filled = 0;
                                                const missingFieldsInSection = [];

                                                fields.forEach(field => {
                                                    if (field.name === '_token') return;

                                                    total++;

                                                    if (isFieldFilled(field)) {
                                                        filled++;
                                                    } else {
                                                        missingFieldsInSection.push({
                                                            name: getGermanFieldLabel(field),
                                                            elementId: field.id || field.name || ''
                                                        });
                                                    }
                                                });

                                                if (wasHidden) contentBox.classList.add('hidden');

                                                if (total > 0) {
                                                    const percent = (filled / total) * 100;
                                                    if (counterEl) counterEl.textContent = `${filled}/${total}`;
                                                    if (progressBar) progressBar.style.width = `${percent}%`;
                                                }

                                                if (missingFieldsInSection.length > 0) {
                                                    totalMissingAcrossWizard += missingFieldsInSection.length;

                                                    const tabLabelEl = tabBtn.querySelector('.tab-label');
                                                    const tabLabel = tabLabelEl ? tabLabelEl.textContent.trim() : section;
                                                    const groupId = `missing-group-${stepNum}`;

                                                    const missingItemsHtml = missingFieldsInSection.map(field => `
                                                            <div class="missing-item" onclick="goToStep(${stepNum}); focusField('${String(field.elementId).replace(/'/g, "\\'")}'); toggleMissingSidebarIfMobile();">
                                                                <span class="missing-item-icon">
                                                                    <i class="feather icon-chevron-right"></i>
                                                                </span>
                                                                <span>${field.name}</span>
                                                            </div>
                                                        `).join('');

                                                    missingHtml += `
                                                            <div class="missing-group-card is-collapsed" id="${groupId}">
                                                                <div class="missing-group-head" onclick="toggleMissingGroup('${groupId}')">
                                                                    <div class="missing-group-left">
                                                                        <div class="missing-group-title">
                                                                            <i class="feather icon-folder"></i>
                                                                            ${tabLabel}
                                                                        </div>
                                                                        <div class="missing-group-meta">Karte aufklappen oder direkt den Tab öffnen</div>
                                                                    </div>

                                                                    <div class="missing-group-actions">
                                                                        <span class="missing-badge">${missingFieldsInSection.length}</span>

                                                                        <button
                                                                            type="button"
                                                                            class="missing-open-tab"
                                                                            onclick="event.stopPropagation(); goToStep(${stepNum}); toggleMissingSidebarIfMobile();"
                                                                        >
                                                                            Öffnen
                                                                        </button>

                                                                        <span class="missing-collapse-icon" onclick="event.stopPropagation(); toggleMissingGroup('${groupId}')">
                                                                            <i class="feather icon-chevron-down"></i>
                                                                        </span>
                                                                    </div>
                                                                </div>

                                                                <div class="missing-items">
                                                                    ${missingItemsHtml}
                                                                </div>
                                                            </div>
                                                        `;
                                                }
                                            });

                                            if (missingDataList) {
                                                missingDataList.innerHTML = missingHtml || `
                                                        <div class="missing-empty">
                                                            <i class="feather icon-check-circle"></i>
                                                            Alles komplett!
                                                        </div>
                                                    `;
                                            }

                                            if (toggleBtn) {
                                                toggleBtn.innerHTML = `
                                                        <i class="feather icon-check-square"></i>
                                                        Fehlendes (${totalMissingAcrossWizard})
                                                    `;

                                                toggleBtn.classList.remove('is-success');
                                                if (totalMissingAcrossWizard === 0) {
                                                    toggleBtn.classList.add('is-success');
                                                }
                                            }

                                            refreshFeather();
                                        };

                                        window.toggleMissingSidebarIfMobile = toggleMissingSidebarIfMobile;

                                        // =========================================================
                                        // 6. UI TOGGLES
                                        // =========================================================

                                        window.toggleRoofCard = function (headerElement) {
                                            const card = headerElement.closest('.fw-roof-card') || headerElement.closest('.roof-card') || headerElement.closest('.roof-group');
                                            const body = headerElement.nextElementSibling || (card ? card.querySelector('.fw-roof-body, .roof-body') : null);
                                            const icon = headerElement.querySelector('.toggle-icon');

                                            if (!body) return;

                                            const isHidden = body.style.display === 'none' || body.classList.contains('hidden');

                                            if (isHidden) {
                                                body.style.display = 'block';
                                                body.classList.remove('hidden');
                                                if (icon) icon.style.transform = 'rotate(0deg)';
                                                if (card) card.classList.remove('is-collapsed');
                                            } else {
                                                body.style.display = 'none';
                                                body.classList.add('hidden');
                                                if (icon) icon.style.transform = 'rotate(-90deg)';
                                                if (card) card.classList.add('is-collapsed');
                                            }
                                        };

                                        window.toggleMissingGroup = function (groupId) {
                                            const card = document.getElementById(groupId);
                                            if (!card) return;
                                            card.classList.toggle('is-collapsed');
                                        };

                                        function setupElectricCarToggle(root = document) {
                                            const electricCarSelect =
                                                root.querySelector('#electric_car_select') ||
                                                root.querySelector('#electric_car') ||
                                                root.querySelector('[name="electric_car"]');

                                            const electricCarCountGroup = root.querySelector('#electric_car_count_group');
                                            if (!electricCarSelect || !electricCarCountGroup) return;

                                            const updateVisibility = () => {
                                                if (electricCarSelect.value === 'Ja' || electricCarSelect.value === 'Geplant') {
                                                    electricCarCountGroup.style.display = 'flex';
                                                    electricCarCountGroup.style.flexDirection = 'column';
                                                } else {
                                                    electricCarCountGroup.style.display = 'none';
                                                }
                                            };

                                            electricCarSelect.addEventListener('change', updateVisibility);
                                            updateVisibility();
                                        }

                                        // =========================================================
                                        // 7. POWER CALCULATOR
                                        // =========================================================

                                        function initPowerCalculatorWithIDs(context = document) {
                                            const $context = $(context);
                                            const $household = $context.find('#power_household_input');
                                            const $heatpump = $context.find('#power_heatpump_input');
                                            const $electricCar = $context.find('#power_electric_car_input');
                                            const $other = $context.find('#power_other_input');
                                            const $total = $context.find('#power_total');
                                            const $totalHidden = $context.find('#power_total_hidden');

                                            function updateTotal() {
                                                if (!$total.length && !$totalHidden.length) return;

                                                const totalValue =
                                                    normalizeNumberString($household.val()) +
                                                    normalizeNumberString($heatpump.val()) +
                                                    normalizeNumberString($electricCar.val()) +
                                                    normalizeNumberString($other.val());

                                                if ($total.length) {
                                                    $total.val(totalValue.toFixed(2).replace('.', ','));
                                                }

                                                if ($totalHidden.length) {
                                                    $totalHidden.val(totalValue.toFixed(2));
                                                }

                                                let $year = $context.find('#power_total_year');
                                                if (!$year.length && $total.length) {
                                                    $year = $('<small id="power_total_year" style="color: var(--slate-400); margin-top: 0.25rem;"></small>');
                                                    $year.insertAfter($total);
                                                }

                                                if ($year.length) {
                                                    $year.text('≈ ' + (totalValue * 365).toLocaleString('de-DE') + ' kWh / Jahr');
                                                }
                                            }

                                            const $inputs = $household.add($heatpump).add($electricCar).add($other);
                                            if ($inputs.length) {
                                                $inputs.off('input.powercalc').on('input.powercalc', updateTotal);
                                                updateTotal();
                                            }
                                        }

                                        window.initPowerCalculatorWithIDs = initPowerCalculatorWithIDs;

                                        // =========================================================
                                        // 8. AJAX CONTENT LOAD
                                        // =========================================================

                                        window.loadFullAlternativeObject = function (button) {
                                            const customerId = button.dataset.customerId;
                                            const alternativeId = button.dataset.alternativeId;
                                            const productIds = button.dataset.productIds || button.dataset.productId || '';
                                            const mainContent = document.getElementById('mainContent');

                                            if (!mainContent) return;

                                            const url = `/customer/alternative/partials/${customerId}/${alternativeId}/${button.dataset.productId}/objekt`;

                                            mainContent.innerHTML = `
                                                    <div class="text-center py-4">
                                                        <span class="spinner-border spinner-border-sm"></span>
                                                        Lade Objektdaten...
                                                    </div>
                                                `;

                                            fetch(url)
                                                .then(response => {
                                                    if (!response.ok) {
                                                        throw new Error('Fehler beim Laden des Objekts');
                                                    }
                                                    return response.text();
                                                })
                                                .then(html => {
                                                    mainContent.innerHTML = html;

                                                    refreshFeather();
                                                    initPowerCalculatorWithIDs(mainContent);
                                                    setupElectricCarToggle(mainContent);

                                                    const detectedProducts = productIds ? getSelectedProductIds(productIds) : detectSelectedProductsFromDOM();
                                                    applySmartTabs(detectedProducts);

                                                    setTimeout(window.updateProgressCounts, 200);
                                                })
                                                .catch(error => {
                                                    mainContent.innerHTML = `<div class="alert alert-danger m-3">${error.message}</div>`;
                                                    console.error('Fehler beim Laden:', error);
                                                });
                                        };

                                        // =========================================================
                                        // 9. AJAX FORM SAVE
                                        // =========================================================

                                        function handlePartialFormSubmit(event) {
                                            const form = event.target;
                                            if (!form.classList.contains('partial-form')) return;

                                            event.preventDefault();

                                            const section = form.dataset.section;
                                            const id = form.dataset.id;
                                            const csrfInput = form.querySelector('input[name="_token"]');

                                            if (!csrfInput) {
                                                console.error('CSRF-Token fehlt.');
                                                return;
                                            }

                                            const formData = new FormData(form);
                                            formData.append('id', id);

                                            fetch('/new_lead_profile/alternative/object/save', {
                                                method: 'POST',
                                                headers: {
                                                    'X-CSRF-TOKEN': csrfInput.value
                                                },
                                                body: formData
                                            })
                                                .then(response => {
                                                    if (!response.ok) {
                                                        throw new Error('Fehler beim Speichern von ' + section);
                                                    }
                                                    return response.json();
                                                })
                                                .then(() => {
                                                    if (typeof Swal !== 'undefined') {
                                                        Swal.fire({
                                                            icon: 'success',
                                                            title: 'Gespeichert',
                                                            text: `Abschnitt "${section}" erfolgreich gespeichert.`
                                                        });
                                                    }
                                                    window.updateProgressCounts();
                                                })
                                                .catch(error => {
                                                    if (typeof Swal !== 'undefined') {
                                                        Swal.fire({
                                                            icon: 'error',
                                                            title: 'Fehler',
                                                            text: error.message
                                                        });
                                                    } else {
                                                        alert(error.message);
                                                    }
                                                });
                                        }

                                        // =========================================================
                                        // 10. EVENTS
                                        // =========================================================

                                        $(document).on('change', '.product-select', function () {
                                            applySmartTabs(this);
                                        });

                                        $(document).on('change', '.product-select-checkbox, input[name="product_id[]"], input[name="product_ids[]"]', function () {
                                            const selectedProducts = detectSelectedProductsFromDOM();
                                            applySmartTabs(selectedProducts);
                                        });

                                        document.body.addEventListener('submit', handlePartialFormSubmit);

                                        $(document).on('input change', 'form.partial-form input, form.partial-form select, form.partial-form textarea', function () {
                                            window.updateProgressCounts();
                                        });

                                        // =========================================================
                                        // 11. INIT
                                        // =========================================================

                                        function initWizard() {
                                            setupElectricCarToggle(document);
                                            initPowerCalculatorWithIDs(document);

                                            const selectedProducts = detectSelectedProductsFromDOM();
                                            if (selectedProducts.length) {
                                                applySmartTabs(selectedProducts);
                                            } else {
                                                applySmartTabs(PRODUCT_TAB_MAP.default);
                                            }

                                            setTimeout(window.updateProgressCounts, 300);
                                            refreshFeather();
                                        }

                                        document.addEventListener('DOMContentLoaded', initWizard);
                                    })();
                                </script>

                                <script id="84723">
                                    window.toggleMissingGroup = function (groupId) {
                                        const card = document.getElementById(groupId);
                                        if (!card) return;
                                        card.classList.toggle('is-collapsed');
                                    };
                                </script>
                                <!-- Object Daten Script start.  -->





                                <!-- Loading the checklists  -->
                                <script>
                                    function loadChecklist(button) {
                                        const customerId = button.dataset.customerId;
                                        const alternativeId = button.dataset.alternativeId;
                                        const productId = button.dataset.productId;
                                        const leadProductListId = button.dataset.productListId;

                                        const container = document.getElementById('mainContent');
                                        container.innerHTML = '<div class="p-3 text-center">Checkliste wird geladen...</div>';

                                        fetch('/lead-product-checklist/init', {
                                            method: 'POST',
                                            headers: {
                                                'Content-Type': 'application/json',
                                                'Accept': 'application/json',
                                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                            },
                                            body: JSON.stringify({
                                                customer_id: customerId,
                                                alternative_id: alternativeId,
                                                product_id: productId,
                                                lead_product_list_id: leadProductListId,
                                            })
                                        })
                                            .then(async res => {
                                                const text = await res.text();
                                                try {
                                                    return JSON.parse(text);
                                                } catch (e) {
                                                    container.innerHTML = `<pre style="color:red">${text}</pre>`;
                                                    throw e;
                                                }
                                            })
                                            .then(data => {
                                                if (data.success) {
                                                    container.innerHTML = `
                                                            <form id="customerChecklistForm" class="form-preview bg-white p-4">
                                                                <input type="hidden" name="lead_product_list_id" value="${leadProductListId}">
                                                                <input type="hidden" name="customer_id" value="${customerId}">
                                                                <input type="hidden" name="alternative_id" value="${alternativeId}">
                                                                <input type="hidden" name="product_id" value="${productId}">
                                                                ${data.html}
                                                                <button type="submit" class="btn btn-primary mt-3">Speichern</button>
                                                            </form>
                                                        `;

                                                    attachChecklistEvents();
                                                } else {
                                                    container.innerHTML = '<div class="alert alert-danger">Fehler beim Laden.</div>';
                                                }
                                            })
                                            .catch(err => {
                                                console.error('Fetch failed:', err);
                                                container.innerHTML = '<div class="alert alert-danger">Ein Fehler ist aufgetreten.</div>';
                                            });
                                    }

                                    function attachChecklistEvents() {
                                        const form = document.querySelector('#customerChecklistForm');
                                        if (!form) return;

                                        form.addEventListener('submit', submitChecklist);
                                        form.addEventListener('input', () => {
                                            evaluateFormulas();
                                            updateProgressBars();
                                        });

                                        evaluateFormulas();
                                        updateProgressBars();
                                    }

                                    function submitChecklist(e) {
                                        e.preventDefault();

                                        const form = document.getElementById('customerChecklistForm');
                                        const filledValues = {};
                                        const leadProductListId = form.querySelector('[name="lead_product_list_id"]').value;
                                        const customerId = form.querySelector('[name="customer_id"]').value;
                                        const alternativeId = form.querySelector('[name="alternative_id"]').value;
                                        const productId = form.querySelector('[name="product_id"]').value;

                                        form.querySelectorAll('input, select, textarea').forEach(input => {
                                            if (!input.name || input.classList.contains('formula-field')) return;
                                            const name = input.name.replace(/\[\]$/, '');

                                            if (input.type === 'checkbox') {
                                                filledValues[name] = input.checked ? 1 : 0;
                                            } else if (input.name.endsWith('[]')) {
                                                if (!Array.isArray(filledValues[name])) filledValues[name] = [];
                                                filledValues[name].push(input.value);
                                            } else {
                                                filledValues[name] = input.value;
                                            }
                                        });

                                        fetch('/lead-product-checklist/save', {
                                            method: 'POST',
                                            headers: {
                                                'Content-Type': 'application/json',
                                                'Accept': 'application/json',
                                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                            },
                                            body: JSON.stringify({
                                                lead_product_list_id: leadProductListId,
                                                filled_values: filledValues,
                                                customer_id: customerId,
                                                alternative_id: alternativeId,
                                                product_id: productId
                                            })
                                        })
                                            .then(res => res.json())
                                            .then(data => {
                                                if (data.success) {
                                                    Swal.fire('Gespeichert', 'Die Daten wurden erfolgreich gespeichert.', 'success');
                                                } else {
                                                    Swal.fire('Fehler', data.message || 'Daten konnten nicht gespeichert werden.', 'error');
                                                }
                                            })
                                            .catch(err => {
                                                console.error(err);
                                                Swal.fire('Fehler', 'Ein Fehler ist aufgetreten.', 'error');
                                            });
                                    }

                                    function evaluateFormulas() {
                                        const values = {};

                                        document.querySelectorAll('#customerChecklistForm input, #customerChecklistForm select, #customerChecklistForm textarea')
                                            .forEach(input => {
                                                if (!input.name || input.classList.contains('formula-field')) return;
                                                values[input.name] = input.type === 'checkbox' ? (input.checked ? 1 : 0) : input.value;
                                            });

                                        document.querySelectorAll('.formula-field').forEach(field => {
                                            const formula = field.dataset.formula;
                                            const result = evaluateFormula(formula, values);
                                            field.value = isNaN(result) ? 'Fehler' : result;
                                        });
                                    }

                                    function evaluateFormula(formula, values) {
                                        try {
                                            const fns = { add, sub, mul, div, round, min, max, toNum };
                                            const valKeys = Object.keys(values).filter(key => /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(key));
                                            const valVals = valKeys.map(k => toNum(values[k]));

                                            const fnKeys = Object.keys(fns);
                                            const fnVals = Object.values(fns);

                                            const fn = new Function(...fnKeys, ...valKeys, `return ${formula}`);
                                            return fn(...fnVals, ...valVals);
                                        } catch (e) {
                                            console.warn('Formula error:', formula, e);
                                            return 'Fehler';
                                        }
                                    }

                                    function toNum(val) {
                                        return val === '' || val == null || isNaN(val) ? 0 : Number(val);
                                    }
                                    function add(a, b) { return toNum(a) + toNum(b); }
                                    function sub(a, b) { return toNum(a) - toNum(b); }
                                    function mul(a, b) { return toNum(a) * toNum(b); }
                                    function div(a, b) { const d = toNum(b); return d === 0 ? 0 : toNum(a) / d; }
                                    function round(v, p = 0) { return Math.round(toNum(v) * 10 ** p) / 10 ** p; }
                                    function min(...args) { return Math.min(...args.map(toNum)); }
                                    function max(...args) { return Math.max(...args.map(toNum)); }

                                    function updateProgressBars() {
                                        document.querySelectorAll('.accordion-section').forEach(section => {
                                            const inputs = section.querySelectorAll('input, select, textarea');
                                            let total = 0;
                                            let filled = 0;

                                            inputs.forEach(input => {
                                                if (!input.name || input.classList.contains('formula-field')) return;
                                                total++;
                                                const isFilled = input.type === 'checkbox' ? input.checked : input.value !== '';
                                                if (isFilled) filled++;
                                            });

                                            const percent = total > 0 ? Math.round((filled / total) * 100) : 0;
                                            const bar = section.querySelector('.progress-bar');

                                            if (bar) {
                                                bar.style.width = percent + '%';
                                                bar.setAttribute('aria-valuenow', percent);
                                                bar.innerText = percent + '%';
                                            }
                                        });
                                    }
                                </script>

                    <!-- Document and PIcutre :start -->
                    <script> 
                        (() => {
                            "use strict";

                            const CONFIG = {
                                ROOT_ID: "docsShell",
                                MAIN_CONTENT_ID: "mainContent",
                                LS_VIEW_KEY: "docs.view.mode",

                                ENDPOINTS: {
                                    load: "/document/load",
                                    delete: (id) => `/document/delete/${id}`,
                                    rename: "/document/rename",
                                    updateDetails: "{{ route('document.updateDetails') }}",
                                },

                                TAB_LINKS: "#galleryTabs .nav-link",
                                TAB_PANES: "#galleryTabsContent .tab-pane",
                                SEARCH_INPUT: "#searchImage",
                                STAGE_FILTER: "#stageFilter",

                                DOC_TYPES: {
                                    customer: "Kunde",
                                    montage: "Montage",
                                    Reklamation: "Reklamation",
                                    Rechnung: "Rechnung",
                                    Auftrag: "Auftrag",
                                    AuftragBeshtitgung: "Auftragsbestätigung",
                                    Angebot: "Angebot",
                                    Wartung: "Wartung",
                                    Ticket: "Ticket",
                                    end: "Abgeschlossen",
                                    Other: "Sonstiges",
                                },
                            };

                            const state = {
                                glb: null,
                                lastActiveButton: null,
                            };

                            window.currentDocumentContext = window.currentDocumentContext || {
                                customerId: "",
                                alternativeId: "",
                                productId: "",
                                productListId: "",
                            };

                            window.customerDocumentProductsByAlternative = window.customerDocumentProductsByAlternative || {};

                            const getCsrf = () => {
                                return document.querySelector('meta[name="csrf-token"]')?.getAttribute("content") || "";
                            };

                            const $ = (selector, root = document) => root.querySelector(selector);

                            const $$ = (selector, root = document) => {
                                return Array.from(root.querySelectorAll(selector));
                            };

                            const escapeHtml = (value) => {
                                return String(value ?? "")
                                    .replace(/&/g, "&amp;")
                                    .replace(/</g, "&lt;")
                                    .replace(/>/g, "&gt;")
                                    .replace(/"/g, "&quot;")
                                    .replace(/'/g, "&#039;");
                            };

                            const getActivePane = (root = document) => {
                                return $(`${CONFIG.TAB_PANES}.active`, root) || $("#allTab", root);
                            };

                            const getCurrentUiState = (opts = {}) => {
                                const shell = document.getElementById(CONFIG.ROOT_ID);

                                return {
                                    tab: opts.keepTab !== false
                                        ? ($(`${CONFIG.TAB_LINKS}.active`)?.getAttribute("data-tab") || "#allTab")
                                        : "#allTab",

                                    search: opts.keepFilters !== false
                                        ? ($(CONFIG.SEARCH_INPUT)?.value || "")
                                        : "",

                                    stage: opts.keepFilters !== false
                                        ? ($(CONFIG.STAGE_FILTER)?.value || "")
                                        : "",

                                    view: opts.keepView !== false
                                        ? (shell?.dataset.view || localStorage.getItem(CONFIG.LS_VIEW_KEY) || "grid")
                                        : "grid",
                                };
                            };

                            const restoreUiState = (uiState, root = document) => {
                                setView(uiState.view, root);

                                const searchInput = $(CONFIG.SEARCH_INPUT, root);
                                const stageFilter = $(CONFIG.STAGE_FILTER, root);

                                if (searchInput) searchInput.value = uiState.search;
                                if (stageFilter) stageFilter.value = uiState.stage;

                                const savedTab = $(
                                    `${CONFIG.TAB_LINKS}[data-tab="${uiState.tab}"], ${CONFIG.TAB_LINKS}[href="${uiState.tab}"]`,
                                    root
                                );

                                if (savedTab) {
                                    savedTab.click();
                                } else {
                                    applyFilters(root);
                                }
                            };

                            const normalizeDatasetButton = (buttonOrDataset = {}) => {
                                const dataset = buttonOrDataset.dataset || buttonOrDataset || {};

                                return {
                                    customerId: dataset.customerId || dataset.customer_id || "",
                                    alternativeId: dataset.alternativeId || dataset.alternative_id || "",
                                    productId: dataset.productId || dataset.product_id || "",
                                    productListId: dataset.productListId || dataset.product_list_id || "",
                                };
                            };

                            const setCurrentDocumentContext = (ctx = {}) => {
                                window.currentDocumentContext = {
                                    customerId: ctx.customerId || "",
                                    alternativeId: ctx.alternativeId || "",
                                    productId: ctx.productId || "",
                                    productListId: ctx.productListId || "",
                                };
                            };

                            const getCurrentCustomerId = () => {
                                return window.currentDocumentContext?.customerId
                                    || document.querySelector('input[name="customer_id"]')?.value
                                    || "";
                            };

                            const getCurrentAlternativeId = () => {
                                return window.currentDocumentContext?.alternativeId
                                    || document.querySelector('input[name="alternative_id"]')?.value
                                    || "";
                            };

                            const getCurrentProductId = () => {
                                return window.currentDocumentContext?.productId
                                    || document.getElementById("image_product")?.value
                                    || "";
                            };

                            const getProductsForCurrentAlternative = () => {
                                const alternativeId = getCurrentAlternativeId();

                                let products = window.customerDocumentProductsByAlternative?.[String(alternativeId)] || [];

                                if (Array.isArray(products) && products.length) {
                                    return products
                                        .filter(p => p && p.id)
                                        .map(p => ({
                                            id: String(p.id),
                                            name: p.name || `Produkt #${p.id}`,
                                        }));
                                }

                                const productSelect = document.getElementById("image_product");

                                if (productSelect && productSelect.tagName === "SELECT") {
                                    return Array.from(productSelect.options)
                                        .filter(option => option.value)
                                        .map(option => ({
                                            id: String(option.value),
                                            name: option.textContent.trim() || `Produkt #${option.value}`,
                                        }));
                                }

                                const productId = getCurrentProductId();

                                if (productId) {
                                    return [{
                                        id: String(productId),
                                        name: `Produkt #${productId}`,
                                    }];
                                }

                                return [];
                            };

                            const buildStageOptions = (currentStage = "") => {
                                return Object.entries(CONFIG.DOC_TYPES)
                                    .map(([key, label]) => {
                                        const selected = String(currentStage) === String(key) ? "selected" : "";

                                        return `
                                            <option value="${escapeHtml(key)}" ${selected}>
                                                ${escapeHtml(label)}
                                            </option>
                                        `;
                                    })
                                    .join("");
                            };

                            const buildProductOptions = (currentArticleGroup = "") => {
                                const products = getProductsForCurrentAlternative();
                                const currentValue = String(currentArticleGroup || "");

                                let options = `<option value="">Produkt wählen</option>`;

                                products.forEach(product => {
                                    const selected = currentValue === String(product.id) ? "selected" : "";

                                    options += `
                                        <option value="${escapeHtml(product.id)}" ${selected}>
                                            ${escapeHtml(product.name)}
                                        </option>
                                    `;
                                });

                                if (currentValue && !products.some(p => String(p.id) === currentValue)) {
                                    options += `
                                        <option value="${escapeHtml(currentValue)}" selected>
                                            Produkt #${escapeHtml(currentValue)}
                                        </option>
                                    `;
                                }

                                return options;
                            };

                            const setView = (view, root = document) => {
                                const shell = document.getElementById(CONFIG.ROOT_ID);
                                if (!shell) return;

                                const normalizedView = view === "list" ? "list" : "grid";

                                shell.dataset.view = normalizedView;
                                localStorage.setItem(CONFIG.LS_VIEW_KEY, normalizedView);

                                $$(".view-btn", root).forEach(btn => {
                                    btn.classList.toggle("is-active", btn.dataset.view === normalizedView);
                                });
                            };

                            const applyFilters = (root = document) => {
                                const keyword = ($(CONFIG.SEARCH_INPUT, root)?.value || "").trim().toLowerCase();
                                const stage = ($(CONFIG.STAGE_FILTER, root)?.value || "").trim();
                                const pane = getActivePane(root);

                                if (!pane) return;

                                $$(".gallery-item", pane).forEach(item => {
                                    const name = (item.dataset.name || "").toLowerCase();
                                    const type = (item.dataset.type || item.dataset.ext || "").toLowerCase();
                                    const itemStage = item.dataset.stage || "";
                                    const dateRaw = item.dataset.date || "";
                                    const date = dateRaw
                                        ? new Date(dateRaw).toLocaleDateString("de-DE").toLowerCase()
                                        : "";

                                    const matchesSearch = !keyword || `${name} ${type} ${date}`.includes(keyword);
                                    const matchesStage = !stage || itemStage === stage;

                                    item.style.display = matchesSearch && matchesStage ? "" : "none";
                                });
                            };

                            const initLightbox = (root = document) => {
                                if (typeof GLightbox === "undefined") return;

                                if (state.glb) {
                                    state.glb.destroy();
                                }

                                state.glb = GLightbox({
                                    selector: `#${CONFIG.ROOT_ID} .glightbox`,
                                    loop: true,
                                    openEffect: "zoom",
                                    closeEffect: "fade",
                                });
                            };

                            const initTabs = (root = document) => {
                                const tabs = $$(CONFIG.TAB_LINKS, root);
                                const panes = $$(CONFIG.TAB_PANES, root);

                                tabs.forEach(tab => {
                                    tab.onclick = (event) => {
                                        event.preventDefault();

                                        const targetId = tab.getAttribute("data-tab") || tab.getAttribute("href");
                                        const targetPane = $(targetId, root);

                                        if (!targetPane) return;

                                        tabs.forEach(t => t.classList.remove("active"));
                                        panes.forEach(p => p.classList.remove("show", "active"));

                                        tab.classList.add("active");
                                        targetPane.classList.add("show", "active");

                                        applyFilters(root);
                                        initLightbox(root);
                                    };
                                });
                            };

                            const initControls = (root = document) => {
                                $$(".view-btn", root).forEach(btn => {
                                    btn.onclick = () => setView(btn.dataset.view, root);
                                });

                                const searchInput = $(CONFIG.SEARCH_INPUT, root);
                                const stageFilter = $(CONFIG.STAGE_FILTER, root);

                                if (searchInput) searchInput.oninput = () => applyFilters(root);
                                if (stageFilter) stageFilter.onchange = () => applyFilters(root);
                            };

                            const initDocumentUi = (root = document) => {
                                initTabs(root);
                                initControls(root);
                                initLightbox(root);
                                applyFilters(root);
                            };

                            window.loadDocuments = async function (button, opts = {}) {
                                const container = document.getElementById(CONFIG.MAIN_CONTENT_ID);
                                if (!container) return;

                                const ctx = normalizeDatasetButton(button);

                                state.lastActiveButton = button;
                                setCurrentDocumentContext(ctx);

                                const currentUiState = getCurrentUiState(opts);

                                container.innerHTML = `
                                    <div class="p-3 text-center">
                                        <i class="fa fa-spinner fa-spin"></i> Dokumente werden geladen...
                                    </div>
                                `;

                                try {
                                    const response = await fetch(CONFIG.ENDPOINTS.load, {
                                        method: "POST",
                                        headers: {
                                            "Content-Type": "application/json",
                                            "Accept": "text/html",
                                            "X-CSRF-TOKEN": getCsrf(),
                                        },
                                        body: JSON.stringify({
                                            customer_id: ctx.customerId,
                                            alternative_id: ctx.alternativeId,
                                            product_id: ctx.productId,
                                            product_list_id: ctx.productListId,
                                        }),
                                    });

                                    if (!response.ok) {
                                        throw new Error("Dokumente konnten nicht geladen werden.");
                                    }

                                    const html = await response.text();
                                    container.innerHTML = html;

                                    const productInput = document.getElementById("image_product");

                                    if (productInput && productInput.tagName !== "SELECT") {
                                        productInput.value = ctx.productId || "";
                                    }

                                    const newRoot = document.getElementById(CONFIG.ROOT_ID) || document;

                                    initDocumentUi(newRoot);

                                    if (typeof initDropzone === "function") {
                                        initDropzone(button);
                                    }

                                    restoreUiState(currentUiState, newRoot);
                                } catch (error) {
                                    console.error("Fetch error:", error);

                                    container.innerHTML = `
                                        <div class="text-danger p-3">
                                            Fehler beim Laden der Dokumente.
                                        </div>
                                    `;
                                }
                            };

                            window.deleteDocument = async function (id, docType, element) {
                                const result = await Swal.fire({
                                    title: "Löschen bestätigen",
                                    text: "Willst du dieses Dokument wirklich löschen?",
                                    icon: "warning",
                                    showCancelButton: true,
                                    confirmButtonText: "Ja, löschen",
                                    cancelButtonText: "Abbrechen",
                                    confirmButtonColor: "#dc2626",
                                    cancelButtonColor: "#64748b",
                                });

                                if (!result.isConfirmed) return;

                                try {
                                    const response = await fetch(CONFIG.ENDPOINTS.delete(id), {
                                        method: "DELETE",
                                        headers: {
                                            "Accept": "application/json",
                                            "X-CSRF-TOKEN": getCsrf(),
                                        },
                                    });

                                    const data = await response.json();

                                    if (!response.ok || !data.success) {
                                        throw data;
                                    }

                                    element?.closest(".gallery-item")?.remove();

                                    Swal.fire({
                                        icon: "success",
                                        title: "Gelöscht",
                                        timer: 900,
                                        showConfirmButton: false,
                                    });
                                } catch (error) {
                                    console.error("Delete failed:", error);

                                    Swal.fire({
                                        icon: "error",
                                        title: "Fehler",
                                        text: error?.message || "Löschen fehlgeschlagen.",
                                    });
                                }
                            };

                            window.renameDocument = async function (id, newName) {
                                try {
                                    const response = await fetch(CONFIG.ENDPOINTS.rename, {
                                        method: "POST",
                                        headers: {
                                            "Content-Type": "application/json",
                                            "Accept": "application/json",
                                            "X-CSRF-TOKEN": getCsrf(),
                                        },
                                        body: JSON.stringify({
                                            id: id,
                                            image_name: newName,
                                        }),
                                    });

                                    const data = await response.json();

                                    if (!response.ok || !data.success) {
                                        throw data;
                                    }

                                    Swal.fire({
                                        icon: "success",
                                        title: "Umbenannt",
                                        timer: 900,
                                        showConfirmButton: false,
                                    });
                                } catch (error) {
                                    console.error("Rename failed:", error);

                                    Swal.fire({
                                        icon: "error",
                                        title: "Fehler",
                                        text: error?.message || "Fehler beim Umbenennen.",
                                    });
                                }
                            };

                            window.editDocumentDetails = function (
                                id,
                                currentName,
                                currentStage,
                                currentArticleGroup = null
                            ) {
                                const stageOptionsHtml = buildStageOptions(currentStage);
                                const productOptionsHtml = buildProductOptions(currentArticleGroup);

                                Swal.fire({
                                    title: "Dokument bearbeiten",
                                    width: 620,
                                    focusConfirm: false,
                                    showCancelButton: true,
                                    confirmButtonText: "Speichern",
                                    cancelButtonText: "Abbrechen",
                                    confirmButtonColor: "#93c11c",
                                    cancelButtonColor: "#64748b",
                                    customClass: {
                                        popup: "doc-edit-swal",
                                        title: "doc-edit-swal-title",
                                        htmlContainer: "doc-edit-swal-html",
                                        confirmButton: "doc-edit-swal-confirm",
                                        cancelButton: "doc-edit-swal-cancel",
                                    },
                                    html: `
                                        <style>
                                            .doc-edit-form {
                                                text-align: left;
                                                display: grid;
                                                gap: 16px;
                                                padding-top: 6px;
                                            }

                                            .doc-edit-card {
                                                border: 1px solid #e2e8f0;
                                                background: #f8fafc;
                                                border-radius: 14px;
                                                padding: 14px;
                                            }

                                            .doc-edit-grid {
                                                display: grid;
                                                grid-template-columns: 1fr 1fr;
                                                gap: 14px;
                                            }

                                            .doc-edit-field {
                                                display: flex;
                                                flex-direction: column;
                                                gap: 6px;
                                            }

                                            .doc-edit-label {
                                                font-size: 12px;
                                                font-weight: 800;
                                                color: #334155;
                                                margin: 0;
                                            }

                                            .doc-edit-help {
                                                font-size: 11px;
                                                color: #64748b;
                                                margin-top: 3px;
                                            }

                                            .doc-edit-input,
                                            .doc-edit-select {
                                                width: 100%;
                                                height: 42px;
                                                border: 1px solid #cbd5e1;
                                                border-radius: 10px;
                                                padding: 8px 11px;
                                                font-size: 13px;
                                                color: #0f172a;
                                                background: #fff;
                                                outline: none;
                                                box-shadow: none;
                                            }

                                            .doc-edit-input:focus,
                                            .doc-edit-select:focus {
                                                border-color: #93c11c;
                                                box-shadow: 0 0 0 3px rgba(147, 193, 28, 0.16);
                                            }

                                            .doc-edit-section-title {
                                                display: flex;
                                                align-items: center;
                                                gap: 8px;
                                                font-size: 13px;
                                                font-weight: 900;
                                                color: #0f172a;
                                                margin-bottom: 10px;
                                            }

                                            .doc-edit-badge {
                                                display: inline-flex;
                                                align-items: center;
                                                justify-content: center;
                                                width: 24px;
                                                height: 24px;
                                                border-radius: 999px;
                                                background: #ecfccb;
                                                color: #4d7c0f;
                                                font-size: 12px;
                                                font-weight: 900;
                                            }

                                            @media (max-width: 640px) {
                                                .doc-edit-grid {
                                                    grid-template-columns: 1fr;
                                                }
                                            }
                                        </style>

                                        <div class="doc-edit-form">
                                            <div class="doc-edit-card">
                                                <div class="doc-edit-section-title">
                                                    <span class="doc-edit-badge">1</span>
                                                    Allgemeine Datei-Informationen
                                                </div>

                                                <div class="doc-edit-field">
                                                    <label for="swal-edit-name" class="doc-edit-label">Dateiname</label>
                                                    <input
                                                        id="swal-edit-name"
                                                        class="doc-edit-input"
                                                        value="${escapeHtml(currentName)}"
                                                        placeholder="Dateiname eingeben"
                                                    >
                                                    <div class="doc-edit-help">
                                                        Der Dateiname wird in der Dokumentenübersicht angezeigt.
                                                    </div>
                                                </div>
                                            </div>

                                            <div class="doc-edit-card">
                                                <div class="doc-edit-section-title">
                                                    <span class="doc-edit-badge">2</span>
                                                    Zuordnung
                                                </div>

                                                <div class="doc-edit-grid">
                                                    <div class="doc-edit-field">
                                                        <label for="swal-edit-stage" class="doc-edit-label">Kategorie / Typ</label>
                                                        <select id="swal-edit-stage" class="doc-edit-select">
                                                            ${stageOptionsHtml}
                                                        </select>
                                                    </div>

                                                    <div class="doc-edit-field">
                                                        <label for="swal-edit-article-group" class="doc-edit-label">
                                                            Produkt / Artikelgruppe
                                                        </label>
                                                        <select id="swal-edit-article-group" class="doc-edit-select">
                                                            ${productOptionsHtml}
                                                        </select>
                                                    </div>
                                                </div>

                                                <div class="doc-edit-help">
                                                    Hier kannst du das Dokument von einem Produkt zu einem anderen Produkt verschieben.
                                                </div>
                                            </div>
                                        </div>
                                    `,
                                    preConfirm: () => {
                                        const name = document.getElementById("swal-edit-name")?.value.trim();
                                        const stage = document.getElementById("swal-edit-stage")?.value;
                                        const articleGroup = document.getElementById("swal-edit-article-group")?.value;

                                        if (!name) {
                                            Swal.showValidationMessage("Name darf nicht leer sein.");
                                            return false;
                                        }

                                        if (!stage) {
                                            Swal.showValidationMessage("Bitte Kategorie / Typ wählen.");
                                            return false;
                                        }

                                        if (!articleGroup) {
                                            Swal.showValidationMessage("Bitte Produkt / Artikelgruppe wählen.");
                                            return false;
                                        }

                                        return {
                                            id: id,
                                            image_name: name,
                                            stage: stage,
                                            article_group: articleGroup,
                                        };
                                    },
                                }).then(async (result) => {
                                    if (!result.isConfirmed) return;

                                    try {
                                        Swal.fire({
                                            title: "Wird gespeichert...",
                                            allowOutsideClick: false,
                                            didOpen: () => Swal.showLoading(),
                                        });

                                        const response = await fetch(CONFIG.ENDPOINTS.updateDetails, {
                                            method: "POST",
                                            headers: {
                                                "Content-Type": "application/json",
                                                "Accept": "application/json",
                                                "X-CSRF-TOKEN": getCsrf(),
                                            },
                                            body: JSON.stringify(result.value),
                                        });

                                        const data = await response.json();

                                        if (!response.ok || !data.success) {
                                            throw data;
                                        }

                                        await Swal.fire({
                                            icon: "success",
                                            title: "Aktualisiert",
                                            timer: 900,
                                            showConfirmButton: false,
                                        });

                                        const customerId = getCurrentCustomerId();
                                        const alternativeId = getCurrentAlternativeId();

                                        const reloadProductId = result.value.article_group;

                                        setCurrentDocumentContext({
                                            customerId: customerId,
                                            alternativeId: alternativeId,
                                            productId: reloadProductId,
                                            productListId: "",
                                        });

                                        if (typeof window.loadDocuments === "function") {
                                            window.loadDocuments({
                                                dataset: {
                                                    customerId: customerId,
                                                    alternativeId: alternativeId,
                                                    productId: reloadProductId,
                                                    productListId: "",
                                                },
                                            }, {
                                                keepTab: true,
                                                keepFilters: true,
                                                keepView: true,
                                            });
                                        }
                                    } catch (error) {
                                        console.error("Update failed:", error);

                                        Swal.fire({
                                            icon: "error",
                                            title: "Fehler",
                                            text: error?.message || "Die Daten konnten nicht aktualisiert werden.",
                                        });
                                    }
                                });
                            };

                            document.addEventListener("DOMContentLoaded", () => {
                                const root = document.getElementById(CONFIG.ROOT_ID) || document;
                                initDocumentUi(root);
                            });
                        })();
                    </script>

                                <script>
                                    // PDF Viewer Logic
                                    window.openPdfViewer = function (url, title) {
                                        document.getElementById('pdfViewerTitle').textContent = title || 'Dokument';
                                        document.getElementById('pdfViewerIframe').src = url;

                                        const modal = document.getElementById('pdfViewerModal');
                                        modal.classList.add('is-open');
                                        modal.setAttribute('aria-hidden', 'false');
                                        document.body.classList.add('cmodal-open');
                                    };

                                    window.closePdfViewer = function () {
                                        const modal = document.getElementById('pdfViewerModal');
                                        modal.classList.remove('is-open');
                                        modal.setAttribute('aria-hidden', 'true');

                                        if (!document.querySelectorAll('.cmodal.is-open').length) {
                                            document.body.classList.remove('cmodal-open');
                                        }

                                        setTimeout(() => {
                                            document.getElementById('pdfViewerIframe').src = '';
                                        }, 300);
                                    };

                                    // Ensure Escape key also closes the PDF viewer
                                    document.addEventListener('keydown', function (e) {
                                        if (e.key === 'Escape' && document.getElementById('pdfViewerModal').classList.contains('is-open')) {
                                            closePdfViewer();
                                        }
                                    });
                                </script>

                                <script>
                                    (() => {
                                        "use strict";

                                        // -----------------------------
                                        // Helpers
                                        // -----------------------------
                                        const $ = (sel, root = document) => root.querySelector(sel);

                                        const getCsrf = () =>
                                            $('meta[name="csrf-token"]')?.getAttribute("content") || "";

                                        const normalizeError = (msg) => {
                                            if (msg == null) return "Upload fehlgeschlagen.";
                                            if (typeof msg === "string") return msg;
                                            if (Array.isArray(msg)) return msg.filter(Boolean).join("\n") || "Upload fehlgeschlagen.";
                                            if (typeof msg === "object") {
                                                // Dropzone sometimes passes an object
                                                try { return JSON.stringify(msg); } catch (_) { }
                                            }
                                            return String(msg);
                                        };

                                        const parseLaravel422 = (xhr) => {
                                            try {
                                                const j = JSON.parse(xhr?.responseText || "{}");

                                                // typical Laravel JSON: { message, errors: { field: [..] } }
                                                if (j?.errors && typeof j.errors === "object") {
                                                    const lines = [];
                                                    Object.keys(j.errors).forEach((k) => {
                                                        const arr = j.errors[k];
                                                        if (Array.isArray(arr)) lines.push(...arr);
                                                    });
                                                    if (lines.length) return lines.join("\n");
                                                }

                                                if (j?.message) return String(j.message);
                                                return "Validierung fehlgeschlagen.";
                                            } catch (_) {
                                                return "Validierung fehlgeschlagen.";
                                            }
                                        };

                                        const swalOk = (title) => {
                                            if (typeof Swal === "undefined") return;
                                            Swal.fire({
                                                target: document.body,
                                                icon: "success",
                                                title,
                                                timer: 900,
                                                showConfirmButton: false,
                                            });
                                        };

                                        const swalErr = (title, text) => {
                                            if (typeof Swal === "undefined") return;
                                            Swal.fire({
                                                target: document.body,
                                                icon: "error",
                                                title,
                                                text: text || "Upload fehlgeschlagen.",
                                            });
                                        };

                                        const swalWarn = (title, text) => {
                                            if (typeof Swal === "undefined") return;
                                            Swal.fire({
                                                target: document.body,
                                                icon: "warning",
                                                title,
                                                text: text || "",
                                            });
                                        };

                                        // -----------------------------
                                        // Dropzone init
                                        // -----------------------------
                                        function initDropzone(button) {
                                            if (typeof Dropzone === "undefined") return;

                                            const form = document.getElementById("documentDropzone");
                                            if (!form) return;

                                            Dropzone.autoDiscover = false;

                                            // destroy previous instance
                                            if (window.__docsDz) {
                                                try { window.__docsDz.destroy(); } catch (_) { }
                                                window.__docsDz = null;
                                            }

                                            const dz = new Dropzone(form, {
                                                url: form.getAttribute("action"),
                                                paramName: "file",

                                                // client-side limit (MB)
                                                maxFilesize: 50,
                                                maxFiles: 1,

                                                acceptedFiles: ".jpg,.jpeg,.png,.webp,.gif,.pdf,.doc,.docx,.xls,.xlsx",
                                                headers: {
                                                    "X-CSRF-TOKEN": getCsrf(),
                                                    "X-Requested-With": "XMLHttpRequest",
                                                    "Accept": "application/json",
                                                },

                                                clickable: true,
                                                previewsContainer: false,
                                                previewTemplate: "<div></div>",

                                                timeout: 0, // no client timeout for large files

                                                // IMPORTANT in Blade: use @{{ }} to avoid Blade parsing
                                                dictFileTooBig: "Datei ist zu groß (@{{filesize}}MB). Max: @{{maxFilesize}}MB",
                                                dictInvalidFileType: "Ungültiger Dateityp.",
                                                dictResponseError: "Serverfehler: @{{statusCode}}",

                                                sending: (file, xhr, formData) => {
                                                    const cid = form.querySelector('input[name="customer_id"]')?.value || "";
                                                    const aid = form.querySelector('input[name="alternative_id"]')?.value || "";
                                                    const pid = form.querySelector('input[name="product_id"]')?.value || "";
                                                    const stg = form.querySelector('select[name="stage"]')?.value || "customer";

                                                    formData.append("customer_id", cid);
                                                    formData.append("alternative_id", aid);
                                                    formData.append("product_id", pid);
                                                    formData.append("stage", stg);
                                                },

                                                success: () => {
                                                    if (typeof window.loadDocuments === "function" && button) {
                                                        window.loadDocuments(button, { keepTab: true, keepFilters: true, keepView: true });
                                                    }
                                                    swalOk("Upload OK");
                                                },
                                            });

                                            // show errors (client + server)
                                            dz.on("error", (file, msg, xhr) => {
                                                let text = normalizeError(msg);

                                                if (xhr) {
                                                    if (xhr.status === 413) {
                                                        text = "Upload zu groß: Server-Limit (413). Prüfe Nginx client_max_body_size.";
                                                    } else if (xhr.status === 422) {
                                                        text = parseLaravel422(xhr);
                                                    } else if (xhr.status >= 500) {
                                                        text = "Serverfehler (500+). Prüfe Nginx/PHP/Laravel Logs.";
                                                    }
                                                }

                                                swalErr("Upload fehlgeschlagen", text);
                                                try { dz.removeFile(file); } catch (_) { }
                                            });

                                            dz.on("maxfilesexceeded", (file) => {
                                                swalWarn("Nur 1 Datei", "Bitte nur eine Datei pro Upload.");
                                                try { dz.removeFile(file); } catch (_) { }
                                            });

                                            window.__docsDz = dz;
                                        }

                                        // expose
                                        window.initDropzone = initDropzone;
                                    })();
                                </script>


                                <script>
                                    document.addEventListener("DOMContentLoaded", function () {
                                        const lazyImages = [].slice.call(document.querySelectorAll("img.lazy"));
                                        if ("IntersectionObserver" in window) {
                                            let lazyImageObserver = new IntersectionObserver(function (entries, observer) {
                                                entries.forEach(function (entry) {
                                                    if (entry.isIntersecting) {
                                                        let img = entry.target;
                                                        img.src = img.dataset.src;
                                                        img.classList.remove("lazy");
                                                        lazyImageObserver.unobserve(img);
                                                    }
                                                });
                                            });

                                            lazyImages.forEach(function (lazyImage) {
                                                lazyImageObserver.observe(lazyImage);
                                            });
                                        }
                                    }); 
                                </script>
                                <!-- Document and PIcutre :end -->



                                <script>
                                    function loadkanban(customerId, alternativeId, productId, employeeId) {
                                        const container = document.getElementById('mainContent');
                                        container.innerHTML = '<div class="p-3 text-center">Kanban wird geladen...</div>';

                                        fetch(`/customer/process/kanban/${customerId}/${alternativeId}/${productId}/${employeeId}`)
                                            .then(response => response.json())
                                            .then(data => {
                                                return fetch('/customer/process/kanban/view', {
                                                    method: 'POST',
                                                    headers: {
                                                        'Content-Type': 'application/json',
                                                        'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                                    },
                                                    body: JSON.stringify({ leads: data })
                                                });
                                            })
                                            .then(res => res.text())
                                            .then(html => {
                                                container.innerHTML = html;
                                                feather.replace();
                                                initKanbanSortable();
                                            })
                                            .catch(err => {
                                                container.innerHTML = `<div class="alert alert-danger">Fehler beim Laden des Kanban-Boards.</div>`;
                                                console.error(err);
                                            });
                                    }

                                    function initKanbanSortable(onStageChangeSuccess = () => { }) {
                                        const dropzones = document.querySelectorAll('.kanban-dropzone');
                                        const borderColors = {
                                            lead: '#fcd34d',
                                            offer: '#93c5fd',
                                            deal: '#34d399',
                                            project: '#60a5fa',
                                            ticket: '#fca5a5',
                                            completed: '#a3e635',
                                            junk: '#d1d5db'
                                        };

                                        dropzones.forEach((zone, index) => {
                                            new Sortable(zone, {
                                                group: 'kanban',
                                                animation: 150,
                                                onEnd: function (evt) {
                                                    const el = evt.item;
                                                    const fromStage = evt.from.closest('.kanban-column')?.dataset.stage;
                                                    const toStage = evt.to.closest('.kanban-column')?.dataset.stage;

                                                    if (!toStage || fromStage === toStage) return;

                                                    const customerId = el.dataset.customerId;
                                                    const alternativeId = el.dataset.alternativeId;
                                                    const productId = el.dataset.productId;
                                                    const employeeId = el.dataset.employeeId || 0;
                                                    const service = el.dataset.service;
                                                    const serviceId = el.dataset.serviceId || 0;
                                                    const departmentId = el.dataset.departmentId || 0;

                                                    if (!customerId || !alternativeId || !productId || !service || !toStage) {
                                                        console.error('[Kanban Error] Missing data');
                                                        return;
                                                    }

                                                    Swal.fire({
                                                        title: 'Notiz zum Statuswechsel',
                                                        input: 'textarea',
                                                        inputPlaceholder: 'Gib eine Beschreibung oder Notiz ein...',
                                                        showCancelButton: true,
                                                        confirmButtonText: 'Speichern',
                                                        cancelButtonText: 'Abbrechen',
                                                        inputAttributes: {
                                                            autocapitalize: 'on'
                                                        },
                                                        showLoaderOnConfirm: true,
                                                        preConfirm: (description) => {
                                                            const url = `/lead/kanban/${customerId}/${alternativeId}/${productId}/${employeeId}/${service}/${toStage}/${serviceId}/${departmentId}`;
                                                            return fetch(url, {
                                                                method: 'POST',
                                                                headers: {
                                                                    'Content-Type': 'application/json',
                                                                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                                                },
                                                                body: JSON.stringify({ description })
                                                            })
                                                                .then(response => response.json())
                                                                .then(data => {
                                                                    if (!data.success) throw new Error(data.message || 'Fehler beim Speichern');
                                                                    return data;
                                                                })
                                                                .catch(error => {
                                                                    Swal.showValidationMessage(`❌ ${error.message}`);
                                                                });
                                                        },
                                                        allowOutsideClick: () => !Swal.isLoading()
                                                    }).then(result => {
                                                        if (result.isConfirmed) {
                                                            // ✅ Style and update
                                                            el.style.borderLeftColor = borderColors[toStage] || '#ccc';
                                                            const stageLabel = el.querySelector('.kanban-stage-label');
                                                            if (stageLabel) {
                                                                const stageMap = {
                                                                    lead: 'Kunde',
                                                                    offer: 'Angebot',
                                                                    deal: 'Auftrag',
                                                                    project: 'Montage',
                                                                    completed: 'Abgeschlossen',
                                                                    ticket: 'Ticket',
                                                                    junk: 'Junk'
                                                                };
                                                                stageLabel.textContent = stageMap[toStage] || toStage;
                                                            }

                                                            Swal.fire({
                                                                icon: 'success',
                                                                title: 'Status geändert',
                                                                text: result.value.message || 'Erfolgreich aktualisiert.',
                                                                timer: 1200,
                                                                showConfirmButton: false,
                                                                toast: true,
                                                                position: 'top-end'
                                                            });

                                                            onStageChangeSuccess(el, toStage);
                                                        } else {
                                                            // ❌ Move back if canceled
                                                            evt.from.appendChild(el);
                                                        }
                                                    });
                                                }
                                            });
                                        });
                                    }
                                </script>


                                <!-- Ticket systems  -->
                                <script>
                                    const context = document.getElementById('filterContext');
                                    const customer_id = context.dataset.customer;
                                    const alternative_id = context.dataset.alternative;
                                    const product_id = context.dataset.product;

                                    function LoadCustomerTicket(customerId, alternativeId, productId, tab) {
                                        const container = document.getElementById("mainContent");
                                        container.innerHTML = '<div class="p-4 text-center">Tickets werden geladen...</div>';

                                        fetch("/customer/tickets/load", {
                                            method: "POST",
                                            headers: {
                                                "Content-Type": "application/json",
                                                "X-CSRF-TOKEN": document.querySelector('meta[name="csrf-token"]').content
                                            },
                                            body: JSON.stringify({
                                                customer_id: customerId,
                                                alternative_id: alternativeId,
                                                product_id: productId,
                                                tab: tab
                                            })
                                        })
                                            .then(res => res.text())
                                            .then(html => {
                                                container.innerHTML = html;
                                                feather.replace();
                                                initKanbanSortable(); // ✅ re-initialize sortable
                                            });
                                    }
                                    function filterTickets() {
                                        const date = document.getElementById('filterDate').value;
                                        const status = document.getElementById('filterStatus').value;
                                        const employee = document.getElementById('filterEmployee').value;

                                        // ✅ use correctly defined vars
                                        const context = document.getElementById('filterContext');
                                        const customer_id = context.dataset.customer;
                                        const alternative_id = context.dataset.alternative;
                                        const product_id = context.dataset.product;

                                        fetch('/customer/tickets/load', {
                                            method: 'POST',
                                            headers: {
                                                'Content-Type': 'application/json',
                                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                            },
                                            body: JSON.stringify({
                                                customer_id,
                                                alternative_id,
                                                product_id,
                                                date,
                                                status,
                                                employee
                                            })
                                        })
                                            .then(res => res.text())
                                            .then(html => {
                                                document.getElementById('mainContent').innerHTML = html;
                                                feather.replace();
                                                initKanbanSortable();
                                            });
                                    }

                                    function initKanbanSortable() {
                                        document.querySelectorAll('.kanban-dropzone').forEach(zone => {
                                            new Sortable(zone, {
                                                group: 'tickets',
                                                animation: 150,
                                                onAdd: function (evt) {
                                                    const ticketId = evt.item.dataset.id;
                                                    const newStatus = evt.to.closest('.kanban-column').dataset.status;

                                                    fetch('/ticket/status/update', {
                                                        method: 'POST',
                                                        headers: {
                                                            'Content-Type': 'application/json',
                                                            'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]').content
                                                        },
                                                        body: JSON.stringify({ id: ticketId, status: newStatus })
                                                    }).then(res => res.json())
                                                        .then(res => {
                                                            if (res.success) {
                                                                console.log(`Ticket #${ticketId} → ${newStatus}`);
                                                            }
                                                        });
                                                }
                                            });
                                        });
                                    }
                                    // Optional: Call this once if Kanban is rendered on page load
                                    document.addEventListener('DOMContentLoaded', initKanbanSortable);
                                </script>

                                <script>
                                    $(document).ready(function () {
                                        // 1. Fix for Bootstrap 4 Focus Stealing
                                        // This stops Bootstrap from stealing focus when you click inputs in your custom overlay
                                        $.fn.modal.Constructor.prototype._enforceFocus = function () { };

                                        // 2. Fix for Bootstrap 5 (if you update later)
                                        $.fn.modal.Constructor.prototype.enforceFocus = function () { };

                                        // 3. Specific Event Listener for your Overlay
                                        // This stops the focusin event from bubbling up to Bootstrap
                                        $(document).on('focusin', function (e) {
                                            if ($(e.target).closest('#serialsOverlay').length) {
                                                e.stopPropagation();
                                            }
                                        });
                                    });
                                </script>

                                <!-- save operation of Product  -->
                                <script>
                                    /**
                                     * Customer Products + Gallery – FULL SCRIPT (No page reload)
                                     * Fixes:
                                     *  - leadProduct global always available (no "leadProduct is not defined")
                                     *  - serial_numbers key aligned with controller (NOT serial_numbers_json)
                                     *  - serial modal uses {pos, serial, product_name} and remains backward compatible
                                     *  - removes duplicate saveSerials() definition
                                     *  - avoids inline-onclick dependency by exposing window.leadProduct and window.CustomerProducts.leadProduct
                                     *
                                     * Requires:
                                     * - jQuery
                                     * - Select2
                                     * - SweetAlert2 (Swal)
                                     */

                                    (function () {
                                        'use strict';

                                        // ------------------------------------------------------------
                                        // State (persistent across blade injections)
                                        // ------------------------------------------------------------
                                        window.__CP_STATE__ = window.__CP_STATE__ || {
                                            currentCid: null,
                                            currentAid: null,
                                            currentPid: null,
                                            cachedProducts: [],
                                            cachedDepartments: [],
                                            serialMode: 'add',
                                            booted: false,

                                            // gallery
                                            addSavedProductInfoId: null,
                                            editProductInfoId: null,
                                            addMediaCache: [],
                                            editMediaCache: [],
                                        };
                                        const S = window.__CP_STATE__;

                                        // ------------------------------------------------------------
                                        // API (adjust if routes differ)
                                        // ------------------------------------------------------------
                                        const CP = {
                                            api: {
                                                leadBlade: (cid, aid, pid) => `/lead-product/${cid}/${aid}/${pid}`,
                                                loadData: (pid) => `/customer/load/product/${pid}`,

                                                store: `/lead-product/store`,
                                                show: (id) => `/lead-product/${id}`,
                                                update: (id) => `/lead-product/update/${id}`,
                                                del: (id) => `/lead-product/delete/${id}`,

                                                // gallery
                                                mediaIndex: (productInfoId) => `/lead-product/media/${productInfoId}`,
                                                mediaUpload: (productInfoId) => `/lead-product/media/${productInfoId}/upload`,
                                                mediaDelete: (mediaId) => `/lead-product/media/file/${mediaId}`,
                                            }
                                        };

                                        // ------------------------------------------------------------
                                        // Helpers
                                        // ------------------------------------------------------------
                                        const csrf = () =>
                                            document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';

                                        const stripHtml = (html) => {
                                            const div = document.createElement('div');
                                            div.innerHTML = html ?? '';
                                            return div.textContent || div.innerText || '';
                                        };

                                        const escHtml = (s) =>
                                            String(s ?? '')
                                                .replace(/&/g, '&amp;')
                                                .replace(/</g, '&lt;')
                                                .replace(/>/g, '&gt;')
                                                .replace(/"/g, '&quot;')
                                                .replace(/'/g, '&#039;');

                                        const isTruthy = (v) => Number(v) === 1 || v === true || v === '1';

                                        const swalLoading = (title = 'Loading...') => {
                                            if (!window.Swal) return;
                                            Swal.fire({ title, allowOutsideClick: false, didOpen: () => Swal.showLoading() });
                                        };
                                        const closeSwal = () => { try { window.Swal?.close?.(); } catch (e) { } };

                                        const toast = (icon, title, text) => {
                                            window.Swal?.fire?.({
                                                icon: icon || 'success',
                                                title: title || '',
                                                text: text || '',
                                                timer: 1300,
                                                showConfirmButton: false,
                                                toast: true,
                                                position: 'top-end',
                                            });
                                        };

                                        const $ovAdd = () => $('#addProductOverlay');
                                        const $ovEdit = () => $('#editProductOverlay');
                                        const $ovSn = () => $('#serialsOverlay');

                                        function setBodyLock() {
                                            const anyOpen = $('.cp-overlay.is-open').length > 0;
                                            document.documentElement.classList.toggle('cp-modal-open', anyOpen);
                                            document.body.classList.toggle('cp-modal-open', anyOpen);
                                        }

                                        function closeAllSelect2() {
                                            $('select').each(function () {
                                                const $s = $(this);
                                                if ($s.data('select2')) {
                                                    try { $s.select2('close'); } catch (e) { }
                                                }
                                            });
                                        }

                                        function openOverlay($el) {
                                            if (!$el || !$el.length) return;
                                            closeAllSelect2();
                                            $el.addClass('is-open').attr('aria-hidden', 'false');
                                            setBodyLock();
                                            setTimeout(() => {
                                                const $f = $el.find('input,select,textarea,button').filter(':visible').not(':disabled').first();
                                                if ($f.length) $f.trigger('focus');
                                            }, 30);
                                        }

                                        function closeOverlay($el) {
                                            if (!$el || !$el.length) return;
                                            closeAllSelect2();
                                            $el.removeClass('is-open').attr('aria-hidden', 'true');
                                            setBodyLock();
                                        }

                                        // overlay: click outside closes
                                        $(document).off('mousedown.cpOverlay').on('mousedown.cpOverlay', '.cp-overlay.is-open', function (e) {
                                            if (e.target === this) closeOverlay($(this));
                                        });

                                        // overlay: data-cp-close
                                        $(document).off('click.cpClose').on('click.cpClose', '[data-cp-close]', function () {
                                            const id = $(this).attr('data-cp-close');
                                            closeOverlay($('#' + id));
                                        });

                                        // overlay: ESC closes top-most
                                        $(document).off('keydown.cpEsc').on('keydown.cpEsc', function (e) {
                                            if (e.key !== 'Escape') return;
                                            if ($ovSn().hasClass('is-open')) return closeOverlay($ovSn());
                                            if ($ovEdit().hasClass('is-open')) return closeOverlay($ovEdit());
                                            if ($ovAdd().hasClass('is-open')) return closeOverlay($ovAdd());
                                        });

                                        // ------------------------------------------------------------
                                        // Select2 (products)
                                        // ------------------------------------------------------------
                                        function formatProduct(p) {
                                            if (!p || !p.id) return p?.text || '';
                                            const $el = $(p.element);
                                            const brand = $el.data('brand') || '';
                                            const desc = stripHtml($el.data('description') || '');
                                            const img = $el.data('image') || '/images/icons/placeholder.svg';

                                            const $row = $('<div class="d-flex align-items-center" style="gap:10px;"/>');
                                            $row.append($('<img/>', { src: img, width: 28, height: 28, class: 'rounded' }));
                                            const $text = $('<div style="min-width:0;"/>');
                                            $text.append($('<div style="font-weight:600;"/>').text(p.text));
                                            if (brand) $text.append($('<small class="text-muted d-block"/>').text(brand));
                                            if (desc) $text.append($('<small class="text-muted d-block"/>').text(desc));
                                            $row.append($text);
                                            return $row;
                                        }

                                        function formatProductSelection(p) {
                                            if (!p || !p.id) return p?.text || '';
                                            const $el = $(p.element);
                                            const brand = $el.data('brand') || '';
                                            const $wrap = $('<span/>').text(p.text);
                                            if (brand) $wrap.append($('<small class="text-muted ml-1"/>').text(`(${brand})`));
                                            return $wrap;
                                        }

                                        function ensureEmptyOption($select) {
                                            if (!$select || !$select.length) return;
                                            const hasEmpty = $select.find('option').filter(function () {
                                                return String($(this).attr('value') ?? '') === '';
                                            }).length > 0;
                                            if (!hasEmpty) $select.prepend(new Option('', '', false, false));
                                        }

                                        function safeDestroySelect2($select) {
                                            if (!$select || !$select.length) return;
                                            if (!$select.data('select2')) return;
                                            try { $select.select2('close'); } catch (e) { }
                                            try { $select.select2('destroy'); } catch (e) { }
                                        }

                                        function initProductSelect2($select, $overlay, placeholder) {
                                            if (!$select || !$select.length) return;

                                            ensureEmptyOption($select);
                                            safeDestroySelect2($select);

                                            const $parent = $overlay.find('.cp-dialog').first();

                                            $select.select2({
                                                width: '100%',
                                                allowClear: true,
                                                placeholder: placeholder || 'Bitte wählen',
                                                closeOnSelect: true,
                                                templateResult: formatProduct,
                                                templateSelection: formatProductSelection,
                                                dropdownParent: $parent.length ? $parent : $(document.body),
                                            });

                                            $select.off('select2:select.cpClose').on('select2:select.cpClose', function () {
                                                try { $(this).select2('close'); } catch (e) { }
                                            });
                                        }

                                        function initEmployeeSelect2($overlay) {
                                            const $sels = $overlay.find('.js-employee-select');
                                            if (!$sels.length) return;

                                            $sels.each(function () {
                                                const $el = $(this);
                                                if ($el.data('select2')) return;

                                                ensureEmptyOption($el);
                                                const $parent = $overlay.find('.cp-dialog').first();

                                                $el.select2({
                                                    tags: true,
                                                    width: '100%',
                                                    allowClear: true,
                                                    closeOnSelect: true,
                                                    placeholder: 'Mitarbeiter wählen oder Namen eingeben',
                                                    dropdownParent: $parent.length ? $parent : $(document.body),
                                                });

                                                $el.off('select2:select.cpClose').on('select2:select.cpClose', function () {
                                                    try { $(this).select2('close'); } catch (e) { }
                                                });
                                            });
                                        }

                                        function getInstalledBy($select) {
                                            if ($select.data('select2')) {
                                                const d = $select.select2('data');
                                                if (d && d.length) return (d[0].text || '').trim();
                                            }
                                            return ($select.val() || '').trim();
                                        }

                                        // ------------------------------------------------------------
                                        // Table row render/patch
                                        // ------------------------------------------------------------
                                        function rowHtml(p) {
                                            const purchasedTxt = isTruthy(p.purchased_from_us) ? 'Ja' : 'Nein';
                                            const imageTxt = isTruthy(p.image_available) ? 'Ja' : 'Nein';

                                            return `
                                              <tr data-id="${escHtml(p.id)}" style="cursor:pointer;">
                                                <td><p class="m-0 p-0">${escHtml(p.product_count ?? '')}</p></td>
                                                <td>
                                                  <p class="m-0 p-0">${escHtml(p.product_name ?? '')}</p>
                                                  <small><p class="m-0 p-0">S.Nr: ${escHtml(p.serial_number ?? '-')}</p></small>
                                                </td>
                                                <td>${escHtml(p.manufacturer ?? '')}</td>
                                                <td>
                                                  <p class="m-0 p-0">${escHtml(p.installation_date ?? 'unbekannt')}</p>
                                                  <small><p class="m-0 p-0">${escHtml(p.installation_location ?? 'Installationsort unbekannt')}</p></small>
                                                </td>
                                                <td>
                                                  <p class="m-0 p-0">${escHtml(p.purchase_date ?? '—')}</p>
                                                  <small><p class="m-0 p-0">${purchasedTxt}</p></small>
                                                </td>
                                                <td>
                                                  <small>
                                                    <p class="m-0 p-0"><strong>Rechnung/Referenz:</strong> ${escHtml(p.invoice_reference ?? 'unbekannt')}</p>
                                                    <p class="m-0 p-0"><strong>Garantie bis:</strong> ${escHtml(p.warranty_until ?? 'unbekannt')}</p>
                                                    <p class="m-0 p-0"><strong>Gewährleistung bis:</strong> ${escHtml(p.guarantee_until ?? 'unbekannt')}</p>
                                                    <p class="m-0 p-0"><strong>Bild vorhanden:</strong> ${imageTxt}</p>
                                                  </small>
                                                </td>
                                                <td>${escHtml(p.installed_by ?? '—')}</td>
                                                <td>${escHtml(p.department_name ?? '—')}</td>
                                                <td class="text-right">
                                                  <button class="btn btn-icon btn-icon rounded-circle btn-primary mr-1 mb-1 waves-effect waves-light action-btn"
                                                          onclick="event.stopPropagation(); window.CustomerProducts.editProduct(${Number(p.id)})">
                                                    <i class="feather icon-edit"></i>
                                                  </button>
                                                  <button class="btn btn-icon btn-icon rounded-circle btn-danger mr-1 mb-1 waves-effect waves-light action-btn"
                                                          onclick="event.stopPropagation(); window.CustomerProducts.deleteProduct(${Number(p.id)})">
                                                    <i class="feather icon-trash"></i>
                                                  </button>
                                                </td>
                                              </tr>
                                            `;
                                        }

                                        function appendRow(p) {
                                            $('#productTableBody').append(rowHtml(p));
                                            window.feather?.replace?.();
                                        }

                                        function upsertRow(p) {
                                            const $row = $(`#productTableBody tr[data-id="${p.id}"]`);
                                            if ($row.length) $row.replaceWith(rowHtml(p));
                                            else appendRow(p);
                                            window.feather?.replace?.();
                                        }

                                        // ------------------------------------------------------------
                                        // Build selects
                                        // ------------------------------------------------------------
                                        function buildProductOptions($select, products) {
                                            $select.empty();
                                            $select.append(new Option('', '', false, false));
                                            (products || []).forEach((p) => {
                                                const image = p?.images?.[0]?.image ? `/uploads/${p.images[0].image}` : '/images/icons/placeholder.svg';
                                                const brand = p?.brand?.name || '';
                                                const desc = stripHtml(p?.short_description || '');

                                                const opt = new Option(p.product, p.id, false, false);
                                                opt.setAttribute('data-brand', brand);
                                                opt.setAttribute('data-description', desc);
                                                opt.setAttribute('data-image', image);
                                                $select.append(opt);
                                            });
                                        }

                                        function buildDepartmentOptions($select, depts) {
                                            $select.empty();
                                            $select.append(new Option('', '', false, false));
                                            (depts || []).forEach((d) => $select.append(new Option(d.department_name, d.id, false, false)));
                                        }

                                        // ------------------------------------------------------------
                                        // Gallery
                                        // ------------------------------------------------------------
                                        function bytesToSize(bytes) {
                                            const b = Number(bytes || 0);
                                            if (!b) return '';
                                            const units = ['B', 'KB', 'MB', 'GB'];
                                            let i = 0, v = b;
                                            while (v >= 1024 && i < units.length - 1) { v /= 1024; i++; }
                                            return `${v.toFixed(i === 0 ? 0 : 1)} ${units[i]}`;
                                        }

                                        function isImageMime(mime) {
                                            return String(mime || '').startsWith('image/');
                                        }

                                        function mediaCardHtml(m, mode) {
                                            const name = escHtml(m.original_name || 'file');
                                            const size = escHtml(bytesToSize(m.size));
                                            const url = escHtml(m.url || '#');
                                            const id = Number(m.id);

                                            const preview = isImageMime(m.mime)
                                                ? `<img src="${url}" alt="${name}" style="width:100%; height:140px; object-fit:cover; border-radius:10px;">`
                                                : `<div style="width:100%; height:140px; border-radius:10px; display:flex; align-items:center; justify-content:center; border:1px dashed rgba(0,0,0,.15);">
                                                   <div style="text-align:center;">
                                                     <i class="feather icon-file-text" style="font-size:28px;"></i>
                                                     <div style="font-size:12px; opacity:.75; margin-top:6px;">PDF/Dokument</div>
                                                   </div>
                                                 </div>`;

                                            return `
                                              <div class="col-md-3 mb-2 cp-media-item" data-mid="${id}" data-name="${escHtml((m.original_name || '').toLowerCase())}">
                                                <div class="card" style="border-radius:14px; overflow:hidden;">
                                                  <div class="p-2">${preview}</div>
                                                  <div class="px-2 pb-2">
                                                    <div class="d-flex justify-content-between align-items-start" style="gap:10px;">
                                                      <div style="min-width:0;">
                                                        <div style="font-weight:600; font-size:13px; white-space:nowrap; overflow:hidden; text-overflow:ellipsis;">${name}</div>
                                                        <div style="font-size:12px; opacity:.75;">${size}</div>
                                                      </div>
                                                      <div class="d-flex" style="gap:6px;">
                                                        <a class="btn btn-sm btn-outline-primary" href="${url}" target="_blank" title="Öffnen">
                                                          <i class="feather icon-external-link"></i>
                                                        </a>
                                                        <button type="button" class="btn btn-sm btn-outline-danger btnMediaDelete" data-mode="${mode}" data-id="${id}" title="Löschen">
                                                          <i class="feather icon-trash"></i>
                                                        </button>
                                                      </div>
                                                    </div>
                                                  </div>
                                                </div>
                                              </div>
                                            `;
                                        }

                                        function renderMediaGrid(mode, media) {
                                            const list = Array.isArray(media) ? media : [];
                                            const $grid = mode === 'add' ? $('#addGalleryGrid') : $('#editGalleryGrid');
                                            $grid.html(list.map(m => mediaCardHtml(m, mode)).join('') || `<div class="col-12"><div class="text-muted">Keine Dateien vorhanden.</div></div>`);
                                            window.feather?.replace?.();
                                        }

                                        function filterMediaGrid(mode) {
                                            const q = (mode === 'add' ? $('#add_gallery_search').val() : $('#edit_gallery_search').val()) || '';
                                            const s = q.trim().toLowerCase();
                                            const $grid = mode === 'add' ? $('#addGalleryGrid') : $('#editGalleryGrid');
                                            $grid.find('.cp-media-item').each(function () {
                                                const name = ($(this).data('name') || '');
                                                $(this).toggle(!s || name.includes(s));
                                            });
                                        }

                                        async function loadMedia(mode, productInfoId) {
                                            if (!productInfoId) return;
                                            try {
                                                const res = await $.getJSON(CP.api.mediaIndex(productInfoId));
                                                const media = res?.media || [];
                                                if (mode === 'add') S.addMediaCache = media;
                                                else S.editMediaCache = media;
                                                renderMediaGrid(mode, media);
                                                filterMediaGrid(mode);
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Galerie konnte nicht geladen werden.', 'error');
                                            }
                                        }

                                        async function uploadMedia(mode) {
                                            const productInfoId = mode === 'add' ? S.addSavedProductInfoId : S.editProductInfoId;
                                            if (!productInfoId) return window.Swal?.fire?.('Info', 'Bitte zuerst das Produkt speichern.', 'info');

                                            const $input = mode === 'add' ? $('#add_gallery_files') : $('#edit_gallery_files');
                                            const files = $input[0]?.files ? Array.from($input[0].files) : [];
                                            if (!files.length) return toast('info', 'Keine Datei', 'Bitte Dateien auswählen.');

                                            const fd = new FormData();
                                            fd.append('_token', csrf());
                                            files.forEach(f => fd.append('files[]', f));

                                            const $btn = mode === 'add' ? $('#btnAddGalleryUpload') : $('#btnEditGalleryUpload');
                                            $btn.prop('disabled', true);

                                            try {
                                                const res = await $.ajax({
                                                    url: CP.api.mediaUpload(productInfoId),
                                                    type: 'POST',
                                                    data: fd,
                                                    processData: false,
                                                    contentType: false,
                                                });

                                                const newMedia = res?.media || [];
                                                if (mode === 'add') {
                                                    S.addMediaCache = [...newMedia, ...(S.addMediaCache || [])];
                                                    renderMediaGrid('add', S.addMediaCache);
                                                } else {
                                                    S.editMediaCache = [...newMedia, ...(S.editMediaCache || [])];
                                                    renderMediaGrid('edit', S.editMediaCache);
                                                }

                                                $input.val('');
                                                filterMediaGrid(mode);
                                                toast('success', 'Upload', 'Dateien wurden hochgeladen.');
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Upload fehlgeschlagen.', 'error');
                                            } finally {
                                                $btn.prop('disabled', false);
                                            }
                                        }

                                        async function deleteMedia(mode, mediaId) {
                                            const ok = await window.Swal?.fire?.({
                                                title: 'Datei löschen?',
                                                icon: 'warning',
                                                showCancelButton: true,
                                                confirmButtonText: 'Ja, löschen',
                                            });
                                            if (!ok?.isConfirmed) return;

                                            try {
                                                await $.ajax({
                                                    url: CP.api.mediaDelete(mediaId),
                                                    type: 'DELETE',
                                                    data: { _token: csrf() },
                                                });

                                                if (mode === 'add') {
                                                    S.addMediaCache = (S.addMediaCache || []).filter(x => Number(x.id) !== Number(mediaId));
                                                    renderMediaGrid('add', S.addMediaCache);
                                                } else {
                                                    S.editMediaCache = (S.editMediaCache || []).filter(x => Number(x.id) !== Number(mediaId));
                                                    renderMediaGrid('edit', S.editMediaCache);
                                                }

                                                filterMediaGrid(mode);
                                                toast('success', 'Gelöscht', 'Datei wurde entfernt.');
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Konnte Datei nicht löschen.', 'error');
                                            }
                                        }

                                        function resetAddGalleryUI() {
                                            S.addSavedProductInfoId = null;
                                            S.addMediaCache = [];
                                            $('#addGalleryGrid').empty();
                                            $('#add_gallery_search').val('');
                                            $('#add_gallery_files').val('');
                                            $('#addGalleryLocked').removeClass('d-none');
                                            $('#addGalleryControls').addClass('d-none');
                                        }

                                        function unlockAddGallery(productInfoId) {
                                            S.addSavedProductInfoId = Number(productInfoId);
                                            $('#addGalleryLocked').addClass('d-none');
                                            $('#addGalleryControls').removeClass('d-none');
                                            loadMedia('add', S.addSavedProductInfoId);
                                        }

                                        // ------------------------------------------------------------
                                        // Wire after blade injection
                                        // ------------------------------------------------------------
                                        function wireAfterBladeLoad() {
                                            // Row click -> edit
                                            $('#productTableBody')
                                                .off('click.cpRow')
                                                .on('click.cpRow', 'tr', function (e) {
                                                    if ($(e.target).closest('button, a, .action-btn').length) return;
                                                    const id = $(this).data('id');
                                                    if (id) window.CustomerProducts.editProduct(id);
                                                });

                                            initEmployeeSelect2($ovAdd());
                                            initEmployeeSelect2($ovEdit());

                                            // Add product select
                                            const $addProd = $('#customer_product_info');
                                            buildProductOptions($addProd, S.cachedProducts);
                                            initProductSelect2($addProd, $ovAdd(), 'Produkt auswählen');
                                            $addProd.off('change.cpAddFill').on('change.cpAddFill', function () {
                                                const opt = this.options[this.selectedIndex];
                                                $('#manufacturer_note').val(opt?.getAttribute('data-brand') || '');
                                                $('#notes_note').val(opt?.getAttribute('data-description') || '');
                                            });

                                            buildDepartmentOptions($('#department_id'), S.cachedDepartments);

                                            // Edit product select
                                            const $editProd = $('#edit_product_name');
                                            buildProductOptions($editProd, S.cachedProducts);
                                            initProductSelect2($editProd, $ovEdit(), 'Produkt auswählen');
                                            $editProd.off('change.cpEditFill').on('change.cpEditFill', function () {
                                                const opt = this.options[this.selectedIndex];
                                                $('#edit_manufacturer').val(opt?.getAttribute('data-brand') || '');
                                                if (!$('#edit_notes').val()) $('#edit_notes').val(opt?.getAttribute('data-description') || '');
                                            });

                                            buildDepartmentOptions($('#edit_department_id'), S.cachedDepartments);

                                            resetAddGalleryUI();
                                            updateSerialButtons();
                                        }

                                        // ------------------------------------------------------------
                                        // Lock/unlock edit
                                        // ------------------------------------------------------------
                                        const ICON_LOCKED =
                                            '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-lock"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1 10 0v4"></path></svg>';
                                        const ICON_UNLOCKED =
                                            '<svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round" class="feather feather-unlock"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"></rect><path d="M7 11V7a5 5 0 0 1-9.9-1"></path></svg>';

                                        function toggleEditLock(forceLocked = null) {
                                            const $ov = $ovEdit();
                                            const $inputs = $ov.find('input, select, textarea');
                                            const $save = $('#btnEditSave');
                                            const $lock = $('#btnToggleEditLock');

                                            let shouldLock;
                                            if (forceLocked !== null) shouldLock = !!forceLocked;
                                            else shouldLock = !$inputs.first().prop('disabled');

                                            $inputs.prop('disabled', shouldLock);
                                            $save.prop('disabled', shouldLock);
                                            $lock.html(shouldLock ? ICON_LOCKED : ICON_UNLOCKED);

                                            updateSerialButtons();
                                        }

                                        $(document).off('click.cpLock').on('click.cpLock', '#btnToggleEditLock', () => toggleEditLock(null));

                                        // ------------------------------------------------------------
                                        // Serials modal (JSON keys aligned)
                                        // ------------------------------------------------------------
                                        function parseSerialJson(raw) {
                                            if (Array.isArray(raw)) return raw;
                                            try {
                                                const v = JSON.parse(raw || '[]');
                                                return Array.isArray(v) ? v : [];
                                            } catch {
                                                return [];
                                            }
                                        }

                                        function serialCount(mode) {
                                            return Math.max(1, Number((mode === 'edit' ? $('#edit_product_count').val() : $('#product_count').val()) || 1));
                                        }

                                        function serialName(mode) {
                                            const name = (mode === 'edit'
                                                ? $('#edit_product_name option:selected').text()
                                                : $('#customer_product_info option:selected').text()) || '';
                                            return (name || 'Produkt').trim();
                                        }

                                        function jsonInput(mode) {
                                            return mode === 'edit' ? $('#edit_serial_numbers_json') : $('#serial_numbers_json');
                                        }

                                        function mainInput(mode) {
                                            return mode === 'edit' ? $('#edit_serial_number') : $('#serial_number');
                                        }

                                        function hintEl(mode) {
                                            return mode === 'edit' ? $('#serialsHintEdit') : $('#serialsHintAdd');
                                        }

                                        function updateSerialButtons() {
                                            const addC = Number($('#product_count').val() || 1);
                                            $('#btnSerialsAdd').prop('disabled', !(addC > 1));

                                            const editC = Number($('#edit_product_count').val() || 1);
                                            const locked = $('#btnEditSave').prop('disabled') === true;
                                            $('#btnSerialsEdit').prop('disabled', locked || !(editC > 1));
                                        }

                                        function renderSerialRows(mode) {
                                            const count = serialCount(mode);
                                            const existing = parseSerialJson(jsonInput(mode).val());
                                            const seed = (mainInput(mode).val() || '').trim();

                                            if (!existing.length && seed) existing.push({ pos: 1, serial: seed, product_name: serialName(mode) });

                                            $('#serialsModalProductName').text(serialName(mode));
                                            $('#serialsModalCount').text(String(count));

                                            const rows = [];
                                            for (let i = 1; i <= count; i++) {
                                                const found = existing.find(x => Number(x.pos) === i);
                                                const val = (found?.serial ?? found?.serial_number ?? ''); // backward compat
                                                rows.push(`
                                                <tr>
                                                  <td style="width:90px;">${i}</td>
                                                  <td>
                                                    <input type="text"
                                                           class="form-control form-control-sm serial-input"
                                                           data-pos="${i}"
                                                           value="${escHtml(val)}"
                                                           placeholder="z.B. SN-${String(i).padStart(3, '0')}"
                                                           autocomplete="off">
                                                  </td>
                                                </tr>
                                              `);
                                            }
                                            $('#serialsModalBody').html(rows.join(''));
                                        }

                                        function openSerials(mode) {
                                            S.serialMode = mode;
                                            renderSerialRows(mode);
                                            openOverlay($ovSn());
                                            setTimeout(() => $('#serialsModalBody').find('input.serial-input').first().trigger('focus'), 50);
                                        }

                                        function saveSerials() {
                                            const mode = S.serialMode || 'add';
                                            const count = serialCount(mode);
                                            const pn = serialName(mode);

                                            const arr = [];
                                            $('#serialsModalBody').find('input.serial-input').each(function () {
                                                arr.push({
                                                    pos: Number($(this).data('pos')),
                                                    serial: ($(this).val() || '').trim(),
                                                    product_name: pn,
                                                });
                                            });

                                            jsonInput(mode).val(JSON.stringify(arr));

                                            const firstNonEmpty = arr.find(x => x.serial) || arr.find(x => x.pos === 1) || null;
                                            mainInput(mode).val(firstNonEmpty?.serial || '');

                                            const filled = arr.filter(x => x.serial).length;
                                            hintEl(mode).text(`${filled}/${count} Seriennummern gespeichert`).show();

                                            closeOverlay($ovSn());
                                        }

                                        $(document).off('click.cpOpenSerialAdd').on('click.cpOpenSerialAdd', '#btnSerialsAdd', function () {
                                            if ($(this).prop('disabled')) return;
                                            openSerials('add');
                                        });

                                        $(document).off('click.cpOpenSerialEdit').on('click.cpOpenSerialEdit', '#btnSerialsEdit', function () {
                                            if ($(this).prop('disabled')) return;
                                            openSerials('edit');
                                        });

                                        $(document).off('click.cpSerialClose').on('click.cpSerialClose', '#snCloseBtn, #snCancelBtn', () => closeOverlay($ovSn()));
                                        $(document).off('click.cpSerialSave').on('click.cpSerialSave', '#btnSerialsModalSave', saveSerials);
                                        $(document).off('input.cpSerialCount change.cpSerialCount').on('input.cpSerialCount change.cpSerialCount', '#product_count, #edit_product_count', updateSerialButtons);

                                        // ------------------------------------------------------------
                                        // Open/Close overlays
                                        // ------------------------------------------------------------
                                        function openAdd() {
                                            openOverlay($ovAdd());
                                            updateSerialButtons();
                                            if (!S.addSavedProductInfoId) resetAddGalleryUI();
                                        }
                                        function closeAdd() { closeOverlay($ovAdd()); }
                                        function openEdit() { openOverlay($ovEdit()); updateSerialButtons(); }
                                        function closeEdit() { closeOverlay($ovEdit()); }

                                        // ------------------------------------------------------------
                                        // Load blade + cache data
                                        // IMPORTANT: expose globally so inline onclick="leadProduct(this)" works
                                        // ------------------------------------------------------------
                                        async function leadProduct(buttonOrEvent) {
                                            const btn = buttonOrEvent?.currentTarget ? buttonOrEvent.currentTarget : buttonOrEvent;
                                            const $btn = $(btn);

                                            S.currentCid = $btn.data('customer-id');
                                            S.currentAid = $btn.data('alternative-id');
                                            S.currentPid = $btn.data('product-id');

                                            swalLoading('Loading...');

                                            try {
                                                const html = await $.ajax({ url: CP.api.leadBlade(S.currentCid, S.currentAid, S.currentPid), method: 'GET' });
                                                $('#mainContent').html(html);
                                                closeSwal();
                                                window.feather?.replace?.();

                                                const data = await fetch(CP.api.loadData(S.currentPid), { credentials: 'same-origin' }).then(r => r.json());
                                                S.cachedProducts = data.products || [];
                                                S.cachedDepartments = data.departments || [];

                                                wireAfterBladeLoad();
                                            } catch (e) {
                                                closeSwal();
                                                console.error(e);
                                                window.Swal?.fire?.('Error', 'Failed to load product info.', 'error');
                                            }
                                        }

                                        // ------------------------------------------------------------
                                        // ADD (NO reload)
                                        // ------------------------------------------------------------
                                        async function addProduct() {
                                            const $btn = $('#btnAddSave');
                                            $btn.prop('disabled', true);

                                            const installedBy = getInstalledBy($('#installed_by'));
                                            const selectedProductName = $('#customer_product_info option:selected').text();

                                            const payload = {
                                                _token: csrf(),
                                                customer_id: S.currentCid,
                                                alternative_id: S.currentAid,
                                                product_id: S.currentPid,

                                                products: $('#customer_product_info').val(),
                                                product_name: selectedProductName,
                                                product_count: $('#product_count').val(),

                                                manufacturer: $('#manufacturer_note').val(),
                                                serial_number: $('#serial_number').val(),

                                                // ✅ controller expects "serial_numbers"
                                                serial_numbers: $('#serial_numbers_json').val(),

                                                installation_date: $('#installation_date').val(),
                                                installation_location: $('#installation_location').val(),

                                                purchased_from_us: $('#purchased_from_us').val(),
                                                purchase_date: $('#purchase_date').val(),

                                                invoice_reference: $('#invoice_reference').val(),
                                                warranty_until: $('#warranty_until').val(),
                                                guarantee_until: $('#guarantee_until').val(),

                                                image_available: $('#image_available').val(),
                                                installed_by: installedBy,
                                                department_id: $('#department_id').val(),
                                                notes: $('#notes_note').val(),
                                            };

                                            try {
                                                const res = await $.post(CP.api.store, payload);
                                                upsertRow(res);

                                                if (res?.id) {
                                                    unlockAddGallery(res.id);
                                                    try { $('a[href="#addTabGallery"]').tab('show'); } catch (e) { }
                                                }

                                                toast('success', 'Gespeichert!', 'Produkt wurde hinzugefügt.');
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Error', 'Fehler beim Speichern', 'error');
                                            } finally {
                                                $btn.prop('disabled', false);
                                            }
                                        }

                                        function resetAddForm() {
                                            $('#product_count').val('1');
                                            $('#manufacturer_note, #serial_number, #installation_location, #invoice_reference, #notes_note').val('');
                                            $('#installation_date, #purchase_date, #warranty_until, #guarantee_until').val('');
                                            $('#purchased_from_us, #image_available').val('0');
                                            $('#department_id').val('');
                                            $('#serial_numbers_json').val('');
                                            $('#serialsHintAdd').hide().text('');

                                            const $prodSel = $('#customer_product_info');
                                            if ($prodSel.data('select2')) $prodSel.val('').trigger('change'); else $prodSel.val('');

                                            const $emp = $('#installed_by');
                                            if ($emp.data('select2')) $emp.val('').trigger('change'); else $emp.val('');

                                            resetAddGalleryUI();
                                            try { $('a[href="#addTabDetails"]').tab('show'); } catch (e) { }
                                            updateSerialButtons();
                                            toast('info', 'Neu', 'Formular zurückgesetzt.');
                                        }

                                        // ------------------------------------------------------------
                                        // EDIT: load item -> open overlay + load gallery
                                        // ------------------------------------------------------------
                                        async function editProduct(id) {
                                            try {
                                                const item = await $.getJSON(CP.api.show(id));
                                                if (!item) return window.Swal?.fire?.('Fehler', 'Produktdaten nicht gefunden.', 'error');

                                                S.editProductInfoId = Number(item.id);

                                                $('#edit_id').val(item.id);
                                                $('#edit_product_count').val(item.product_count ?? 1);

                                                $('#edit_serial_number').val(item.serial_number ?? '');

                                                const sn = item.serial_numbers ?? item.serial_numbers_json ?? [];
                                                $('#edit_serial_numbers_json').val(Array.isArray(sn) ? JSON.stringify(sn) : (sn || ''));

                                                $('#serialsHintEdit').hide().text('');

                                                $('#edit_installation_date').val(item.installation_date ?? '');
                                                $('#edit_installation_location').val(item.installation_location ?? '');
                                                $('#edit_purchased_from_us').val(isTruthy(item.purchased_from_us) ? '1' : '0');
                                                $('#edit_purchase_date').val(item.purchase_date ?? '');
                                                $('#edit_invoice_reference').val(item.invoice_reference ?? '');
                                                $('#edit_warranty_until').val(item.warranty_until ?? '');
                                                $('#edit_guarantee_until').val(item.guarantee_until ?? '');
                                                $('#edit_image_available').val(isTruthy(item.image_available) ? '1' : '0');

                                                $('#edit_manufacturer').val(item.manufacturer ?? '');
                                                $('#edit_notes').val(stripHtml(item.notes ?? ''));

                                                // product select
                                                if (item.products !== null && item.products !== undefined) {
                                                    $('#edit_product_name').val(String(item.products)).trigger('change');
                                                } else {
                                                    $('#edit_product_name').val('').trigger('change');
                                                }

                                                // department
                                                $('#edit_department_id').val(item.department_id ? String(item.department_id) : '');

                                                // installed_by tag
                                                const $emp = $('#edit_installed_by');
                                                const name = (item.installed_by || '').trim();
                                                if ($emp.data('select2')) {
                                                    $emp.val('').trigger('change');
                                                    if (name) {
                                                        const exists = $emp.find('option').filter(function () { return $(this).text().trim() === name; }).length > 0;
                                                        if (!exists) $emp.append(new Option(name, name, true, true));
                                                        $emp.val(name).trigger('change');
                                                    }
                                                } else {
                                                    $emp.val(name);
                                                }

                                                toggleEditLock(true);
                                                openEdit();
                                                updateSerialButtons();

                                                await loadMedia('edit', S.editProductInfoId);
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Produkt konnte nicht geladen werden.', 'error');
                                            }
                                        }

                                        // ------------------------------------------------------------
                                        // UPDATE (NO reload)
                                        // ------------------------------------------------------------
                                        async function updateProduct() {
                                            const id = $('#edit_id').val();
                                            if (!id) return;

                                            const $btn = $('#btnEditSave');
                                            $btn.prop('disabled', true);

                                            const installedBy = getInstalledBy($('#edit_installed_by'));
                                            const selectedProductId = $('#edit_product_name').val();
                                            const selectedProductName = $('#edit_product_name option:selected').text();

                                            const payload = {
                                                _token: csrf(),
                                                products: selectedProductId,
                                                product_name: selectedProductName,
                                                product_count: $('#edit_product_count').val(),

                                                manufacturer: $('#edit_manufacturer').val(),
                                                serial_number: $('#edit_serial_number').val(),

                                                // ✅ controller expects "serial_numbers"
                                                serial_numbers: $('#edit_serial_numbers_json').val(),

                                                installation_date: $('#edit_installation_date').val(),
                                                installation_location: $('#edit_installation_location').val(),

                                                purchased_from_us: $('#edit_purchased_from_us').val(),
                                                purchase_date: $('#edit_purchase_date').val(),

                                                invoice_reference: $('#edit_invoice_reference').val(),
                                                warranty_until: $('#edit_warranty_until').val(),
                                                guarantee_until: $('#edit_guarantee_until').val(),

                                                image_available: $('#edit_image_available').val(),
                                                installed_by: installedBy,
                                                department_id: $('#edit_department_id').val(),
                                                notes: $('#edit_notes').val(),
                                            };

                                            try {
                                                const res = await $.ajax({
                                                    url: CP.api.update(id),
                                                    type: 'PUT',
                                                    data: payload,
                                                });

                                                upsertRow(res);
                                                closeEdit();
                                                toast('success', 'Gespeichert', 'Produkt erfolgreich aktualisiert.');
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Konnte Produkt nicht aktualisieren.', 'error');
                                            } finally {
                                                $btn.prop('disabled', false);
                                            }
                                        }

                                        // ------------------------------------------------------------
                                        // DELETE (NO reload)
                                        // ------------------------------------------------------------
                                        async function deleteProduct(id) {
                                            const result = await window.Swal?.fire?.({
                                                title: 'Löschen?',
                                                icon: 'warning',
                                                showCancelButton: true,
                                                confirmButtonText: 'Ja, löschen',
                                            });
                                            if (!result?.isConfirmed) return;

                                            try {
                                                await $.ajax({
                                                    url: CP.api.del(id),
                                                    type: 'DELETE',
                                                    data: { _token: csrf() },
                                                });
                                                $(`#productTableBody tr[data-id="${id}"]`).remove();
                                                window.Swal?.fire?.('Gelöscht', 'Eintrag wurde entfernt', 'success');
                                            } catch (e) {
                                                console.error(e);
                                                window.Swal?.fire?.('Fehler', 'Konnte nicht gelöscht werden', 'error');
                                            }
                                        }

                                        // ------------------------------------------------------------
                                        // Delegated handlers (blade gets replaced)
                                        // ------------------------------------------------------------
                                        $(document).off('click.cpAddSave').on('click.cpAddSave', '#btnAddSave', addProduct);
                                        $(document).off('click.cpAddNew').on('click.cpAddNew', '#btnAddNew', resetAddForm);
                                        $(document).off('click.cpEditSave').on('click.cpEditSave', '#btnEditSave', updateProduct);

                                        // gallery upload
                                        $(document).off('click.cpAddGalleryUpload').on('click.cpAddGalleryUpload', '#btnAddGalleryUpload', () => uploadMedia('add'));
                                        $(document).off('click.cpEditGalleryUpload').on('click.cpEditGalleryUpload', '#btnEditGalleryUpload', () => uploadMedia('edit'));

                                        // gallery search
                                        $(document).off('input.cpAddGallerySearch').on('input.cpAddGallerySearch', '#add_gallery_search', () => filterMediaGrid('add'));
                                        $(document).off('input.cpEditGallerySearch').on('input.cpEditGallerySearch', '#edit_gallery_search', () => filterMediaGrid('edit'));

                                        // gallery delete
                                        $(document).off('click.cpMediaDelete').on('click.cpMediaDelete', '.btnMediaDelete', function () {
                                            const mode = $(this).data('mode');
                                            const id = $(this).data('id');
                                            if (id) deleteMedia(mode, id);
                                        });

                                        // reload media when tab opens
                                        $(document).off('shown.bs.tab.cpGalleryTab').on('shown.bs.tab.cpGalleryTab', 'a[data-toggle="tab"]', function (e) {
                                            const target = $(e.target).attr('href');
                                            if (target === '#addTabGallery' && S.addSavedProductInfoId) loadMedia('add', S.addSavedProductInfoId);
                                            if (target === '#editTabGallery' && S.editProductInfoId) loadMedia('edit', S.editProductInfoId);
                                        });

                                        // ------------------------------------------------------------
                                        // Public API + global functions (fix "leadProduct is not defined")
                                        // ------------------------------------------------------------
                                        window.CustomerProducts = window.CustomerProducts || {};
                                        window.CustomerProducts = Object.assign(window.CustomerProducts, {
                                            leadProduct,
                                            openAdd,
                                            closeAdd,
                                            addProduct,
                                            editProduct,
                                            updateProduct,
                                            deleteProduct,
                                            toggleEditLock,
                                            openSerials,

                                            loadMedia,
                                            uploadMedia,
                                            deleteMedia,
                                        });

                                        // ✅ Critical: inline onclick="leadProduct(this)" needs this
                                        window.leadProduct = leadProduct;

                                        // optional legacy globals
                                        window.addProduct = addProduct;
                                        window.editProduct = editProduct;
                                        window.deleteProduct = deleteProduct;
                                        window.toggleEditLock = toggleEditLock;

                                        // ------------------------------------------------------------
                                        // Boot once
                                        // ------------------------------------------------------------
                                        function boot() {
                                            if (S.booted) return;
                                            S.booted = true;
                                            updateSerialButtons();
                                        }

                                        $(document).ready(boot);

                                    })();
                                </script>


