                                    const escapeHtml = (value) => String(value ?? "")
                                        .replace(/&/g, "&amp;")
                                        .replace(/</g, "&lt;")
                                        .replace(/>/g, "&gt;")
                                        .replace(/"/g, "&quot;")
                                        .replace(/'/g, "&#039;");

                                    const safeNumber = (value, fallback = 0) => {
