                                 <!-- #project price modal -->
                                  <script>
                                    document.addEventListener('click', function (e) {
                                        const btn = e.target.closest('.price-edit-trigger');
                                        if (!btn) return;

                                        e.preventDefault();
                                        e.stopPropagation();
                                        e.stopImmediatePropagation();

                                        const plId = btn.dataset.plId;

                                        if (!plId || plId === '0' || plId === 'null' || plId === 'undefined') {
                                            console.error('lead_product_lists id (data-pl-id) fehlt.', btn);

                                            Swal.fire({
                                                icon: 'error',
                                                title: 'Fehler',
                                                text: 'Produktlisten-ID fehlt. Prüfe $pl_id im Blade.'
                                            });

                                            return false;
                                        }

                                        const currentPrice = btn.dataset.currentPrice || '0';

                                        Swal.fire({
                                            title: 'Preis ändern',
                                            input: 'number',
                                            inputLabel: 'Neuer Preis in EUR',
                                            inputValue: currentPrice,
                                            inputAttributes: {
                                                step: '0.01',
                                                min: '0'
                                            },
                                            showCancelButton: true,
                                            confirmButtonText: 'Speichern',
                                            cancelButtonText: 'Abbrechen',
                                            width: 'min(420px, 90vw)',
                                            scrollbarPadding: false,
                                            backdrop: true,

                                            didOpen: (modalEl) => {
                                                const inputEl = modalEl.querySelector('input.swal2-input');

                                                if (inputEl) {
                                                    inputEl.style.textAlign = 'center';
                                                    inputEl.focus();
                                                    inputEl.select();
                                                }
                                            },

                                            preConfirm: (value) => {
                                                if (value === '' || value === null || isNaN(value) || Number(value) < 0) {
                                                    Swal.showValidationMessage('Bitte einen gültigen Preis eingeben.');
                                                    return false;
                                                }

                                                return Number(value).toFixed(2);
                                            }
                                        }).then((result) => {
                                            if (!result.isConfirmed) return;

                                            const price = result.value;

                                            fetch('{{ route("leadProduct.updatePrice") }}', {
                                                method: 'POST',
                                                headers: {
                                                    'Content-Type': 'application/json',
                                                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '',
                                                    'Accept': 'application/json',
                                                    'X-Requested-With': 'XMLHttpRequest'
                                                },
                                                body: JSON.stringify({
                                                    id: plId,
                                                    price: price
                                                })
                                            })
                                            .then(async function (response) {
                                                const data = await response.json().catch(() => ({}));

                                                if (!response.ok) {
                                                    throw new Error(data.message || 'Preis konnte nicht gespeichert werden.');
                                                }

                                                return data;
                                            })
                                            .then(function (data) {
                                                if (!data.success) {
                                                    throw new Error(data.message || 'Fehler beim Speichern.');
                                                }

                                                btn.dataset.currentPrice = data.price_raw ?? price;

                                                const priceSpan = btn.querySelector('.price-value, .metric-value');

                                                if (priceSpan) {
                                                    priceSpan.textContent = data.price_formatted || (
                                                        Number(price).toLocaleString('de-DE', {
                                                            minimumFractionDigits: 2,
                                                            maximumFractionDigits: 2
                                                        }) + ' €'
                                                    );
                                                }

                                                const totalNode = document.getElementById('customerTotalPurchase');

                                                if (totalNode && data.total_purchase_formatted) {
                                                    totalNode.textContent = data.total_purchase_formatted;
                                                    totalNode.dataset.totalPurchaseRaw = data.total_purchase_raw ?? '';
                                                }

                                                Swal.fire({
                                                    icon: 'success',
                                                    title: 'Gespeichert',
                                                    text: 'Preis wurde aktualisiert.',
                                                    timer: 1500,
                                                    showConfirmButton: false
                                                });
                                            })
                                            .catch(function (err) {
                                                console.error(err);

                                                Swal.fire({
                                                    icon: 'error',
                                                    title: 'Fehler',
                                                    text: err.message || 'Preis konnte nicht gespeichert werden.'
                                                });
                                            });
                                        });

                                        return false;
                                    }, true);
                                    </script> 

                                    <script>
                                        function formatEuroDE(value) {
                                            return Number(value || 0).toLocaleString('de-DE', {
                                                minimumFractionDigits: 2,
                                                maximumFractionDigits: 2
                                            }) + ' €';
                                        }

                                        function syncInvoicePriceAndLoad(button, customerId, alternativeId, productId) {
                                            if (button && button.dataset.syncRunning === '1') return;

                                            if (button) {
                                                button.dataset.syncRunning = '1';
                                                button.classList.add('is-loading');
                                            }

                                            const amountLine = document.querySelector(
                                                '[data-sidebar-amount="invoice_total_amount"]' +
                                                '[data-customer-id="' + customerId + '"]' +
                                                '[data-alternative-id="' + alternativeId + '"]' +
                                                '[data-product-id="' + productId + '"]'
                                            );

                                            if (amountLine) {
                                                amountLine.classList.remove('is-zero', 'is-error');
                                                amountLine.classList.add('is-loading');
                                                amountLine.textContent = 'Gesamt: wird aktualisiert…';
                                            }

                                            if (typeof Swal !== 'undefined') {
                                                Swal.fire({
                                                    title: 'Rechnungssumme wird aktualisiert',
                                                    text: 'Der Produktpreis wird automatisch aus den Rechnungen übernommen.',
                                                    allowOutsideClick: false,
                                                    allowEscapeKey: false,
                                                    showConfirmButton: false,
                                                    didOpen: () => Swal.showLoading()
                                                });
                                            }

                                            fetch('{{ route("new-leads.invoices.sync-product-price") }}', {
                                                method: 'POST',
                                                headers: {
                                                    'Content-Type': 'application/json',
                                                    'Accept': 'application/json',
                                                    'X-Requested-With': 'XMLHttpRequest',
                                                    'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || ''
                                                },
                                                body: JSON.stringify({
                                                    customer_id: customerId,
                                                    alternative_id: alternativeId,
                                                    product_id: productId
                                                })
                                            })
                                            .then(async function (response) {
                                                const payload = await response.json().catch(() => ({}));

                                                if (!response.ok || !payload.success) {
                                                    throw new Error(payload.message || 'Rechnungssumme konnte nicht aktualisiert werden.');
                                                }

                                                return payload;
                                            })
                                            .then(function (payload) {
                                                const total = Number(payload.invoice_total_amount || payload.price_raw || 0);
                                                const totalFormatted = payload.invoice_total_amount_formatted || payload.price_formatted || formatEuroDE(total);

                                                if (amountLine) {
                                                    amountLine.textContent = 'Gesamt: ' + totalFormatted;
                                                    amountLine.classList.remove('is-loading', 'is-error');
                                                    amountLine.classList.toggle('is-zero', total === 0);
                                                }

                                                const priceButton = document.querySelector(
                                                    '.ma-product-card[data-object-customer-id="' + customerId + '"]' +
                                                    '[data-object-alternative-id="' + alternativeId + '"]' +
                                                    '[data-object-product="' + productId + '"] .price-edit-trigger'
                                                );

                                                if (priceButton) {
                                                    priceButton.dataset.currentPrice = payload.price_raw || total;

                                                    const priceNode = priceButton.querySelector('.price-value, .metric-value');
                                                    if (priceNode) {
                                                        priceNode.textContent = payload.price_formatted || totalFormatted;
                                                    }
                                                }

                                                const customerTotalNode = document.getElementById('customerTotalPurchase');
                                                if (customerTotalNode && payload.total_purchase_formatted) {
                                                    customerTotalNode.textContent = payload.total_purchase_formatted;
                                                    customerTotalNode.dataset.totalPurchaseRaw = payload.total_purchase_raw || 0;
                                                }

                                                if (typeof Swal !== 'undefined') {
                                                    Swal.fire({
                                                        icon: 'success',
                                                        title: 'Preis aktualisiert',
                                                        text: 'Die Rechnungssumme wurde übernommen.',
                                                        timer: 900,
                                                        showConfirmButton: false
                                                    });
                                                }

                                                // ✅ This opens/shows the Rechnung part after updating price
                                                if (typeof loadInvoice === 'function') {
                                                    loadInvoice(customerId, alternativeId, productId);
                                                }
                                            })
                                            .catch(function (error) {
                                                console.error(error);

                                                if (amountLine) {
                                                    amountLine.classList.remove('is-loading', 'is-zero');
                                                    amountLine.classList.add('is-error');
                                                    amountLine.textContent = 'Gesamt: Fehler';
                                                }

                                                if (typeof Swal !== 'undefined') {
                                                    Swal.fire({
                                                        icon: 'error',
                                                        title: 'Fehler',
                                                        text: error.message || 'Rechnungssumme konnte nicht aktualisiert werden.'
                                                    });
                                                }

                                                // Still show Rechnung part even if sync fails
                                                if (typeof loadInvoice === 'function') {
                                                    loadInvoice(customerId, alternativeId, productId);
                                                }
                                            })
                                            .finally(function () {
                                                if (button) {
                                                    button.dataset.syncRunning = '0';
                                                    button.classList.remove('is-loading');
                                                }
                                            });
                                        }
                                        </script>
                                <!-- Feed Script  -->
                                <script>
                                    (function () {
                                        "use strict";

                                        const FEED_ENDPOINT = "/lead/customer-feed"; // /{id}?limit=10

                                        const KIND_LABELS = {
                                            product: "Produkt",
                                            appointment: "Termin",
                                            task: "Aufgabe",
                                            ticket: "Ticket",
                                            history: "Historie"
                                        };

                                        const KIND_PILL_CLASS = {
                                            product: "feed-modal-icon-pill--product",
                                            appointment: "feed-modal-icon-pill--appointment",
                                            task: "feed-modal-icon-pill--task",
                                            ticket: "feed-modal-icon-pill--ticket",
                                            history: "feed-modal-icon-pill--history"
                                        };

                                        const KIND_DEFAULT_ICON = {
                                            product: "icon-package",
                                            appointment: "icon-calendar",
                                            task: "icon-check-square",
                                            ticket: "icon-life-buoy",
                                            history: "icon-activity"
                                        };

                                        function escapeHtml(str) {
                                            if (!str) return "";
                                            return String(str)
                                                .replace(/&/g, "&amp;")
                                                .replace(/</g, "&lt;")
                                                .replace(/>/g, "&gt;")
                                                .replace(/"/g, "&quot;")
                                                .replace(/'/g, "&#039;");
                                        }

                                        async function fetchCustomerFeed(customerId, limit) {
                                            const url = FEED_ENDPOINT + "/" + encodeURIComponent(customerId) + "?limit=" + (limit || 10);

                                            const res = await fetch(url, {
                                                headers: {
                                                    "Accept": "application/json",
                                                    "X-Requested-With": "XMLHttpRequest"
                                                },
                                                credentials: "same-origin"
                                            });

                                            if (!res.ok) {
                                                throw new Error("Feed lädt nicht");
                                            }

                                            let json;
                                            try {
                                                json = await res.json();
                                            } catch (e) {
                                                throw new Error("Antwort ist kein gültiges JSON");
                                            }

                                            if (!json || json.success === false) {
                                                const msg = (json && (json.error || json.message)) || "Feed Fehler";
                                                throw new Error(msg);
                                            }

                                            const items = Array.isArray(json.items) ? json.items : [];
                                            return items;
                                        }

                                        function applyItemToDOM(root, item, index, total) {
                                            const emptyLine = root.querySelector("[data-feed-empty]");
                                            const line = root.querySelector("[data-feed-line]");
                                            const titleEl = root.querySelector("[data-feed-title]");
                                            const textEl = root.querySelector("[data-feed-text]");
                                            const pillEl = root.querySelector("[data-feed-pill]");
                                            const timeEl = root.querySelector("[data-feed-time]");
                                            const counterEl = root.querySelector("[data-feed-counter]");
                                            const iconNode = root.querySelector(".cfs-icon i, .live-feed-icon i");
                                            const errorEl = root.querySelector("[data-feed-error]");

                                            if (errorEl) {
                                                errorEl.textContent = "";
                                                errorEl.classList.add("d-none");
                                            }

                                            if (emptyLine) emptyLine.classList.add("d-none");
                                            if (line) line.classList.remove("d-none");

                                            if (titleEl) titleEl.textContent = item.title || "Aktivität";
                                            if (textEl) textEl.textContent = item.text || "";
                                            if (pillEl) pillEl.textContent = item.pill || "Info";
                                            if (timeEl) timeEl.textContent = item.time || "–";

                                            if (counterEl) {
                                                counterEl.textContent = total > 1 ? (index + 1) + " / " + total : "";
                                            }

                                            if (root) {
                                                root.dataset.kind = item.kind || "";
                                                root.classList.remove("is-empty");
                                                root.style.display = "flex";
                                            }

                                            if (iconNode) {
                                                const base = "feather";
                                                const iconCls = item.icon || KIND_DEFAULT_ICON[item.kind] || "icon-activity";
                                                iconNode.className = base + " " + iconCls;
                                            }
                                        }

                                        function showEmptyState(root, errorMessage) {
                                            const emptyLine = root.querySelector("[data-feed-empty]");
                                            const line = root.querySelector("[data-feed-line]");
                                            const counterEl = root.querySelector("[data-feed-counter]");
                                            const errorEl = root.querySelector("[data-feed-error]");

                                            if (line) line.classList.add("d-none");
                                            if (counterEl) counterEl.textContent = "";

                                            if (errorMessage && errorEl) {
                                                errorEl.textContent = errorMessage;
                                                errorEl.classList.remove("d-none");
                                                if (emptyLine) emptyLine.classList.add("d-none");
                                            } else {
                                                if (errorEl) {
                                                    errorEl.textContent = "";
                                                    errorEl.classList.add("d-none");
                                                }
                                                if (emptyLine) emptyLine.classList.remove("d-none");
                                            }

                                            root.classList.add("is-empty");
                                            root.style.display = "flex";
                                        }

                                        function parseGermanDateTime(str) {
                                            if (!str) return 0;
                                            const parts = String(str).split(" ");
                                            const datePart = parts[0] || "";
                                            const timePart = parts[1] || "";
                                            const dBits = datePart.split(".");
                                            if (dBits.length < 3) return 0;
                                            const day = parseInt(dBits[0], 10) || 1;
                                            const month = (parseInt(dBits[1], 10) || 1) - 1;
                                            const year = parseInt(dBits[2], 10) || 1970;

                                            let hour = 0, min = 0;
                                            if (timePart) {
                                                const tBits = timePart.split(":");
                                                hour = parseInt(tBits[0], 10) || 0;
                                                min = parseInt(tBits[1], 10) || 0;
                                            }

                                            return new Date(year, month, day, hour, min, 0, 0).getTime();
                                        }

                                        function openFeedModal(root) {
                                            const state = root._feedState;
                                            if (!state || !state.items || !state.items.length) return;

                                            const modal = document.getElementById("customerFeedModal");
                                            if (!modal) return;

                                            const titleEl = modal.querySelector("[data-feed-modal-title]");
                                            const subTitleEl = modal.querySelector("[data-feed-modal-subtitle]");
                                            const listEl = modal.querySelector("[data-feed-modal-list]");
                                            const emptyEl = modal.querySelector("[data-feed-modal-empty]");
                                            const countEl = modal.querySelector("[data-feed-modal-count]");
                                            const searchEl = modal.querySelector("[data-feed-modal-search]");
                                            const sortEl = modal.querySelector("[data-feed-modal-sort]");
                                            const kindBtns = modal.querySelectorAll("[data-feed-modal-kind]");

                                            const customerTitle = root.getAttribute("data-customer-title") || "";

                                            if (titleEl) titleEl.textContent = "Aktivitäten";
                                            if (subTitleEl) subTitleEl.textContent = customerTitle;

                                            const items = state.items.map(function (it) {
                                                const copy = Object.assign({}, it);
                                                copy._sortAt = parseGermanDateTime(copy.time);
                                                return copy;
                                            });

                                            const modalState = {
                                                items: items,
                                                filtered: [],
                                                kind: "all",
                                                search: "",
                                                sort: (sortEl && sortEl.value) ? sortEl.value : "desc"
                                            };
                                            modal._feedModalState = modalState;

                                            function renderList() {
                                                if (!listEl || !emptyEl || !countEl) return;

                                                let filtered = modalState.items.slice();

                                                if (modalState.kind !== "all") {
                                                    filtered = filtered.filter(function (it) {
                                                        return it.kind === modalState.kind;
                                                    });
                                                }

                                                if (modalState.search) {
                                                    const q = modalState.search.toLowerCase();
                                                    filtered = filtered.filter(function (it) {
                                                        const t = (it.title || "").toLowerCase();
                                                        const tx = (it.text || "").toLowerCase();
                                                        const p = (it.pill || "").toLowerCase();
                                                        return t.indexOf(q) !== -1 || tx.indexOf(q) !== -1 || p.indexOf(q) !== -1;
                                                    });
                                                }

                                                filtered.sort(function (a, b) {
                                                    if (modalState.sort === "asc") {
                                                        return (a._sortAt || 0) - (b._sortAt || 0);
                                                    }
                                                    return (b._sortAt || 0) - (a._sortAt || 0);
                                                });

                                                modalState.filtered = filtered;

                                                if (!filtered.length) {
                                                    listEl.innerHTML = "";
                                                    emptyEl.classList.remove("d-none");
                                                    countEl.textContent = "Anzahl: 0";
                                                    return;
                                                }

                                                emptyEl.classList.add("d-none");
                                                countEl.textContent = "Anzahl: " + filtered.length;

                                                var html = "";
                                                filtered.forEach(function (item) {
                                                    const kind = item.kind || "";
                                                    const icon = item.icon || KIND_DEFAULT_ICON[kind] || "icon-activity";
                                                    const kindLabel = KIND_LABELS[kind] || "Aktivität";
                                                    const pillCls = KIND_PILL_CLASS[kind] || "feed-modal-icon-pill--history";

                                                    const employees = Array.isArray(item.employees) ? item.employees : [];

                                                    let avatarsHtml = "";
                                                    if (employees.length) {
                                                        avatarsHtml += '<div class="feed-modal-avatars">';
                                                        employees.slice(0, 5).forEach(function (emp) {
                                                            const img = emp.image || "";
                                                            if (img) {
                                                                avatarsHtml += '<div class="feed-modal-avatar"><img src="' + escapeHtml(img) + '" alt=""></div>';
                                                            }
                                                        });
                                                        if (employees.length > 5) {
                                                            avatarsHtml += '<span class="feed-modal-avatars-more">+' + (employees.length - 5) + '</span>';
                                                        }
                                                        avatarsHtml += "</div>";
                                                    }

                                                    html += ''
                                                        + '<div class="feed-modal-item" data-kind="' + escapeHtml(kind) + '">'
                                                        + '  <div class="feed-modal-item-icon">'
                                                        + '    <div class="feed-modal-icon-pill ' + pillCls + '">'
                                                        + '      <i class="feather ' + escapeHtml(icon) + '"></i>'
                                                        + '    </div>'
                                                        + '  </div>'
                                                        + '  <div class="feed-modal-item-main">'
                                                        + '    <div class="feed-modal-item-header">'
                                                        + '      <div class="feed-modal-item-title">' + escapeHtml(item.title || "Aktivität") + '</div>'
                                                        + '      <div class="feed-modal-item-time">'
                                                        + '        <i class="feather icon-clock"></i>'
                                                        + escapeHtml(item.time || "–")
                                                        + '      </div>'
                                                        + '    </div>'
                                                        + '    <div class="feed-modal-item-text">'
                                                        + escapeHtml(item.text || "")
                                                        + '    </div>'
                                                        + avatarsHtml
                                                        + '    <div class="feed-modal-item-meta">'
                                                        + '      <span class="badge badge-light feed-modal-pill">'
                                                        + escapeHtml(item.pill || "Info")
                                                        + '      </span>'
                                                        + '      <span class="feed-modal-kind-label">'
                                                        + kindLabel
                                                        + '      </span>'
                                                        + '    </div>'
                                                        + '  </div>'
                                                        + '</div>';
                                                });

                                                listEl.innerHTML = html;
                                            }

                                            if (searchEl) {
                                                searchEl.value = "";
                                                searchEl.oninput = function () {
                                                    modalState.search = this.value || "";
                                                    renderList();
                                                };
                                            }

                                            if (sortEl) {
                                                sortEl.onchange = function () {
                                                    modalState.sort = this.value || "desc";
                                                    renderList();
                                                };
                                            }

                                            if (kindBtns && kindBtns.length) {
                                                kindBtns.forEach(function (btn) {
                                                    btn.addEventListener("click", function () {
                                                        const kind = this.getAttribute("data-feed-modal-kind") || "all";
                                                        modalState.kind = kind;

                                                        kindBtns.forEach(function (b) {
                                                            b.classList.remove("active");
                                                        });
                                                        this.classList.add("active");

                                                        renderList();
                                                    });
                                                });
                                            }

                                            renderList();

                                            if (window.jQuery && typeof jQuery !== "undefined" && typeof jQuery.fn.modal === "function") {
                                                jQuery("#customerFeedModal").modal("show");
                                            } else {
                                                modal.style.display = "block";
                                                modal.classList.add("show");
                                            }
                                        }

                                        function initFeed(root) {
                                            if (!root || root._feedInitialized) return;
                                            root._feedInitialized = true;

                                            const customerId = root.getAttribute("data-customer-id");
                                            if (!customerId) {
                                                showEmptyState(root);
                                                return;
                                            }

                                            const limitAttr = root.getAttribute("data-feed-limit") || "10";
                                            const limit = parseInt(limitAttr, 10) || 10;

                                            const state = {
                                                items: [],
                                                index: 0,
                                                playing: false,
                                                timer: null
                                            };
                                            root._feedState = state;

                                            const btnPrev = root.querySelector("[data-feed-prev]");
                                            const btnNext = root.querySelector("[data-feed-next]");
                                            const btnToggle = root.querySelector("[data-feed-toggle]");
                                            const btnExpand = root.querySelector("[data-feed-expand]");
                                            const iconPause = root.querySelector("[data-feed-icon-pause]");
                                            const iconPlay = root.querySelector("[data-feed-icon-play]");

                                            function updateToggleIcons() {
                                                if (!btnToggle) return;
                                                if (state.playing) {
                                                    if (iconPause) iconPause.classList.remove("d-none");
                                                    if (iconPlay) iconPlay.classList.add("d-none");
                                                } else {
                                                    if (iconPause) iconPause.classList.add("d-none");
                                                    if (iconPlay) iconPlay.classList.remove("d-none");
                                                }
                                            }

                                            function show(index) {
                                                if (!state.items.length) {
                                                    showEmptyState(root);
                                                    return;
                                                }
                                                const total = state.items.length;
                                                const idx = (index % total + total) % total;
                                                state.index = idx;

                                                const item = state.items[idx];
                                                applyItemToDOM(root, item, idx, total);
                                            }

                                            function stop() {
                                                if (state.timer) {
                                                    clearInterval(state.timer);
                                                    state.timer = null;
                                                }
                                                state.playing = false;
                                                updateToggleIcons();
                                            }

                                            function start() {
                                                if (state.playing || state.items.length <= 1) {
                                                    state.playing = false;
                                                    updateToggleIcons();
                                                    return;
                                                }
                                                state.playing = true;
                                                updateToggleIcons();
                                                state.timer = setInterval(function () {
                                                    show(state.index + 1);
                                                }, 6000);
                                            }

                                            if (btnPrev) {
                                                btnPrev.addEventListener("click", function () {
                                                    if (!state.items.length) return;
                                                    stop();
                                                    show(state.index - 1);
                                                });
                                            }

                                            if (btnNext) {
                                                btnNext.addEventListener("click", function () {
                                                    if (!state.items.length) return;
                                                    stop();
                                                    show(state.index + 1);
                                                });
                                            }

                                            if (btnToggle) {
                                                btnToggle.addEventListener("click", function () {
                                                    if (!state.items.length) return;
                                                    if (state.playing) {
                                                        stop();
                                                    } else {
                                                        start();
                                                    }
                                                });
                                            }

                                            if (btnExpand) {
                                                btnExpand.addEventListener("click", function () {
                                                    if (!state.items.length) return;
                                                    openFeedModal(root);
                                                });
                                            }

                                            fetchCustomerFeed(customerId, limit)
                                                .then(function (items) {
                                                    state.items = items || [];
                                                    root.setAttribute("data-feed-count", String(state.items.length || 0));

                                                    if (!state.items.length) {
                                                        showEmptyState(root);
                                                        return;
                                                    }

                                                    show(0);
                                                    start();
                                                })
                                                .catch(function (err) {
                                                    showEmptyState(root, err && err.message ? err.message : null);
                                                });
                                        }

                                        function bootstrapCustomerFeeds() {
                                            const roots = Array.prototype.slice.call(
                                                document.querySelectorAll(".customer-live-feed[data-feed-root][data-customer-id]")
                                            );
                                            if (!roots.length) return;

                                            let i = 0;
                                            const BATCH = 5;

                                            (function pump() {
                                                const slice = roots.slice(i, i + BATCH);
                                                i += BATCH;
                                                slice.forEach(initFeed);
                                                if (i < roots.length) {
                                                    setTimeout(pump, 80);
                                                }
                                            })();
                                        }

                                        document.addEventListener("DOMContentLoaded", bootstrapCustomerFeeds);
                                    })();
                                </script>

                                <script>
                                    (function ($) {
                                        const modalEl = document.getElementById('customerContactPeopleModal');

                                        let currentCustomerId = {{ (int) $customer->id }};
                                        let currentEditId = null;

                                        function openContactModal() {
                                            if (modalEl) {
                                                modalEl.classList.add('is-open');
                                            }
                                        }

                                        function closeContactModal() {
                                            if (modalEl) {
                                                modalEl.classList.remove('is-open');
                                            }
                                            resetForm();
                                        }

                                        // close via X and "Schließen" button
                                        $(document).on('click', '.ccp-modal-close-btn', function () {
                                            closeContactModal();
                                        });

                                        // click on backdrop closes modal
                                        if (modalEl) {
                                            modalEl.addEventListener('click', function (e) {
                                                if (e.target === modalEl) {
                                                    closeContactModal();
                                                }
                                            });
                                        }

                                        function getIndexUrl(customerId) {
                                            return "{{ route('customers.contact-people.index', ['customer' => '___CID___']) }}"
                                                .replace('___CID___', customerId);
                                        }

                                        function getStoreUrl(customerId) {
                                            return "{{ route('customers.contact-people.store', ['customer' => '___CID___']) }}"
                                                .replace('___CID___', customerId);
                                        }

                                        function getUpdateUrl(id) {
                                            return "{{ route('customer-contact-people.update', ['person' => '___PID___']) }}"
                                                .replace('___PID___', id);
                                        }

                                        function getDeleteUrl(id) {
                                            return "{{ route('customer-contact-people.destroy', ['person' => '___PID___']) }}"
                                                .replace('___PID___', id);
                                        }

                                        // CSRF
                                        $.ajaxSetup({
                                            headers: {
                                                'X-CSRF-TOKEN': document.querySelector('meta[name="csrf-token"]')?.content || ''
                                            }
                                        });

                                        // open modal from icon
                                        $(document).on('click', '.cn-contact-people-trigger', function () {
                                            const cid = $(this).data('customer-id');
                                            currentCustomerId = cid || currentCustomerId;
                                            loadContactPeople(currentCustomerId);
                                            resetForm();
                                            openContactModal();
                                        });

                                        // add new
                                        $('#addContactPersonBtn').on('click', function () {
                                            resetForm();
                                            $('#contactPersonFormTitle').text('Kontaktperson hinzufügen');
                                        });

                                        // edit
                                        $(document).on('click', '.cp-edit-btn', function () {
                                            const id = $(this).data('id');
                                            const rowStr = $(this).attr('data-row') || '{}';
                                            let rowData = {};

                                            try {
                                                rowData = JSON.parse(rowStr);
                                            } catch (e) {
                                                console.warn('Cannot parse row data', e);
                                            }

                                            currentEditId = id;
                                            $('#contactPersonFormTitle').text('Kontaktperson bearbeiten');

                                            $('#contactPersonId').val(id);
                                            $('#cpRelation').val(rowData.relation || '');
                                            $('#cpName').val(rowData.name || '');
                                            $('#cpLastname').val(rowData.lastname || '');
                                            $('#cpPhone').val(rowData.phone || '');
                                            $('#cpOffice').val(rowData.office || '');
                                            $('#cpHome').val(rowData.home || '');
                                            $('#cpEmail').val(rowData.email || '');
                                            $('#cpStatus').val(rowData.status || 'Published');
                                        });

                                        // delete
                                        $(document).on('click', '.cp-delete-btn', function () {
                                            const id = $(this).data('id');

                                            if (!confirm('Kontaktperson wirklich löschen?')) {
                                                return;
                                            }

                                            $.ajax({
                                                url: getDeleteUrl(id),
                                                type: 'DELETE',
                                                success: function (res) {
                                                    if (res.success) {
                                                        loadContactPeople(currentCustomerId);
                                                    }
                                                }
                                            });
                                        });

                                        // submit form
                                        $('#contactPersonForm').on('submit', function (e) {
                                            e.preventDefault();

                                            const id = $('#contactPersonId').val();
                                            const cid = $('#contactPersonCustomerId').val();

                                            const data = {
                                                relation: $('#cpRelation').val(),
                                                name: $('#cpName').val(),
                                                lastname: $('#cpLastname').val(),
                                                phone: $('#cpPhone').val(),
                                                office: $('#cpOffice').val(),
                                                home: $('#cpHome').val(),
                                                email: $('#cpEmail').val(),
                                                status: $('#cpStatus').val()
                                            };

                                            if (!id) {
                                                // create
                                                $.post(getStoreUrl(cid), data, function (res) {
                                                    if (res.success) {
                                                        resetForm();
                                                        loadContactPeople(cid);
                                                    } else {
                                                        console.warn(res.errors || res);
                                                    }
                                                }).fail(function (xhr) {
                                                    console.error(xhr.responseJSON || xhr.responseText);
                                                });
                                            } else {
                                                // update
                                                $.ajax({
                                                    url: getUpdateUrl(id),
                                                    method: 'PUT',
                                                    data: data,
                                                    success: function (res) {
                                                        if (res.success) {
                                                            resetForm();
                                                            loadContactPeople(cid);
                                                        }
                                                    },
                                                    error: function (xhr) {
                                                        console.error(xhr.responseJSON || xhr.responseText);
                                                    }
                                                });
                                            }
                                        });

                                        function resetForm() {
                                            currentEditId = null;
                                            $('#contactPersonId').val('');
                                            $('#cpRelation').val('');
                                            $('#cpName').val('');
                                            $('#cpLastname').val('');
                                            $('#cpPhone').val('');
                                            $('#cpOffice').val('');
                                            $('#cpHome').val('');
                                            $('#cpEmail').val('');
                                            $('#cpStatus').val('Published');
                                        }

                                        function loadContactPeople(customerId) {
                                            $.get(getIndexUrl(customerId), function (res) {
                                                if (!res.success) return;

                                                const rows = res.data || [];
                                                renderTable(rows);
                                                renderPreview(rows, customerId);
                                            });
                                        }

                                        function renderTable(rows) {
                                            const tbody = $('#contactPeopleTableBody');
                                            tbody.empty();

                                            if (!rows.length) {
                                                tbody.append(
                                                    '<tr><td colspan="6" class="text-muted text-center py-3">Keine Kontaktpersonen vorhanden.</td></tr>'
                                                );
                                                return;
                                            }

                                            rows.forEach(function (row) {
                                                const jsonRow = JSON.stringify(row).replace(/"/g, '&quot;');

                                                tbody.append(`
                                                <tr>
                                                    <td>${row.relation || ''}</td>
                                                    <td>${row.full_name || ''}</td>
                                                    <td>${row.phone || ''}</td>
                                                    <td>${row.email || ''}</td>
                                                    <td>${row.status || ''}</td>
                                                    <td class="text-end">
                                                        <button type="button"
                                                                class="btn btn-xs btn-outline-secondary cp-edit-btn me-1"
                                                                data-id="${row.id}"
                                                                data-row="${jsonRow}">
                                                            <i class="feather icon-edit-2"></i>
                                                        </button>
                                                        <button type="button"
                                                                class="btn btn-xs btn-outline-danger cp-delete-btn"
                                                                data-id="${row.id}">
                                                            <i class="feather icon-trash-2"></i>
                                                        </button>
                                                    </td>
                                                </tr>
                                            `);
                                            });
                                        }

                                        function renderPreview(rows, customerId) {
                                            const previewEl = $('#contactPeoplePreview-' + customerId);
                                            const badgeEl = $('#contactPeopleCountBadge-' + customerId);

                                            badgeEl.text(rows.length);

                                            if (!rows.length) {
                                                previewEl.html('<span class="text-muted small">Keine Kontaktpersonen</span>');
                                                return;
                                            }

                                            const firstTwo = rows.slice(0, 2)
                                                .map(r => `${r.full_name || 'ohne Name'} (${r.relation || 'n/a'})`);

                                            let text = firstTwo.join(' · ');
                                            if (rows.length > 2) {
                                                text += ` · +${rows.length - 2} weitere`;
                                            }

                                            previewEl.html(`<span class="small text-muted"><i class="feather icon-users me-1"></i>${text}</span>`);
                                        }

                                        // initial preview load
                                        loadContactPeople(currentCustomerId);

                                    })(jQuery);
                                </script>

                                <script>
                                    (() => {
                                        'use strict';

                                        /* ===== Boot data from Blade ===== */
                                        const STAGE = @json($stage ?? 'lead');
                                        const SERVICES = @json($new_services);
                                        const PRODUCTS = @json($new_products);
                                        const DEPARTMENTS = @json($departments);
                                        const CSRF = document.querySelector('meta[name="csrf-token"]')?.content || '{{ csrf_token() }}';

                                        const EMP_IMG_DIR = "{{ asset('images/employee') }}";
                                        const DEFAULT_AVA = "{{ asset('images/gender/male.png') }}";

                                        let modalRowIndex = 0;

                                        /* ===== Labels ===== */
                                        const SERVICE_LABEL = {
                                            complete: 'Komplettlösung', montage: 'Montage', product: 'Produkt', plan: 'Planung',
                                            maintenance: 'Wartung', repair: 'Reparatur', reclaim: 'Reklamation',
                                            emergency: 'Notdienst', others: 'Sonstiges'
                                        };
                                        const INTEREST_LABEL = { intent: 'Kaufabsicht', interest: 'Kaufinteresse', option: 'Kaufoption' };
                                        const REALIZATION_LABEL = { soon: 'Schnellstmöglich', '3': '3 Monate', '6': '6 Monate', other: 'Sonstiges' };

                                        const tService = k => SERVICE_LABEL[(k || '').toLowerCase()] || (k || '');
                                        const tInterest = v => INTEREST_LABEL[v] || '-';
                                        const tRealization = v => REALIZATION_LABEL[String(v)] || '-';
                                        const empImg = f => f ? `${EMP_IMG_DIR}/${f}` : DEFAULT_AVA;

                                        const $existing = $('#existingProductRows');
                                        const $newRows = $('#modalNewRows');

                                        const debounce = (fn, ms) => { let t; return (...a) => { clearTimeout(t); t = setTimeout(() => fn(...a), ms); }; };
                                        const autoPickIfSingle = ($select) => {
                                            const opts = $select.find('option[value!=""]');
                                            if (!$select.val() && opts.length === 1) $select.val(opts.first().val()).trigger('change');
                                        };

                                        /* ===== Custom modal helpers ===== */
                                        const $addModal = $('#addCustomerProductModal');
                                        const $editModal = $('#editCustomerProduct');

                                        function openModal($m) {
                                            $m.addClass('is-open').attr('aria-hidden', 'false');
                                            document.body.classList.add('cmodal-open');
                                            // focus first focusable
                                            const el = $m.find('button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])').filter(':visible').first();
                                            if (el.length) el.trigger('focus');
                                        }

                                        function closeModal($m) {
                                            $m.removeClass('is-open').attr('aria-hidden', 'true');
                                            if (!$('.cmodal.is-open').length) document.body.classList.remove('cmodal-open');
                                        }

                                        // Close: backdrop + any [data-modal-close]
                                        $(document).on('click', '[data-modal-close]', function () {
                                            const $m = $(this).closest('.cmodal');
                                            if ($m.length) closeModal($m);
                                        });

                                        // Close: ESC
                                        $(document).on('keydown', function (e) {
                                            if (e.key === 'Escape') {
                                                const $m = $('.cmodal.is-open').last();
                                                if ($m.length) closeModal($m);
                                            }
                                        });

                                        /* ===== Select2 template for employees ===== */
                                        function employeeTpl(opt) {
                                            if (!opt.id) return opt.text;
                                            const $el = $(opt.element);
                                            const img = $el.data('img') ? `${EMP_IMG_DIR}/${$el.data('img')}` : DEFAULT_AVA;
                                            const pos = $el.data('positions') || '';
                                            return $(`
                                            <div style="display:flex;align-items:center;gap:8px;">
                                            <img src="${img}" style="width:32px;height:32px;border-radius:50%;object-fit:cover;">
                                            <div><strong>${opt.text}</strong><br><small>${pos}</small></div>
                                            </div>
                                        `);
                                        }

                                        function s2($el, opts) {
                                            if (!$el || !$el.length) return;
                                            if ($el.data('select2')) $el.select2('destroy');
                                            $el.select2(opts);
                                        }

                                        const addDropdownParent = $('#addCustomerProductModal .cmodal__dialog');
                                        const editDropdownParent = $('#editCustomerProduct .cmodal__dialog');

                                        /* ===== Open Add modal ===== */
                                        $(document).on('click', '.addNewProduct', function () {
                                            const customerId = $(this).data('id');
                                            const alternativeId = $(this).data('alternative-id');

                                            $('#modal_customer_id').val(customerId);
                                            $('#modal_alternative_id').val(alternativeId);

                                            $existing.empty();
                                            $newRows.empty();
                                            modalRowIndex = 0;

                                            // load saved rows
                                            $.get(`/lead/get/products/${customerId}/${alternativeId}`, (rows = []) => {
                                                $existing.empty();
                                                rows.forEach(row => {
                                                    const svcKey = row.service_phase_section
                                                        || (SERVICES.find(s => String(s.id) === String(row.service_id))?.phase_section)
                                                        || row.service_id;

                                                    $existing.append(`
                                                <tr>
                                                <td>${row.article_group || '-'}</td>
                                                <td>${tService(svcKey)}</td>
                                                <td>${row.department_name || '-'}</td>
                                                <td>
                                                    <div style="display:flex;align-items:center;gap:8px;">
                                                    <img src="${empImg(row.image)}" style="width:32px;height:32px;border-radius:50%;">
                                                    <span>${(`${row.name ?? ''} ${row.lastname ?? ''}`).trim() || '-'}</span>
                                                    </div>
                                                </td>
                                                <td>
                                                    <div style="display:flex;align-items:center;gap:8px;">
                                                    <img src="${empImg(row.feimage)}" style="width:32px;height:32px;border-radius:50%;">
                                                    <span>${(`${row.fename ?? ''} ${row.felastname ?? ''}`).trim() || '-'}</span>
                                                    </div>
                                                </td>
                                                <td>${tInterest(row.interest)}</td>
                                                <td>${tRealization(row.realization_time)}</td>
                                                <td>
                                                    <button type="button" class="btn btn-sm btn-warning edit-product"
                                                    data-id="${row.id}"
                                                    data-product-id="${row.product_id}"
                                                    data-service-id="${row.service_id ?? ''}"
                                                    data-department-id="${row.department_id ?? ''}"
                                                    data-employee-id="${row.employee_id ?? ''}"
                                                    data-field-employee="${row.field_employee_id ?? row.field_employee ?? ''}"
                                                    data-interest="${row.interest ?? ''}"
                                                    data-realization-time="${row.realization_time ?? ''}">
                                                    <i class="feather icon-edit"></i>
                                                    </button>
                                                    <button type="button" class="btn btn-sm btn-danger delete-product"
                                                    data-id="${row.id}"
                                                    data-customer-id="${row.customer_id}"
                                                    data-alternative-id="${row.alternative_id}"
                                                    data-product-id="${row.product_id}">
                                                    <i class="feather icon-trash"></i>
                                                    </button>
                                                </td>
                                                </tr>
                                            `);
                                                });
                                            });

                                            openModal($addModal);
                                            addRow();
                                        });

                                        /* ===== Add new editable row ===== */
                                        $('#modalAddRow').on('click', addRow);

                                        function addRow() {
                                            modalRowIndex++;
                                            $newRows.append(rowTemplate(modalRowIndex));
                                            initRow(modalRowIndex);
                                        }

                                        function rowTemplate(i) {
                                            return `
                                            <tr data-index="${i}">
                                            <td>
                                                <select class="form-control product-select" data-index="${i}" name="product_id[]" style="width:100%">
                                                <option value="">Produkt wählen</option>
                                                ${PRODUCTS.map(p => `<option value="${p.id}" data-img="${p.image || ''}">${p.article_group}</option>`).join('')}
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control service-select" data-index="${i}" name="service_id[]" style="width:100%">
                                                <option value="">Service wählen</option>
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control department-select" data-index="${i}" name="department_id[]" style="width:100%">
                                                <option value="">Abteilung wählen</option>
                                                ${DEPARTMENTS.map(d => `<option value="${d.id}">${d.department_name}</option>`).join('')}
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control employee-select" data-index="${i}" name="employee_id[]" style="width:100%">
                                                <option value="">Innendienst wählen</option>
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control field-employee-select" data-index="${i}" name="field_employee[]" style="width:100%">
                                                <option value="">Außendienst wählen</option>
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control interest-select" data-index="${i}" name="interest[]" style="width:100%">
                                                <option value="intent" selected>Kaufabsicht</option>
                                                <option value="interest">Kaufinteresse</option>
                                                <option value="option">Kaufoption</option>
                                                </select>
                                            </td>
                                            <td>
                                                <select class="form-control realization-select" data-index="${i}" name="realization_time[]" style="width:100%">
                                                <option value="">Bitte auswählen</option>
                                                <option value="soon" selected>Schnellstmöglich</option>
                                                <option value="3">3 Monate</option>
                                                <option value="6">6 Monate</option>
                                                <option value="other">Sonstiges</option>
                                                </select>
                                            </td>
                                            <td>
                                                <button type="button" class="btn btn-sm btn-outline-danger removeRow">
                                                <i class="feather icon-trash"></i>
                                                </button>
                                            </td>
                                            </tr>`;
                                        }

                                        /* ===== Per-row select2 + logic ===== */
                                        function initRow(i) {
                                            const q = cls => $(`.${cls}[data-index="${i}"]`);
                                            const $prod = q('product-select');
                                            const $serv = q('service-select');
                                            const $dept = q('department-select');
                                            const $emp = q('employee-select');
                                            const $femp = q('field-employee-select');

                                            // basic select2 inside modal
                                            [$prod, $serv, $dept, q('interest-select'), q('realization-select')].forEach($el => {
                                                s2($el, { width: '100%', dropdownParent: addDropdownParent });
                                            });

                                            // employees template
                                            [$emp, $femp].forEach($el => {
                                                s2($el, {
                                                    width: '100%',
                                                    dropdownParent: addDropdownParent,
                                                    templateResult: employeeTpl,
                                                    templateSelection: o => o.text,
                                                    escapeMarkup: m => m
                                                });
                                            });

                                            $prod.off('change.modal').on('change.modal', () => onProductChanged(i));
                                            $serv.off('change.modal').on('change.modal', debounce(() => loadEmployees(i), 120));
                                            $dept.off('change.modal').on('change.modal', debounce(() => loadEmployees(i), 120));
                                        }

                                        async function onProductChanged(i) {
                                            const $prod = $(`.product-select[data-index="${i}"]`);
                                            const $serv = $(`.service-select[data-index="${i}"]`);
                                            const $dept = $(`.department-select[data-index="${i}"]`);

                                            const pid = $prod.val();

                                            // services for selected product
                                            const list = SERVICES.filter(s => String(s.product_id) === String(pid));
                                            $serv.empty().append('<option value="">Service wählen</option>');
                                            list.forEach(s => $serv.append(`<option value="${s.id}">${tService(s.phase_section)}</option>`));
                                            $serv.trigger('change');

                                            if (!pid) { renderBothEmployees(i, [], []); return; }

                                            try {
                                                const resp = await $.post('{{ route("inquiry.department.employees") }}', {
                                                    _token: CSRF,
                                                    product_id: pid,
                                                    stage: STAGE
                                                });

                                                const suggestion = resp || {};
                                                let internalEmployees = [];
                                                let externalEmployees = [];

                                                if (Array.isArray(suggestion)) {
                                                    internalEmployees = suggestion;
                                                    externalEmployees = suggestion;
                                                } else {
                                                    internalEmployees = suggestion.internal_employees || suggestion.employees || [];
                                                    externalEmployees = suggestion.external_employees || suggestion.employees || [];
                                                }

                                                if (suggestion.department_id) {
                                                    const did = String(suggestion.department_id);
                                                    if (!$dept.find(`option[value="${did}"]`).length) {
                                                        $dept.append(`<option value="${did}">${DEPARTMENTS.find(d => String(d.id) === did)?.department_name || ('Abt. ' + did)}</option>`);
                                                    }
                                                    $dept.val(did).trigger('change.select2');
                                                }

                                                if (suggestion.service_id) {
                                                    const sid = String(suggestion.service_id);
                                                    if (!$serv.find(`option[value="${sid}"]`).length) {
                                                        const svc = SERVICES.find(s => String(s.id) === sid);
                                                        $serv.append(`<option value="${sid}">${tService(svc?.phase_section || '') || 'Service ' + sid}</option>`);
                                                    }
                                                    $serv.val(sid).trigger('change.select2');
                                                }

                                                if (internalEmployees.length || externalEmployees.length) {
                                                    renderBothEmployees(i, internalEmployees, externalEmployees);
                                                } else {
                                                    autoPickIfSingle($serv);
                                                    autoPickIfSingle($dept);
                                                    loadEmployees(i);
                                                }

                                            } catch (e) {
                                                autoPickIfSingle($serv);
                                                autoPickIfSingle($dept);
                                                loadEmployees(i);
                                            }
                                        }

                                        function renderBothEmployees(i, internalList, externalList) {
                                            const $emp = $(`.employee-select[data-index="${i}"]`);
                                            const $femp = $(`.field-employee-select[data-index="${i}"]`);

                                            const render = ($select, placeholder, list) => {
                                                $select.empty().append(`<option value="">${placeholder}</option>`);
                                                (list || []).forEach(e => {
                                                    $select.append(
                                                        `<option value="${e.id}"
                                                        data-img="${e.image || ''}"
                                                        data-positions="${(e.positions || []).join(', ')}">
                                                ${e.name} ${e.lastname}
                                                </option>`
                                                    );
                                                });
                                                s2($select, {
                                                    width: '100%',
                                                    dropdownParent: addDropdownParent,
                                                    templateResult: employeeTpl,
                                                    templateSelection: o => o.text,
                                                    escapeMarkup: m => m
                                                });
                                                autoPickIfSingle($select);
                                            };

                                            render($emp, 'Innendienst wählen', internalList);
                                            render($femp, 'Außendienst wählen', externalList);
                                        }

                                        function loadEmployees(i) {
                                            const $prod = $(`.product-select[data-index="${i}"]`);
                                            const $serv = $(`.service-select[data-index="${i}"]`);
                                            const $dept = $(`.department-select[data-index="${i}"]`);

                                            const pid = $prod.val();
                                            const sid = $serv.val();
                                            const did = $dept.val();

                                            if (!pid) { renderBothEmployees(i, [], []); return; }

                                            $.post('{{ route("inquiry.department.employees") }}', {
                                                _token: CSRF,
                                                product_id: pid,
                                                service_id: sid || null,
                                                department_id: did || null,
                                                stage: STAGE
                                            }, (resp = {}) => {
                                                let internalEmployees = [];
                                                let externalEmployees = [];

                                                if (Array.isArray(resp)) {
                                                    internalEmployees = resp;
                                                    externalEmployees = resp;
                                                } else {
                                                    if (resp.department_id && String(resp.department_id) !== String(did || '')) {
                                                        $dept.val(String(resp.department_id)).trigger('change.select2');
                                                    }
                                                    if (resp.service_id && String(resp.service_id) !== String(sid || '')) {
                                                        $serv.val(String(resp.service_id)).trigger('change.select2');
                                                    }
                                                    internalEmployees = resp.internal_employees || resp.employees || [];
                                                    externalEmployees = resp.external_employees || resp.employees || [];
                                                }

                                                renderBothEmployees(i, internalEmployees, externalEmployees);
                                            }).fail(() => {
                                                renderBothEmployees(i, [], []);
                                                Swal.fire({ icon: 'error', title: 'Fehler', text: 'Mitarbeiter konnten nicht geladen werden.' });
                                            });
                                        }

                                        /* ===== Remove new row ===== */
                                        $(document).on('click', '.removeRow', function () { $(this).closest('tr').remove(); });

                                        /* ===== Submit Add form ===== */
                                        $('#addCustomerProductForm').on('submit', async function (e) {
                                            e.preventDefault();

                                            if ($newRows.find('tr').length === 0) {
                                                return Swal.fire({ icon: 'warning', title: 'Hinweis', text: 'Bitte mindestens eine Zeile hinzufügen.' });
                                            }

                                            const $btn = $(this).find('button[type="submit"]');
                                            const old = $btn.html();
                                            $btn.prop('disabled', true).html('Speichern…');

                                            try {
                                                const res = await fetch($(this).attr('action'), {
                                                    method: 'POST',
                                                    headers: { 'X-CSRF-TOKEN': CSRF },
                                                    body: new FormData(this)
                                                });

                                                const txt = await res.text();
                                                let data; try { data = JSON.parse(txt); } catch { data = { ok: res.ok, message: txt || '' }; }

                                                if (!res.ok) {
                                                    if (res.status === 422 && data?.errors) {
                                                        const list = Object.values(data.errors).flat().join('\n');
                                                        return Swal.fire({ icon: 'error', title: 'Validierung', text: list || 'Bitte Eingaben prüfen.' });
                                                    }
                                                    return Swal.fire({ icon: 'error', title: 'Fehler', text: data?.message || `HTTP ${res.status}` });
                                                }

                                                Swal.fire({ icon: 'success', title: 'Gespeichert', text: data?.message || 'Produkte erfolgreich gespeichert.' })
                                                    .then(() => {
                                                        $newRows.empty();

                                                        const cid = $('#modal_customer_id').val();
                                                        const aid = $('#modal_alternative_id').val();

                                                        if (cid && aid) {
                                                            $.get(`/lead/get/products/${cid}/${aid}`, (rows = []) => {
                                                                $existing.empty();
                                                                rows.forEach(row => {
                                                                    const svcKey = row.service_phase_section
                                                                        || (SERVICES.find(s => String(s.id) === String(row.service_id))?.phase_section)
                                                                        || row.service_id;

                                                                    $existing.append(`
                                                        <tr>
                                                        <td>${row.article_group || '-'}</td>
                                                        <td>${tService(svcKey)}</td>
                                                        <td>${row.department_name || '-'}</td>
                                                        <td>
                                                            <div style="display:flex;align-items:center;gap:8px;">
                                                            <img src="${empImg(row.image)}" style="width:32px;height:32px;border-radius:50%;">
                                                            <span>${(`${row.name ?? ''} ${row.lastname ?? ''}`).trim() || '-'}</span>
                                                            </div>
                                                        </td>
                                                        <td>
                                                            <div style="display:flex;align-items:center;gap:8px;">
                                                            <img src="${empImg(row.feimage)}" style="width:32px;height:32px;border-radius:50%;">
                                                            <span>${(`${row.fename ?? ''} ${row.felastname ?? ''}`).trim() || '-'}</span>
                                                            </div>
                                                        </td>
                                                        <td>${tInterest(row.interest)}</td>
                                                        <td>${tRealization(row.realization_time)}</td>
                                                        <td>
                                                            <button type="button" class="btn btn-sm btn-warning edit-product"
                                                            data-id="${row.id}"
                                                            data-product-id="${row.product_id}"
                                                            data-service-id="${row.service_id ?? ''}"
                                                            data-department-id="${row.department_id ?? ''}"
                                                            data-employee-id="${row.employee_id ?? ''}"
                                                            data-field-employee="${row.field_employee_id ?? row.field_employee ?? ''}"
                                                            data-interest="${row.interest ?? ''}"
                                                            data-realization-time="${row.realization_time ?? ''}">
                                                            <i class="feather icon-edit"></i>
                                                            </button>
                                                            <button type="button" class="btn btn-sm btn-danger delete-product"
                                                            data-id="${row.id}"
                                                            data-customer-id="${row.customer_id}"
                                                            data-alternative-id="${row.alternative_id}"
                                                            data-product-id="${row.product_id}">
                                                            <i class="feather icon-trash"></i>
                                                            </button>
                                                        </td>
                                                        </tr>
                                                    `);
                                                                });
                                                            });
                                                        }
                                                    });

                                            } catch (err) {
                                                Swal.fire({ icon: 'error', title: 'Fehler', text: err?.message || 'Unerwarteter Fehler.' });
                                            } finally {
                                                $btn.prop('disabled', false).html(old);
                                            }
                                        });

                                        /* ===== Edit modal (opens from existing table) ===== */
                                        function fillEditStaticSelects() {
                                            const $interest = $('#edit_interest');
                                            const $real = $('#edit_realization_time');

                                            if (!$interest.find('option').length) {
                                                $interest.append(`<option value="intent">Kaufabsicht</option>`)
                                                    .append(`<option value="interest">Kaufinteresse</option>`)
                                                    .append(`<option value="option">Kaufoption</option>`);
                                            }
                                            if (!$real.find('option').length) {
                                                $real.append(`<option value="soon">Schnellstmöglich</option>`)
                                                    .append(`<option value="3">3 Monate</option>`)
                                                    .append(`<option value="6">6 Monate</option>`)
                                                    .append(`<option value="other">Sonstiges</option>`);
                                            }

                                            ['#edit_product', '#edit_service', '#edit_department', '#edit_interest', '#edit_realization_time'].forEach(sel => {
                                                s2($(sel), { width: '100%', dropdownParent: editDropdownParent });
                                            });

                                            // employee selects with template
                                            s2($('#edit_employee'), {
                                                width: '100%',
                                                dropdownParent: editDropdownParent,
                                                templateResult: employeeTpl,
                                                templateSelection: o => o.text,
                                                escapeMarkup: m => m
                                            });
                                            s2($('#edit_field_employee'), {
                                                width: '100%',
                                                dropdownParent: editDropdownParent,
                                                templateResult: employeeTpl,
                                                templateSelection: o => o.text,
                                                escapeMarkup: m => m
                                            });
                                        }

                                        function setEditServices(pid, selectedSid) {
                                            const $serv = $('#edit_service');
                                            $serv.empty().append('<option value="">Wählen...</option>');
                                            SERVICES.filter(s => String(s.product_id) === String(pid))
                                                .forEach(s => $serv.append(`<option value="${s.id}">${tService(s.phase_section)}</option>`));
                                            $serv.val(selectedSid || '').trigger('change.select2');
                                        }

                                        function renderEditEmployees(internalList, externalList, selectedEmp, selectedFemp) {
                                            const $emp = $('#edit_employee');
                                            const $femp = $('#edit_field_employee');

                                            const render = ($select, placeholder, list, selected) => {
                                                $select.empty().append(`<option value="">${placeholder}</option>`);
                                                (list || []).forEach(e => {
                                                    $select.append(
                                                        `<option value="${e.id}"
                                                        data-img="${e.image || ''}"
                                                        data-positions="${(e.positions || []).join(', ')}">
                                                ${e.name} ${e.lastname}
                                                </option>`
                                                    );
                                                });
                                                $select.val(selected || '').trigger('change.select2');
                                            };

                                            render($emp, 'Wählen...', internalList, selectedEmp);
                                            render($femp, 'Wählen...', externalList, selectedFemp);

                                            // re-apply template select2 (keeps avatars)
                                            fillEditStaticSelects();
                                        }

                                        async function loadEditEmployees(pid, sid, did, selectedEmp, selectedFemp) {
                                            try {
                                                const resp = await $.post('{{ route("inquiry.department.employees") }}', {
                                                    _token: CSRF,
                                                    product_id: pid,
                                                    service_id: sid || null,
                                                    department_id: did || null,
                                                    stage: STAGE
                                                });

                                                let internalEmployees = [];
                                                let externalEmployees = [];
                                                if (Array.isArray(resp)) {
                                                    internalEmployees = resp;
                                                    externalEmployees = resp;
                                                } else {
                                                    internalEmployees = resp.internal_employees || resp.employees || [];
                                                    externalEmployees = resp.external_employees || resp.employees || [];
                                                }

                                                renderEditEmployees(internalEmployees, externalEmployees, selectedEmp, selectedFemp);
                                            } catch (e) {
                                                renderEditEmployees([], [], selectedEmp, selectedFemp);
                                            }
                                        }

                                        $(document).on('click', '.edit-product', function () {
                                            const id = $(this).data('id');
                                            const pid = $(this).data('product-id');
                                            const sid = $(this).data('service-id');
                                            const did = $(this).data('department-id');
                                            const emp = $(this).data('employee-id');
                                            const femp = $(this).data('field-employee');

                                            $('#edit_product_id').val(id);

                                            fillEditStaticSelects();

                                            $('#edit_product').val(pid).trigger('change.select2');
                                            setEditServices(pid, sid);
                                            $('#edit_department').val(did || '').trigger('change.select2');

                                            $('#edit_interest').val($(this).data('interest') || 'intent').trigger('change.select2');
                                            $('#edit_realization_time').val($(this).data('realization-time') || 'soon').trigger('change.select2');

                                            openModal($editModal);

                                            loadEditEmployees(pid, sid, did, emp, femp);
                                        });

                                        // When product/service/department changes inside edit modal, refresh dependent lists
                                        $(document).on('change', '#edit_product', function () {
                                            const pid = $(this).val();
                                            setEditServices(pid, null);
                                            loadEditEmployees(pid, $('#edit_service').val(), $('#edit_department').val(), $('#edit_employee').val(), $('#edit_field_employee').val());
                                        });
                                        $(document).on('change', '#edit_service, #edit_department', debounce(function () {
                                            loadEditEmployees($('#edit_product').val(), $('#edit_service').val(), $('#edit_department').val(), $('#edit_employee').val(), $('#edit_field_employee').val());
                                        }, 120));

                                    })();
                                </script>


                                <script>
                                    // 1. Main Load Function (Triggered by your button)
                                    function loadHistory(cid, aid, pid) {
                                        const $mainContent = $('#mainContent');

                                        // Show Loader
                                        $mainContent.html(`
                                        <div class="d-flex justify-content-center align-items-center" style="height: 100%;">
                                            <div class="spinner-border text-primary" role="status">
                                                <span class="sr-only">Loading...</span>
                                            </div>
                                        </div>
                                    `);

                                        // AJAX Call
                                        let url = `/new-leads/${cid}/history-feed`;
                                        let params = {
                                            alternative_id: aid,
                                            product_id: pid
                                        };

                                        $.ajax({
                                            url: url,
                                            type: 'GET',
                                            data: params,
                                            success: function (response) {
                                                $mainContent.html(response);

                                                // Re-init Feather icons if using feather
                                                if (typeof feather !== 'undefined') feather.replace();
                                            },
                                            error: function (xhr) {
                                                console.error('History load failed', xhr);
                                                $mainContent.html('<div class="alert alert-danger m-4">Fehler beim Laden der Historie.</div>');
                                            }
                                        });
                                    }

                                    // 2. Debounce Function for Search
                                    function debounceHistory(func, wait) {
                                        let timeout;
                                        return function () {
                                            const context = this, args = arguments;
                                            clearTimeout(timeout);
                                            timeout = setTimeout(() => func.apply(context, args), wait);
                                        };
                                    }

                                    // 3. EVENT DELEGATION (This works even on dynamically loaded content)

                                    // Handle Input Typing
                                    $(document).on('input', '#historySearchText', debounceHistory(function () {
                                        performHistoryRefresh();
                                    }, 600));

                                    // Handle Date Change
                                    $(document).on('change', '#historySearchDate', function () {
                                        performHistoryRefresh();
                                    });

                                    // Handle Reset Button
                                    $(document).on('click', '#btnResetHistory', function () {
                                        $('#historySearchText').val('');
                                        $('#historySearchDate').val('');
                                        performHistoryRefresh();
                                    });

                                    // 4. The Refresh Logic
                                    function performHistoryRefresh() {
                                        // We read the IDs from the data-attributes we put in the HTML wrapper
                                        const $wrapper = $('.history-wrapper');
                                        const cid = $wrapper.data('current-cid');
                                        const aid = $wrapper.data('current-aid');
                                        const pid = $wrapper.data('current-pid');

                                        const text = $('#historySearchText').val();
                                        const date = $('#historySearchDate').val();

                                        // Select the container to swap
                                        // We want to replace just the body if possible, OR the whole wrapper. 
                                        // Replacing the whole wrapper is easier to keep consistent.
                                        const $container = $('#mainContent');

                                        // Visual feedback (optional opacity change)
                                        $wrapper.css('opacity', '0.6');

                                        $.ajax({
                                            url: `/new-leads/${cid}/history-feed`,
                                            type: 'GET',
                                            data: {
                                                alternative_id: aid,
                                                product_id: pid,
                                                search_text: text,
                                                search_date: date
                                            },
                                            success: function (response) {
                                                $container.html(response);
                                                if (typeof feather !== 'undefined') feather.replace();
                                            },
                                            error: function () {
                                                alert('Fehler beim Filtern.');
                                                $wrapper.css('opacity', '1');
                                            }
                                        });
                                    }
                                    // Helper to handle the "Active" state of your nav buttons (optional)
                                    function setActiveSubNav(btn) {
                                        // Remove active class from all buttons with .nav-section-btn
                                        $('.nav-section-btn').removeClass('active btn-secondary').addClass('btn-outline-secondary');

                                        // Add active class to clicked button
                                        $(btn).removeClass('btn-outline-secondary').addClass('active btn-secondary');
                                    }
                                </script>
                                 <script>
                                    window.NEW_LEADS = window.NEW_LEADS || {};

                                    window.NEW_LEADS.invoicePanelUrl = {!! json_encode(
        route('admin.new_leads.invoices.panel', [
            'customer' => '__CID__',
            'alternative' => '__AID__',
            'product' => '__PID__',
        ])
    ) !!};
                                </script>

                                <script>
                                    /*
                                    |--------------------------------------------------------------------------
                                    | NEW LEADS — Invoice Panel Loader + PDF Upload/Viewer
                                    |--------------------------------------------------------------------------
                                    | loadInvoice(cid, aid, pid)
                                    | - Loads invoices partial into #mainContent
                                    | - Supports PDF upload inside AJAX-loaded invoice partial
                                    | - Supports PDF modal preview, download, and delete
                                    */
                                    (function () {
                                        "use strict";

                                        if (window.__NEW_LEADS_INVOICE_PANEL_SCRIPT_READY__) {
                                            return;
                                        }

                                        window.__NEW_LEADS_INVOICE_PANEL_SCRIPT_READY__ = true;

                                        const mainEl = document.getElementById("mainContent");

                                        const csrf =
                                            document.querySelector('meta[name="csrf-token"]')?.getAttribute("content") || "";

                                        const urlTpl = String(window.NEW_LEADS?.invoicePanelUrl || "");

                                        let activeAbort = null;

                                        function escapeHtml(value) {
                                            return String(value ?? "")
                                                .replaceAll("&", "&amp;")
                                                .replaceAll("<", "&lt;")
                                                .replaceAll(">", "&gt;")
                                                .replaceAll('"', "&quot;")
                                                .replaceAll("'", "&#039;");
                                        }

                                        function cssEscape(value) {
                                            if (window.CSS && typeof window.CSS.escape === "function") {
                                                return window.CSS.escape(String(value));
                                            }

                                            return String(value).replace(/["\\]/g, "\\$&");
                                        }

                                        function buildInvoicePanelUrl(cid, aid, pid) {
                                            if (!urlTpl) {
                                                throw new Error("invoicePanelUrl template missing.");
                                            }

                                            return urlTpl
                                                .replace("__CID__", encodeURIComponent(cid || 0))
                                                .replace("__AID__", encodeURIComponent(aid || 0))
                                                .replace("__PID__", encodeURIComponent(pid || 0));
                                        }

                                        function invoiceSkeleton() {
                                            return `
                                                <div style="padding:18px;">
                                                    <div style="display:flex;gap:12px;align-items:center;justify-content:space-between;flex-wrap:wrap;">
                                                        <div style="min-width:0;">
                                                            <div style="height:14px;width:220px;max-width:70vw;background:#e2e8f0;border-radius:999px;"></div>
                                                            <div style="height:10px;width:360px;max-width:80vw;background:#eef2f7;border-radius:999px;margin-top:10px;"></div>
                                                        </div>

                                                        <div style="height:38px;width:140px;background:#eef2f7;border-radius:12px;"></div>
                                                    </div>

                                                    <div style="display:flex;gap:8px;flex-wrap:wrap;margin-top:14px;">
                                                        <div style="height:40px;width:190px;background:#e2e8f0;border-radius:12px;"></div>
                                                        <div style="height:40px;width:210px;background:#eef2f7;border-radius:12px;"></div>
                                                    </div>

                                                    <div style="margin-top:14px;border:1px solid #e2e8f0;border-radius:18px;overflow:hidden;background:#fff;">
                                                        <div style="padding:14px;border-bottom:1px solid #e2e8f0;background:#f8fafc;">
                                                            <div style="height:10px;width:260px;background:#e2e8f0;border-radius:999px;"></div>
                                                        </div>

                                                        <div style="padding:14px;display:grid;gap:10px;">
                                                            ${Array.from({ length: 7 }).map(() => `
                                                                <div style="display:flex;gap:12px;align-items:center;">
                                                                    <div style="height:12px;width:90px;background:#eef2f7;border-radius:999px;"></div>
                                                                    <div style="height:12px;flex:1;background:#eef2f7;border-radius:999px;"></div>
                                                                    <div style="height:12px;width:120px;background:#eef2f7;border-radius:999px;"></div>
                                                                </div>
                                                            `).join("")}
                                                        </div>
                                                    </div>
                                                </div>
                                            `;
                                        }

                                        function renderInvoiceError(message) {
                                            if (!mainEl) return;

                                            mainEl.innerHTML = `
                                                <div style="padding:18px;">
                                                    <div style="border:1px solid rgba(220,38,38,.25);background:rgba(220,38,38,.06);border-radius:16px;padding:14px;">
                                                        <div style="font-weight:900;color:#991b1b;">Fehler</div>
                                                        <div style="margin-top:6px;color:#7f1d1d;font-weight:700;">
                                                            ${escapeHtml(message || "Request failed")}
                                                        </div>
                                                    </div>
                                                </div>
                                            `;
                                        }

                                        async function fetchJson(url, options = {}) {
                                            const response = await fetch(url, {
                                                ...options,
                                                headers: {
                                                    "Accept": "application/json",
                                                    "X-Requested-With": "XMLHttpRequest",
                                                    "X-CSRF-TOKEN": csrf,
                                                    ...(options.headers || {}),
                                                },
                                            });

                                            const contentType = (response.headers.get("content-type") || "").toLowerCase();

                                            let json = {};
                                            if (contentType.includes("application/json")) {
                                                json = await response.json().catch(() => ({}));
                                            }

                                            if (!response.ok || json?.ok === false) {
                                                const message =
                                                    json?.message ||
                                                    (json?.errors ? Object.values(json.errors).flat().join(" ") : "") ||
                                                    `Request failed (${response.status})`;

                                                throw new Error(message);
                                            }

                                            return json;
                                        }

                                        async function loadInvoice(cid, aid, pid) {
                                            if (!mainEl) {
                                                console.warn("#mainContent not found.");
                                                return;
                                            }

                                            if (activeAbort) {
                                                activeAbort.abort();
                                            }

                                            activeAbort = new AbortController();

                                            mainEl.style.transition = "";
                                            mainEl.style.opacity = "1";
                                            mainEl.innerHTML = invoiceSkeleton();

                                            try {
                                                const url = buildInvoicePanelUrl(cid, aid, pid);

                                                const response = await fetch(url, {
                                                    method: "GET",
                                                    headers: {
                                                        "Accept": "application/json",
                                                        "X-Requested-With": "XMLHttpRequest",
                                                        "X-CSRF-TOKEN": csrf,
                                                    },
                                                    signal: activeAbort.signal,
                                                });

                                                const contentType = (response.headers.get("content-type") || "").toLowerCase();
                                                const json = contentType.includes("application/json")
                                                    ? await response.json().catch(() => null)
                                                    : null;

                                                if (!response.ok || !json || json.ok !== true) {
                                                    throw new Error(json?.message || `Request failed (${response.status})`);
                                                }

                                                mainEl.style.opacity = "0.25";
                                                mainEl.innerHTML = json.html || "";

                                                requestAnimationFrame(() => {
                                                    mainEl.style.transition = "opacity .14s ease";
                                                    mainEl.style.opacity = "1";
                                                });
                                            } catch (error) {
                                                if (String(error?.name) === "AbortError") return;

                                                renderInvoiceError(error?.message || "Load failed");
                                            }
                                        }

                                        window.loadInvoice = loadInvoice;

                                        /*
                                        |--------------------------------------------------------------------------
                                        | PDF Helpers
                                        |--------------------------------------------------------------------------
                                        */

                                        function closestPanel(element) {
                                            return element?.closest?.(".nl-invoice-panel") || document.querySelector(".nl-invoice-panel");
                                        }

                                        function templateUrl(panel, key, id) {
                                            const template = panel?.dataset?.[key] || "";

                                            if (!template) {
                                                throw new Error("URL template missing: " + key);
                                            }

                                            return template.replace("__ID__", encodeURIComponent(id));
                                        }

                                        function shortFileName(name) {
                                            name = String(name || "datei.pdf");

                                            if (name.length <= 36) {
                                                return name;
                                            }

                                            return name.slice(0, 20) + "…" + name.slice(-12);
                                        }

                                        function setPickedHint(invoiceId, text) {
                                            const selector = `[data-nl-picked-hint="${cssEscape(invoiceId)}"]`;
                                            const hint = document.querySelector(selector);

                                            if (hint) {
                                                hint.textContent = text || "";
                                            }
                                        }

                                        function buildUploadedFileChip(panel, invoiceId, file) {
                                            const fileId = file?.id;
                                            const fileName = file?.original_name || file?.stored_name || "datei.pdf";

                                            if (!fileId) return "";

                                            const downloadUrl = templateUrl(panel, "downloadFileUrl", fileId);

                                            return `
                                                <span class="nl-inv-pdf-chip"
                                                    data-nl-open-pdf
                                                    data-file-id="${escapeHtml(fileId)}"
                                                    data-file-name="${escapeHtml(fileName)}">
                                                    <i class="fa-solid fa-file-pdf"></i>

                                                    <span class="nl-inv-trunc">${escapeHtml(shortFileName(fileName))}</span>

                                                    <span class="nl-inv-pdf-actions">
                                                        <a class="nl-inv-pdf-mini"
                                                        href="${escapeHtml(downloadUrl)}"
                                                        title="Herunterladen"
                                                        onclick="event.stopPropagation();">
                                                            <i class="fa-solid fa-download"></i>
                                                        </a>

                                                        <button type="button"
                                                                class="nl-inv-pdf-mini danger"
                                                                title="Löschen"
                                                                data-nl-delete-file="${escapeHtml(fileId)}"
                                                                data-invoice-id="${escapeHtml(invoiceId)}"
                                                                onclick="event.stopPropagation();">
                                                            <i class="fa-solid fa-trash"></i>
                                                        </button>
                                                    </span>
                                                </span>
                                            `;
                                        }

                                        function addUploadedFileChip(invoiceId, file) {
                                            const list = document.querySelector(`[data-nl-files-list="${cssEscape(invoiceId)}"]`);
                                            if (!list) return;

                                            const panel = closestPanel(list);
                                            if (!panel) return;

                                            const empty = list.querySelector("[data-nl-no-files]");
                                            if (empty) {
                                                empty.remove();
                                            }

                                            list.insertAdjacentHTML("beforeend", buildUploadedFileChip(panel, invoiceId, file));
                                        }

                                        function openPdfModal(panel, fileId, fileName) {
                                            const modal = panel.querySelector("[data-nl-pdf-modal]");
                                            const backdrop = panel.querySelector("[data-nl-pdf-backdrop]");
                                            const frame = panel.querySelector("[data-nl-pdf-frame]");
                                            const title = panel.querySelector("[data-nl-pdf-title]");
                                            const openNew = panel.querySelector("[data-nl-pdf-newtab]");
                                            const download = panel.querySelector("[data-nl-pdf-download]");

                                            const viewUrl = templateUrl(panel, "viewFileUrl", fileId);
                                            const downloadUrl = templateUrl(panel, "downloadFileUrl", fileId);

                                            if (title) title.textContent = fileName || "PDF";
                                            if (frame) frame.src = viewUrl;
                                            if (openNew) openNew.href = viewUrl;
                                            if (download) download.href = downloadUrl;

                                            backdrop?.classList.add("active");
                                            modal?.classList.add("active");

                                            document.body.style.overflow = "hidden";
                                        }

                                        function closePdfModal(panel) {
                                            if (!panel) return;

                                            const modal = panel.querySelector("[data-nl-pdf-modal]");
                                            const backdrop = panel.querySelector("[data-nl-pdf-backdrop]");
                                            const frame = panel.querySelector("[data-nl-pdf-frame]");

                                            backdrop?.classList.remove("active");
                                            modal?.classList.remove("active");

                                            if (frame) {
                                                frame.src = "about:blank";
                                            }

                                            document.body.style.overflow = "";
                                        }

                                        /*
                                        |--------------------------------------------------------------------------
                                        | Delegated Events — works after AJAX innerHTML
                                        |--------------------------------------------------------------------------
                                        */

                                        document.addEventListener("click", async function (event) {
                                            const pickButton = event.target.closest("[data-nl-pick-files]");
                                            if (pickButton) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                const invoiceId = pickButton.getAttribute("data-nl-pick-files");
                                                const input = document.querySelector(`[data-nl-file-input="${cssEscape(invoiceId)}"]`);

                                                if (input) {
                                                    input.click();
                                                }

                                                return;
                                            }

                                            const uploadButton = event.target.closest("[data-nl-upload-files]");
                                            if (uploadButton) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                const invoiceId = uploadButton.getAttribute("data-nl-upload-files");
                                                const panel = closestPanel(uploadButton);
                                                const input = document.querySelector(`[data-nl-file-input="${cssEscape(invoiceId)}"]`);

                                                if (!panel || !input) return;

                                                const files = Array.from(input.files || []).filter(file => {
                                                    const type = String(file.type || "").toLowerCase();
                                                    const name = String(file.name || "").toLowerCase();

                                                    return type.includes("pdf") || name.endsWith(".pdf");
                                                });

                                                if (!files.length) {
                                                    alert("Bitte zuerst eine oder mehrere PDF-Dateien wählen.");
                                                    return;
                                                }

                                                const formData = new FormData();
                                                files.forEach(file => formData.append("files[]", file));

                                                const oldHtml = uploadButton.innerHTML;

                                                uploadButton.disabled = true;
                                                uploadButton.innerHTML = `<i class="fa-solid fa-spinner fa-spin"></i> Lade hoch...`;

                                                try {
                                                    const uploadUrl = templateUrl(panel, "uploadUrl", invoiceId);

                                                    const json = await fetchJson(uploadUrl, {
                                                        method: "POST",
                                                        body: formData,
                                                    });

                                                    const uploadedFiles = Array.isArray(json.files) ? json.files : [];

                                                    uploadedFiles.forEach(file => {
                                                        addUploadedFileChip(invoiceId, file);
                                                    });

                                                    input.value = "";
                                                    setPickedHint(invoiceId, "Upload erfolgreich.");
                                                } catch (error) {
                                                    alert(error?.message || "Upload fehlgeschlagen");
                                                } finally {
                                                    uploadButton.disabled = false;
                                                    uploadButton.innerHTML = oldHtml;
                                                }

                                                return;
                                            }

                                            const pdfChip = event.target.closest("[data-nl-open-pdf]");
                                            if (pdfChip) {
                                                event.preventDefault();

                                                if (event.target.closest("a, button")) {
                                                    return;
                                                }

                                                const panel = closestPanel(pdfChip);
                                                const fileId = pdfChip.getAttribute("data-file-id");
                                                const fileName = pdfChip.getAttribute("data-file-name") || "PDF";

                                                if (panel && fileId) {
                                                    openPdfModal(panel, fileId, fileName);
                                                }

                                                return;
                                            }

                                            const deleteButton = event.target.closest("[data-nl-delete-file]");
                                            if (deleteButton) {
                                                event.preventDefault();
                                                event.stopPropagation();

                                                if (!confirm("PDF wirklich löschen?")) {
                                                    return;
                                                }

                                                const panel = closestPanel(deleteButton);
                                                const fileId = deleteButton.getAttribute("data-nl-delete-file");

                                                if (!panel || !fileId) return;

                                                try {
                                                    const deleteUrl = templateUrl(panel, "deleteFileUrl", fileId);

                                                    await fetchJson(deleteUrl, {
                                                        method: "DELETE",
                                                    });

                                                    const chip = deleteButton.closest(".nl-inv-pdf-chip");
                                                    const list = chip?.closest(".nl-inv-pdf-list");

                                                    if (chip) {
                                                        chip.remove();
                                                    }

                                                    if (list && !list.querySelector(".nl-inv-pdf-chip")) {
                                                        list.innerHTML = `
                                                            <span class="nl-inv-no-files" data-nl-no-files>
                                                                Keine PDF
                                                            </span>
                                                        `;
                                                    }
                                                } catch (error) {
                                                    alert(error?.message || "PDF konnte nicht gelöscht werden");
                                                }

                                                return;
                                            }

                                            const closePdfButton = event.target.closest("[data-nl-pdf-close]");
                                            if (closePdfButton) {
                                                event.preventDefault();

                                                const panel = closestPanel(closePdfButton);
                                                closePdfModal(panel);

                                                return;
                                            }

                                            const pdfBackdrop = event.target.closest("[data-nl-pdf-backdrop]");
                                            if (pdfBackdrop) {
                                                const panel = closestPanel(pdfBackdrop);
                                                closePdfModal(panel);
                                            }
                                        });

                                        document.addEventListener("change", function (event) {
                                            const input = event.target.closest("[data-nl-file-input]");
                                            if (!input) return;

                                            const invoiceId = input.getAttribute("data-nl-file-input");
                                            const files = Array.from(input.files || []);

                                            if (!files.length) {
                                                setPickedHint(invoiceId, "");
                                                return;
                                            }

                                            const names = files.slice(0, 3).map(file => file.name).join(", ");
                                            const more = files.length > 3 ? ` +${files.length - 3} weitere` : "";

                                            setPickedHint(invoiceId, `Ausgewählt: ${names}${more}`);
                                        });

                                        document.addEventListener("keydown", function (event) {
                                            if (event.key !== "Escape") return;

                                            document.querySelectorAll(".nl-invoice-panel").forEach(panel => {
                                                closePdfModal(panel);
                                            });
                                        });
                                    })();
                                </script>

                                <script>
                                    (function () {
                                        "use strict";

                                        if (window.__NL_INVOICE_PDF_MODAL_READY__) return;
                                        window.__NL_INVOICE_PDF_MODAL_READY__ = true;

                                        function closestPanel(el) {
                                            return el?.closest?.(".nl-invoice-panel") || document.querySelector(".nl-invoice-panel");
                                        }

                                        function openPdfModal(panel, viewUrl, downloadUrl, fileName) {
                                            if (!panel || !viewUrl) return;

                                            const backdrop = panel.querySelector("[data-nl-pdf-backdrop]");
                                            const modal = panel.querySelector("[data-nl-pdf-modal]");
                                            const frame = panel.querySelector("[data-nl-pdf-frame]");
                                            const title = panel.querySelector("[data-nl-pdf-title]");
                                            const newTab = panel.querySelector("[data-nl-pdf-newtab]");
                                            const download = panel.querySelector("[data-nl-pdf-download]");

                                            if (!backdrop || !modal || !frame) {
                                                console.warn("PDF modal elements not found.");
                                                window.open(viewUrl, "_blank", "noopener");
                                                return;
                                            }

                                            if (title) title.textContent = fileName || "PDF";
                                            if (frame) frame.src = viewUrl;
                                            if (newTab) newTab.href = viewUrl;
                                            if (download) download.href = downloadUrl || viewUrl;

                                            backdrop.classList.add("active");
                                            modal.classList.add("active");

                                            document.body.style.overflow = "hidden";
                                        }

                                        function closePdfModal(panel) {
                                            if (!panel) return;

                                            const backdrop = panel.querySelector("[data-nl-pdf-backdrop]");
                                            const modal = panel.querySelector("[data-nl-pdf-modal]");
                                            const frame = panel.querySelector("[data-nl-pdf-frame]");

                                            if (backdrop) backdrop.classList.remove("active");
                                            if (modal) modal.classList.remove("active");
                                            if (frame) frame.src = "about:blank";

                                            document.body.style.overflow = "";
                                        }

                                        document.addEventListener("click", function (event) {
                                            const pdfBtn = event.target.closest("[data-nl-local-open-pdf]");

                                            if (pdfBtn) {
                                                if (event.target.closest("a, [data-nl-delete-file]")) return;

                                                event.preventDefault();
                                                event.stopPropagation();

                                                const panel = closestPanel(pdfBtn);

                                                openPdfModal(
                                                    panel,
                                                    pdfBtn.getAttribute("data-view-url"),
                                                    pdfBtn.getAttribute("data-download-url"),
                                                    pdfBtn.getAttribute("data-file-name") || "PDF"
                                                );

                                                return;
                                            }

                                            const closeBtn = event.target.closest("[data-nl-pdf-close]");
                                            if (closeBtn) {
                                                event.preventDefault();
                                                closePdfModal(closestPanel(closeBtn));
                                                return;
                                            }

                                            const backdrop = event.target.closest("[data-nl-pdf-backdrop]");
                                            if (backdrop) {
                                                closePdfModal(closestPanel(backdrop));
                                            }
                                        });

                                        document.addEventListener("keydown", function (event) {
                                            if (event.key !== "Escape") return;

                                            document.querySelectorAll(".nl-invoice-panel").forEach(function (panel) {
                                                closePdfModal(panel);
                                            });
                                        });
                                    })();
                                </script>

                                <script>
                                    (() => {
                                        "use strict";

                                        // ============================================================
                                        // 1) CONFIG
                                        // ============================================================
                                        const CONFIG = window.__OBJ_MODAL || {};
                                        const CSRF_TOKEN = document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';

                                        const DOM = {
                                            root: document.getElementById('objDrawerRoot'),
                                            backdrop: document.getElementById('objDrawerBackdrop'),
                                            panel: document.getElementById('objDrawerPanel'),
                                            customerLine: document.getElementById('drawerCustomerLine'),
                                            loading: document.getElementById('drawerLoading'),
                                            grid: document.getElementById('drawerObjectsGrid'),
                                            cols: document.getElementById('drawerObjectsCols'),
                                            createPanel: document.getElementById('drawerCreatePanel'),
                                            createMsg: document.getElementById('createObjectMsg'),
                                            inputs: {
                                                name: document.getElementById('co_object_name'),
                                                date: document.getElementById('co_request_date'),
                                                address: document.getElementById('co_address_search'),
                                                fullAddress: document.getElementById('co_full_address'),
                                                street: document.getElementById('co_street'),
                                                postcode: document.getElementById('co_postcode'),
                                                city: document.getElementById('co_city'),
                                                lat: document.getElementById('co_lat'),
                                                lon: document.getElementById('co_lon'),
                                                objective: document.getElementById('co_objective'),
                                                note: document.getElementById('co_note'),
                                                map: document.getElementById('co_map'),
                                            }
                                        };

                                        const STATE = {
                                            customerId: null,
                                            objectsData: [],
                                            sortableInstances: [],
                                            map: null,
                                            marker: null,
                                            geocoder: null,
                                            autocomplete: null,
                                        };

                                        // ============================================================
                                        // 2) SVG ICONS (inline)
                                        // ============================================================
                                        const Icons = {
                                            trash: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                                        <path d="M9 3h6l1 2h4v2H4V5h4l1-2z" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                        <path d="M7 9v10a2 2 0 0 0 2 2h6a2 2 0 0 0 2-2V9" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                        <path d="M10 12v6M14 12v6" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                                    </svg>`,
                                            x: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                                        <path d="M18 6 6 18M6 6l12 12" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                    </svg>`,
                                            arrowRight: `<svg width="16" height="16" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                                        <path d="M5 12h12" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                                        <path d="m13 6 6 6-6 6" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                    </svg>`,
                                            warning: `<svg width="18" height="18" viewBox="0 0 24 24" fill="none" aria-hidden="true">
                                        <path d="M10.29 3.86 1.82 18a2 2 0 0 0 1.71 3h16.94a2 2 0 0 0 1.71-3L13.71 3.86a2 2 0 0 0-3.42 0Z"
                                        stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"/>
                                        <path d="M12 9v4" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                                        <path d="M12 17h.01" stroke="currentColor" stroke-width="2" stroke-linecap="round"/>
                                    </svg>`,
                                        };

                                        // ============================================================
                                        // 3) HELPERS
                                        // ============================================================
                                        const Utils = {
                                            esc: (s) => String(s ?? '').replace(/[&<>"']/g, m => ({
                                                '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#039;'
                                            }[m])),
                                            url: (tpl, id) => String(tpl).replace('___ID___', String(id)),
                                            http: async (url, method = 'GET', data = null) => {
                                                const options = {
                                                    method,
                                                    headers: {
                                                        'Accept': 'application/json',
                                                        'X-Requested-With': 'XMLHttpRequest',
                                                        ...(CSRF_TOKEN ? { 'X-CSRF-TOKEN': CSRF_TOKEN } : {}),
                                                        ...(data ? { 'Content-Type': 'application/json' } : {})
                                                    },
                                                    credentials: 'same-origin',
                                                    body: data ? JSON.stringify(data) : null
                                                };

                                                const res = await fetch(url, options);
                                                const json = await res.json().catch(() => ({}));
                                                if (!res.ok) throw new Error(json?.message || `Request failed: ${res.status}`);
                                                return json;
                                            },
                                            ensureSwal: () => {
                                                if (!window.Swal) {
                                                    throw new Error('SweetAlert2 (Swal) not loaded on this page.');
                                                }
                                            }
                                        };

                                        // ============================================================
                                        // 4) RENDERER (Bootstrap HTML + SVG buttons)
                                        // ============================================================
                                        const Renderer = {
                                            productCard: (p) => {
                                                const phaseKey = p.phase_section_key || '';
                                                const phaseLabel = CONFIG.phaseLabels?.[phaseKey] || (phaseKey || '—');
                                                const name = p.product_name || `Produkt #${p.product_id}`;
                                                const price = p.price ? Number(p.price).toFixed(2) + ' €' : '';

                                                return `
                                        <div class="prod-card shadow-sm" data-product-item="1" data-lead-product-id="${p.id}">
                                            <div class="d-flex justify-content-between align-items-start">
                                            <div style="overflow:hidden;">
                                                <div class="font-weight-bold text-dark text-truncate" style="max-width: 180px;" title="${Utils.esc(name)}">
                                                ${Utils.esc(name)}
                                                </div>
                                                <div class="small text-muted mt-1">
                                                <span class="badge badge-light border">${Utils.esc(phaseLabel)}</span>
                                                <span class="badge badge-light border">${Utils.esc(p.status || 'open')}</span>
                                                </div>
                                            </div>

                                            <div class="d-flex align-items-start" style="gap:8px;">
                                                <div class="small text-dark font-weight-bold" style="white-space: nowrap;">
                                                ${Utils.esc(price)}
                                                </div>

                                                <button type="button"
                                                class="btn btn-sm btn-outline-danger py-0 px-2 d-inline-flex align-items-center justify-content-center"
                                                data-action="delete-product"
                                                data-product-id="${p.id}"
                                                title="Produkt löschen"
                                                aria-label="Produkt löschen">
                                                ${Icons.x}
                                                </button>
                                            </div>
                                            </div>
                                        </div>
                                        `;
                                            },

                                            objectCard: (obj) => {
                                                const name = obj.object_name || `Objekt #${obj.id}`;
                                                const address = obj.full_address
                                                    ? `<div class="small text-muted text-truncate" title="${Utils.esc(obj.full_address)}">${Utils.esc(obj.full_address)}</div>`
                                                    : '';
                                                const date = obj.request_date ? Utils.esc(obj.request_date) : '';
                                                const mainBadge = obj.main ? `<span class="badge badge-warning ml-2">HAUPT</span>` : '';

                                                const productsHtml = (obj.products && obj.products.length > 0)
                                                    ? obj.products.map(Renderer.productCard).join('')
                                                    : `<div class="small text-muted font-italic text-center p-3 border rounded" style="border-style: dashed !important;">Keine Produkte</div>`;

                                                return `
                                        <div class="col-12 col-md-6 col-lg-4 mb-4">
                                            <div class="obj-card h-100 d-flex flex-column" data-object-card="${obj.id}">
                                            <div class="obj-card-header">
                                                <div class="d-flex justify-content-between align-items-start">
                                                <div style="overflow:hidden; padding-right:10px;">
                                                    <div class="font-weight-bold text-dark text-truncate" title="${Utils.esc(name)}">
                                                    ${Utils.esc(name)} ${mainBadge}
                                                    </div>
                                                    ${address}
                                                </div>

                                                <div class="d-flex flex-column align-items-end" style="gap:6px;">
                                                    <div class="small text-muted text-nowrap">${date}</div>
                                                    <button type="button"
                                                    class="btn btn-sm btn-outline-danger py-0 px-2 d-inline-flex align-items-center justify-content-center"
                                                    data-action="delete-object"
                                                    data-object-id="${obj.id}"
                                                    title="Objekt löschen"
                                                    aria-label="Objekt löschen">
                                                    ${Icons.trash}
                                                    </button>
                                                </div>
                                                </div>
                                            </div>

                                            <div class="obj-dropzone flex-grow-1" data-dropzone="${obj.id}">
                                                ${productsHtml}
                                            </div>
                                            </div>
                                        </div>
                                        `;
                                            }
                                        };

                                        // ============================================================
                                        // 5) DRAWER
                                        // ============================================================
                                        const Drawer = {
                                            open: async (customerId) => {
                                                STATE.customerId = customerId;
                                                DOM.root.classList.add('is-visible');
                                                await DataManager.loadTree(customerId);
                                            },
                                            close: () => {
                                                DOM.root.classList.remove('is-visible');
                                                Drawer.toggleCreatePanel(false);
                                                DOM.createMsg.textContent = '';
                                            },
                                            toggleCreatePanel: (show = null) => {
                                                const isHidden = DOM.createPanel.classList.contains('drawer-hidden');
                                                const shouldShow = show !== null ? show : isHidden;

                                                if (shouldShow) {
                                                    DOM.createPanel.classList.remove('drawer-hidden');
                                                    if (!DOM.inputs.date.value) DOM.inputs.date.value = new Date().toISOString().split('T')[0];
                                                    MapController.init();
                                                } else {
                                                    DOM.createPanel.classList.add('drawer-hidden');
                                                    DOM.createMsg.textContent = '';
                                                }
                                            }
                                        };

                                        // ============================================================
                                        // 6) DATA MANAGER (SweetAlert2 delete flows)
                                        // ============================================================
                                        const DataManager = {
                                            loadTree: async (customerId) => {
                                                DOM.loading.classList.remove('drawer-hidden');
                                                DOM.grid.classList.add('drawer-hidden');
                                                DOM.cols.innerHTML = '';
                                                DragDrop.destroy();

                                                try {
                                                    const result = await Utils.http(Utils.url(CONFIG.endpoints.tree, customerId));
                                                    const data = result.data;

                                                    STATE.objectsData = data.objects || [];

                                                    const c = data.customer;
                                                    DOM.customerLine.textContent = [c.customer_no, c.firma, c.name].filter(Boolean).join(' · ');

                                                    DOM.cols.innerHTML = (data.objects || []).map(Renderer.objectCard).join('');

                                                    DOM.loading.classList.add('drawer-hidden');
                                                    DOM.grid.classList.remove('drawer-hidden');

                                                    DragDrop.init();
                                                } catch (error) {
                                                    DOM.cols.innerHTML = `<div class="alert alert-danger m-3">Fehler beim Laden: ${Utils.esc(error.message)}</div>`;
                                                    DOM.loading.classList.add('drawer-hidden');
                                                    DOM.grid.classList.remove('drawer-hidden');
                                                }
                                            },

                                            createObject: async () => {
                                                if (!STATE.customerId) return;

                                                DOM.createMsg.textContent = 'Speichern...';
                                                DOM.createMsg.className = 'ml-2 small text-muted';

                                                try {
                                                    const payload = {
                                                        object_name: DOM.inputs.name.value,
                                                        request_date: DOM.inputs.date.value || null,
                                                        full_address: DOM.inputs.fullAddress.value || null,
                                                        street: DOM.inputs.street.value || null,
                                                        postcode: DOM.inputs.postcode.value || null,
                                                        city: DOM.inputs.city.value || null,
                                                        lat: DOM.inputs.lat.value || null,
                                                        lon: DOM.inputs.lon.value || null,
                                                        objective: DOM.inputs.objective.value || null,
                                                        note: DOM.inputs.note.value || null,
                                                    };

                                                    const result = await Utils.http(Utils.url(CONFIG.endpoints.createObject, STATE.customerId), 'POST', payload);

                                                    DOM.cols.insertAdjacentHTML('beforeend', Renderer.objectCard(result.object));
                                                    DragDrop.init();

                                                    DOM.createMsg.textContent = 'Gespeichert ✅';
                                                    DOM.createMsg.className = 'ml-2 small text-success';
                                                    setTimeout(() => Drawer.toggleCreatePanel(false), 800);

                                                } catch (error) {
                                                    DOM.createMsg.textContent = error.message || 'Fehler.';
                                                    DOM.createMsg.className = 'ml-2 small text-danger';
                                                }
                                            },

                                            moveProduct: async (leadProductId, toObjectId, itemElement, senderList, oldIndex) => {
                                                try {
                                                    await Utils.http(Utils.url(CONFIG.endpoints.moveProduct, leadProductId), 'POST', { to_alternative_id: toObjectId });
                                                } catch (error) {
                                                    if (window.Swal) {
                                                        Swal.fire({ icon: 'error', title: 'Fehler', text: error.message || 'Fehler beim Verschieben.' });
                                                    } else {
                                                        alert(error.message || 'Fehler beim Verschieben.');
                                                    }
                                                    senderList.insertBefore(itemElement, senderList.children[oldIndex]);
                                                }
                                            },

                                            deleteProduct: async (leadProductId) => {
                                                if (!leadProductId) return;
                                                Utils.ensureSwal();

                                                const r = await Swal.fire({
                                                    icon: 'warning',
                                                    title: 'Produkt löschen?',
                                                    html: `<div class="text-left">Dieses Produkt wird entfernt.</div>`,
                                                    showCancelButton: true,
                                                    confirmButtonText: 'Löschen',
                                                    cancelButtonText: 'Abbrechen',
                                                    reverseButtons: true,
                                                });

                                                if (!r.isConfirmed) return;

                                                try {
                                                    Swal.fire({ title: 'Lösche…', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
                                                    await Utils.http(Utils.url(CONFIG.endpoints.deleteProduct, leadProductId), 'POST');
                                                    await DataManager.loadTree(STATE.customerId);
                                                    Swal.fire({ icon: 'success', title: 'Gelöscht', timer: 900, showConfirmButton: false });
                                                } catch (e) {
                                                    Swal.fire({ icon: 'error', title: 'Fehler', text: e.message || 'Fehler beim Löschen.' });
                                                }
                                            },

                                            deleteObject: async (objectId) => {
                                                if (!objectId) return;
                                                Utils.ensureSwal();

                                                const objects = STATE.objectsData || [];
                                                const obj = objects.find(o => Number(o.id) === Number(objectId));
                                                const prodCount = obj?.products?.length || 0;

                                                // Prevent removing last object when user wants move (we handle it)
                                                const otherObjects = objects.filter(o => Number(o.id) !== Number(objectId));
                                                const optionsHtml = otherObjects.map(o => {
                                                    const label = Utils.esc(o.object_name || `Objekt #${o.id}`);
                                                    return `<option value="${o.id}">${label}</option>`;
                                                }).join('');

                                                // Build dynamic dialog
                                                const hasOthers = otherObjects.length > 0;

                                                const html = prodCount > 0
                                                    ? `
                                            <div class="text-left">
                                            <div class="d-flex align-items-center mb-2" style="gap:8px;">
                                                <span style="color:#d9534f">${Icons.warning}</span>
                                                <div><b>${prodCount}</b> Produkte sind in diesem Objekt.</div>
                                            </div>

                                            <div class="mt-3">
                                                <div class="custom-control custom-radio">
                                                <input type="radio" id="delModeMove" name="delMode" class="custom-control-input" ${hasOthers ? 'checked' : ''} ${hasOthers ? '' : 'disabled'}>
                                                <label class="custom-control-label" for="delModeMove">
                                                    Produkte verschieben ${hasOthers ? '' : '(kein anderes Objekt vorhanden)'}
                                                </label>
                                                </div>

                                                <div class="mt-2 ml-4">
                                                <select id="moveTarget" class="form-control form-control-sm" ${hasOthers ? '' : 'disabled'}>
                                                    ${optionsHtml}
                                                </select>
                                                </div>

                                                <div class="custom-control custom-radio mt-3">
                                                <input type="radio" id="delModeDelete" name="delMode" class="custom-control-input" ${hasOthers ? '' : 'checked'}>
                                                <label class="custom-control-label" for="delModeDelete">
                                                    Produkte löschen (mit Objekt)
                                                </label>
                                                </div>
                                            </div>
                                            </div>
                                        `
                                                    : `
                                            <div class="text-left">Objekt wirklich löschen?</div>
                                        `;

                                                const r = await Swal.fire({
                                                    icon: 'warning',
                                                    title: 'Objekt löschen?',
                                                    html,
                                                    showCancelButton: true,
                                                    confirmButtonText: `Löschen`,
                                                    cancelButtonText: 'Abbrechen',
                                                    reverseButtons: true,
                                                    preConfirm: () => {
                                                        if (prodCount > 0) {
                                                            const modeMove = document.getElementById('delModeMove');
                                                            const modeDelete = document.getElementById('delModeDelete');
                                                            const moveTarget = document.getElementById('moveTarget');

                                                            const wantsMove = modeMove?.checked && !modeMove?.disabled;
                                                            const wantsDelete = modeDelete?.checked;

                                                            if (wantsMove) {
                                                                const toId = moveTarget?.value;
                                                                if (!toId) {
                                                                    Swal.showValidationMessage('Bitte Ziel-Objekt auswählen.');
                                                                    return false;
                                                                }
                                                                return { delete_products: false, move_to_alternative_id: Number(toId) };
                                                            }

                                                            if (wantsDelete) {
                                                                return { delete_products: true, move_to_alternative_id: null };
                                                            }

                                                            Swal.showValidationMessage('Bitte eine Option wählen.');
                                                            return false;
                                                        }

                                                        return { delete_products: true, move_to_alternative_id: null };
                                                    }
                                                });

                                                if (!r.isConfirmed) return;

                                                try {
                                                    Swal.fire({ title: 'Lösche…', allowOutsideClick: false, didOpen: () => Swal.showLoading() });
                                                    await Utils.http(Utils.url(CONFIG.endpoints.deleteObject, objectId), 'POST', r.value);
                                                    await DataManager.loadTree(STATE.customerId);
                                                    Swal.fire({ icon: 'success', title: 'Objekt gelöscht', timer: 900, showConfirmButton: false });
                                                } catch (e) {
                                                    Swal.fire({ icon: 'error', title: 'Fehler', text: e.message || 'Fehler beim Löschen.' });
                                                }
                                            }
                                        };

                                        // ============================================================
                                        // 7) DRAG & DROP
                                        // ============================================================
                                        const DragDrop = {
                                            init: () => {
                                                const zones = DOM.root.querySelectorAll('[data-dropzone]');
                                                zones.forEach(zone => {
                                                    const sortable = new Sortable(zone, {
                                                        group: 'productsMove',
                                                        animation: 150,
                                                        draggable: '[data-product-item]',
                                                        ghostClass: 'bg-light',
                                                        onEnd: (evt) => {
                                                            const item = evt.item;
                                                            const leadProductId = parseInt(item.getAttribute('data-lead-product-id'), 10);
                                                            const toObjectId = parseInt(evt.to.getAttribute('data-dropzone'), 10);
                                                            const fromObjectId = parseInt(evt.from.getAttribute('data-dropzone'), 10);
                                                            if (leadProductId && toObjectId && fromObjectId !== toObjectId) {
                                                                DataManager.moveProduct(leadProductId, toObjectId, item, evt.from, evt.oldIndex);
                                                            }
                                                        }
                                                    });
                                                    STATE.sortableInstances.push(sortable);
                                                });
                                            },
                                            destroy: () => {
                                                STATE.sortableInstances.forEach(s => { try { s.destroy(); } catch (e) { } });
                                                STATE.sortableInstances = [];
                                            }
                                        };

                                        // ============================================================
                                        // 8) MAP CONTROLLER
                                        // ============================================================
                                        const MapController = {
                                            init: () => {
                                                if (STATE.map || !window.google?.maps) return;

                                                STATE.geocoder = new google.maps.Geocoder();
                                                const defaultLoc = { lat: 50.1109, lng: 8.6821 };

                                                STATE.map = new google.maps.Map(DOM.inputs.map, {
                                                    center: defaultLoc, zoom: 12, streetViewControl: false, mapTypeControl: false
                                                });

                                                STATE.marker = new google.maps.Marker({ map: STATE.map, position: defaultLoc, draggable: true });
                                                STATE.map.addListener('click', (e) => MapController.handleLocationUpdate(e.latLng));
                                                STATE.marker.addListener('dragend', (e) => MapController.handleLocationUpdate(e.latLng));
                                                MapController.initAutocomplete();
                                            },

                                            initAutocomplete: () => {
                                                STATE.autocomplete = new google.maps.places.Autocomplete(DOM.inputs.address, {
                                                    fields: ['formatted_address', 'geometry', 'address_components']
                                                });

                                                STATE.autocomplete.addListener('place_changed', () => {
                                                    const place = STATE.autocomplete.getPlace();
                                                    if (!place.geometry) return;

                                                    STATE.map.setCenter(place.geometry.location);
                                                    STATE.map.setZoom(15);
                                                    STATE.marker.setPosition(place.geometry.location);

                                                    MapController.handleLocationUpdate(place.geometry.location, false);
                                                    DOM.inputs.fullAddress.value = place.formatted_address || '';
                                                    MapController.fillAddressComponents(place.address_components || []);
                                                });
                                            },

                                            handleLocationUpdate: (latLng, doReverse = true) => {
                                                DOM.inputs.lat.value = String(latLng.lat());
                                                DOM.inputs.lon.value = String(latLng.lng());
                                                STATE.marker.setPosition(latLng);
                                                if (doReverse) MapController.reverseGeocode(latLng);
                                            },

                                            reverseGeocode: (latLng) => {
                                                if (!STATE.geocoder) return;
                                                STATE.geocoder.geocode({ location: latLng }, (res, status) => {
                                                    if (status === 'OK' && res[0]) {
                                                        DOM.inputs.fullAddress.value = res[0].formatted_address;
                                                        MapController.fillAddressComponents(res[0].address_components || []);
                                                    }
                                                });
                                            },

                                            fillAddressComponents: (components) => {
                                                const get = (t) => components.find(c => c.types?.includes(t))?.long_name || '';
                                                DOM.inputs.street.value = [get('route'), get('street_number')].filter(Boolean).join(' ');
                                                DOM.inputs.postcode.value = get('postal_code');
                                                DOM.inputs.city.value = get('locality') || get('postal_town');
                                            }
                                        };

                                        // ============================================================
                                        // 9) EVENTS
                                        // ============================================================
                                        document.getElementById('btnDrawerClose')?.addEventListener('click', Drawer.close);
                                        DOM.backdrop?.addEventListener('click', Drawer.close);
                                        document.getElementById('btnDrawerOpenCreate')?.addEventListener('click', () => Drawer.toggleCreatePanel());
                                        document.getElementById('btnCreateObjectCancel')?.addEventListener('click', () => Drawer.toggleCreatePanel(false));
                                        document.getElementById('btnCreateObjectSave')?.addEventListener('click', DataManager.createObject);

                                        // Open drawer
                                        document.addEventListener('click', (e) => {
                                            const btn = e.target.closest('.openObjectProductDrawer');
                                            if (!btn) return;
                                            e.preventDefault();
                                            const id = parseInt(btn.getAttribute('data-id') || '0', 10);
                                            if (id) Drawer.open(id);
                                        });

                                        // Delete actions (delegated) — inside IIFE so DataManager is in scope ✅
                                        document.addEventListener('click', (e) => {
                                            const delObj = e.target.closest('[data-action="delete-object"]');
                                            if (delObj) {
                                                e.preventDefault();
                                                const objectId = parseInt(delObj.getAttribute('data-object-id') || '0', 10);
                                                if (objectId) DataManager.deleteObject(objectId);
                                                return;
                                            }

                                            const delProd = e.target.closest('[data-action="delete-product"]');
                                            if (delProd) {
                                                e.preventDefault();
                                                const pid = parseInt(delProd.getAttribute('data-product-id') || '0', 10);
                                                if (pid) DataManager.deleteProduct(pid);
                                                return;
                                            }
                                        });

                                    })();
                                </script>


                                <script>
                                    /**
                                    * Loads the Angebote Blade partial via AJAX and injects it into #mainContent
                                    */
                                    function loadAngebotPartial(customer_id, alternative_id, product_id) {
                                        const mainContent = document.getElementById('mainContent');

                                        // 1. Show a loading spinner
                                        mainContent.innerHTML = `
                                        <div class="d-flex justify-content-center align-items-center" style="height: 300px;">
                                            <div class="text-center">
                                                <div class="spinner-border text-primary" role="status"></div>
                                                <div class="mt-2 text-muted" style="font-weight: 500;">Lade Angebote...</div>
                                            </div>
                                        </div>`;

                                        // 2. Build the URL (Hardcoding 'angebote' as the section parameter for the route)
                                        const url = `/customer/partial/${customer_id}/${alternative_id}/${product_id}/angebote`;

                                        // 3. Fetch the HTML
                                        fetch(url, {
                                            headers: {
                                                'X-Requested-With': 'XMLHttpRequest'
                                            }
                                        })
                                            .then(response => {
                                                if (!response.ok) throw new Error('Netzwerkfehler beim Laden der Angebote');
                                                return response.text();
                                            })
                                            .then(html => {
                                                // 4. Inject the returned HTML
                                                mainContent.innerHTML = html;

                                                // 5. Re-initialize UI components
                                                if (typeof feather !== 'undefined') {
                                                    feather.replace();
                                                }
                                                if (window.jQuery && $.fn.tooltip) {
                                                    $('[data-toggle="tooltip"]').tooltip();
                                                }
                                            })
                                            .catch(error => {
                                                console.error(error);
                                                mainContent.innerHTML = `
                                            <div class="alert alert-danger m-3 d-flex align-items-center">
                                                <i class="feather icon-alert-circle mr-2" style="font-size: 20px;"></i>
                                                Fehler: ${error.message}
                                            </div>`;
                                            });
                                    }
                                </script>

                                <script>
                                    // 1. Pass the Data Map from Laravel to JavaScript (Ensure this exists in your Blade)
                                    window.kpiDetailsMap = @json($kpiDetailsMap ?? []);

                                    // --- Switch between Analytics & Feed Tabs ---
                                    function switchFkTab(event, tabName) {
                                        const tabs = event.target.closest('.fk-tabs').querySelectorAll('.fk-tab');
                                        tabs.forEach(btn => btn.classList.remove('active'));
                                        event.target.classList.add('active');

                                        const wrapper = event.target.closest('.fk-switcher-wrapper');
                                        wrapper.querySelectorAll('.fk-pane').forEach(pane => pane.classList.remove('active'));
                                        wrapper.querySelector('#fk-pane-' + tabName).classList.add('active');
                                    }

                                    // --- Open the Modal and list specific Objects/Products ---
                                    function openKpiModal(sidebarTargetText, kpiName, kpiKey) {
                                        const modal = $('#kpiDetailsModal');
                                        const title = document.getElementById('kpiModalTitle');
                                        const body = document.getElementById('kpiModalBody');

                                        title.innerText = `Übersicht: ${kpiName}`;
                                        body.innerHTML = '';

                                        // Auto-detect the KPI Key if you forgot to pass it in the HTML onclick
                                        if (!kpiKey) {
                                            const nameLower = kpiName.toLowerCase();
                                            if (nameLower.includes('foto')) kpiKey = 'photos';
                                            else if (nameLower.includes('dokument')) kpiKey = 'documents';
                                            else if (nameLower.includes('rechnung')) kpiKey = 'rechnung';
                                            else if (nameLower.includes('angebot')) kpiKey = 'angebot';
                                            else if (nameLower.includes('ticket')) kpiKey = 'ticket';
                                        }

                                        let html = '<div class="d-flex flex-column gap-2">';
                                        let itemsFound = 0;

                                        // 🔴 FIX: Target the actual sidebar product links where the data-attributes live!
                                        const products = document.querySelectorAll('.project-link[data-product-key]');

                                        products.forEach(prod => {
                                            // 1. Get the Product Name (Usually the inner text of the link)
                                            let productName = 'Produkt';
                                            const nameEl = prod.querySelector('.text-truncate') || prod.querySelector('span:not(.badge)');
                                            if (nameEl) {
                                                productName = nameEl.innerText.trim();
                                            } else {
                                                productName = prod.innerText.trim() || 'Produkt';
                                            }

                                            // 2. Get the Object Name and Object ID
                                            const objList = prod.closest('.product-list');
                                            const objId = objList ? objList.id : ''; // e.g., 'object0'

                                            // The object header is the element right before the .product-list
                                            const objHeader = objList ? objList.previousElementSibling : null;
                                            let objectName = 'Objekt';
                                            if (objHeader) {
                                                const headerTextEl = objHeader.querySelector('.font-weight-bold');
                                                objectName = headerTextEl ? headerTextEl.innerText.trim() : objHeader.innerText.trim();
                                            }

                                            // 3. Extract the IDs directly from the .project-link
                                            const prodKey = prod.getAttribute('data-product-key');
                                            const aid = prod.getAttribute('data-object-alternative-id') || prod.getAttribute('data-alternative-id');
                                            const pid = prod.getAttribute('data-object-product') || prod.getAttribute('data-product-id');

                                            if (!aid || !pid) return; // Skip if no IDs

                                            // 4. Lookup the exact count in the map generated by the Controller
                                            const mapKey = aid + '_' + pid;
                                            const kpiData = window.kpiDetailsMap ? window.kpiDetailsMap[mapKey] : null;
                                            const count = kpiData ? (kpiData[kpiKey] || 0) : 0;

                                            // 5. ONLY display this item if it has actual data!
                                            if (count > 0) {
                                                html += `
                                                <div class="kpi-modal-item bg-white p-3 d-flex justify-content-between align-items-center rounded border shadow-sm">
                                                    <div>
                                                        <div class="d-flex align-items-center gap-2 mb-1">
                                                            <h6 class="mb-0" style="font-weight: 800; color: #2d3e4f;">${productName}</h6>
                                                            <span style="background: #e2e8f0; color: #1e293b; font-size: 11px; font-weight: 700; padding: 2px 8px; border-radius: 999px;">${count} Einträge</span>
                                                        </div>
                                                        <small style="color: #64748b; font-weight: 600;">
                                                            <i class="feather icon-home"></i> ${objectName}
                                                        </small>
                                                    </div>
                                                    <button class="btn btn-sm" style="background: #74b2d4; color: #fff; font-weight: bold; border-radius: 8px;" 
                                                            onclick="jumpToProductSection('${prodKey}', '${sidebarTargetText}', '${objId}')">
                                                        Öffnen <i class="feather icon-arrow-right ml-1"></i>
                                                    </button>
                                                </div>
                                            `;
                                                itemsFound++;
                                            }
                                        });

                                        // Fallback if no entries are found across all products
                                        if (itemsFound === 0) {
                                            html += `<div class="p-4 text-center text-muted" style="font-weight: 600;">Keine Einträge für diese Kategorie gefunden.</div>`;
                                        }

                                        html += '</div>';
                                        body.innerHTML = html;

                                        // Open Modal
                                        modal.addClass('is-open').attr('aria-hidden', 'false');
                                        document.body.classList.add('cmodal-open');
                                    }

                                    // --- Jump to the right Sidebar Location ---
                                    function jumpToProductSection(prodKey, targetText, objId) {
                                        // 1. Close Modal
                                        $('.cmodal').removeClass('is-open');
                                        document.body.classList.remove('cmodal-open');

                                        // 2. Open the Object Dropdown if closed
                                        const objectList = document.getElementById(objId);
                                        if (objectList && objectList.style.display === 'none') {
                                            if (typeof window.toggleObject === 'function') window.toggleObject(objId);
                                        }

                                        // 3. Open the Product SubNav if closed
                                        const subNav = document.getElementById(prodKey);
                                        if (subNav && subNav.style.display === 'none') {
                                            if (typeof window.toggleProduct === 'function') window.toggleProduct(prodKey);
                                        }

                                        // 4. Find the correct button inside the SubNav and click it
                                        setTimeout(() => {
                                            if (!subNav) return;
                                            const buttons = subNav.querySelectorAll('.nav-section-btn, button');
                                            for (let btn of buttons) {
                                                if (btn.innerText.toLowerCase().includes(targetText.toLowerCase())) {
                                                    btn.click();
                                                    btn.scrollIntoView({ behavior: 'smooth', block: 'center' });
                                                    break;
                                                }
                                            }
                                        }, 350); // Delay allows dropdown animations to finish before clicking
                                    }
                                </script>
                                <script>
                                    function toggleCustomerNav() {
                                        const wrapper = document.getElementById('customerNavWrapper');
                                        const icon = document.getElementById('cnToggleIcon');

                                        // Toggle the collapsed class
                                        wrapper.classList.toggle('is-collapsed');

                                        // Switch the icon up/down
                                        if (wrapper.classList.contains('is-collapsed')) {
                                            icon.classList.remove('icon-chevron-up');
                                            icon.classList.add('icon-chevron-down');
                                        } else {
                                            icon.classList.remove('icon-chevron-down');
                                            icon.classList.add('icon-chevron-up');
                                        }
                                    }
                                </script>
                                    <script>
                                        window.refreshProfileIcons = function () {
                                            if (window.feather && typeof window.feather.replace === 'function') {
                                                window.feather.replace();
                                            }
                                        };

                                        window.isMobileProfile = function () {
                                            return window.matchMedia('(max-width: 991.98px)').matches;
                                        };

                                        window.openMobileSidebar = function () {
                                            document.body.classList.add('mobile-sidebar-open');
                                            refreshProfileIcons();
                                        };

                                        window.closeMobileSidebar = function () {
                                            document.body.classList.remove('mobile-sidebar-open');
                                            refreshProfileIcons();
                                        };

                                    window.togglecustomerSidebar = function () {
                                            const sidebar = document.getElementById('customerSidebar');
                                            const layout = document.querySelector('.layout');

                                            if (!sidebar) return;

                                            /*
                                            * Mobile:
                                            * The sidebar works as drawer.
                                            */
                                            if (typeof isMobileProfile === 'function' && isMobileProfile()) {
                                                if (document.body.classList.contains('mobile-sidebar-open')) {
                                                    if (typeof closeMobileSidebar === 'function') {
                                                        closeMobileSidebar();
                                                    } else {
                                                        document.body.classList.remove('mobile-sidebar-open');
                                                    }
                                                } else {
                                                    if (typeof openMobileSidebar === 'function') {
                                                        openMobileSidebar();
                                                    } else {
                                                        document.body.classList.add('mobile-sidebar-open');
                                                        sidebar.classList.remove('minimized');
                                                    }
                                                }

                                                if (typeof refreshProfileIcons === 'function') {
                                                    refreshProfileIcons();
                                                } else if (window.feather) {
                                                    window.feather.replace();
                                                }

                                                return;
                                            }

                                            /*
                                            * Desktop:
                                            * The sidebar becomes icon-only and the layout column shrinks.
                                            */
                                            const isNowMinimized = !sidebar.classList.contains('minimized');

                                            sidebar.classList.toggle('minimized', isNowMinimized);

                                            if (layout) {
                                                layout.classList.toggle('sidebar-minimized', isNowMinimized);
                                            }

                                            if (isNowMinimized) {
                                                document.querySelectorAll('.product-list.show, .sub-nav.show').forEach(function (el) {
                                                    el.classList.remove('show');
                                                    el.style.display = 'none';
                                                });
                                            }

                                            const icon = sidebar.querySelector('.minimize-btn i, .minimize-btn svg');

                                            if (icon) {
                                                icon.setAttribute('data-feather', isNowMinimized ? 'chevrons-right' : 'chevrons-left');
                                            }

                                            if (typeof refreshProfileIcons === 'function') {
                                                refreshProfileIcons();
                                            } else if (window.feather) {
                                                window.feather.replace();
                                            }
                                        };
                                        document.addEventListener('DOMContentLoaded', function () {
                                            const openBtn = document.getElementById('mobileSidebarOpenBtn');
                                            const backdrop = document.getElementById('mobileSidebarBackdrop');

                                            if (openBtn) {
                                                openBtn.addEventListener('click', openMobileSidebar);
                                            }

                                            if (backdrop) {
                                                backdrop.addEventListener('click', closeMobileSidebar);
                                            }

                                            document.addEventListener('keydown', function (event) {
                                                if (event.key === 'Escape') {
                                                    closeMobileSidebar();
                                                }
                                            });

                                            document.querySelectorAll('.customerSidebar .nav-section-btn').forEach(function (btn) {
                                                btn.addEventListener('click', function () {
                                                    if (isMobileProfile()) {
                                                        closeMobileSidebar();
                                                    }
                                                });
                                            });

                                            window.addEventListener('resize', function () {
                                                if (!isMobileProfile()) {
                                                    closeMobileSidebar();
                                                }
                                            });

                                            refreshProfileIcons();
                                        });
                                    </script>
                        <!-- sidebar Coutners  -->
                                    <script>
                                        (function () {
                                            "use strict";

                                            let sidebarCountController = null;
                                            let sidebarCountTimer = null;

                                            document.addEventListener('DOMContentLoaded', function () {
                                                refreshCustomerSidebarCounts();

                                                document.addEventListener('click', function (event) {
                                                    const objectHeader = event.target.closest('.object-header');

                                                    if (objectHeader) {
                                                        scheduleSidebarCountRefresh(250);
                                                    }
                                                });
                                            });

                                            window.refreshCustomerSidebarCounts = function () {
                                                loadCustomerSidebarCounts();
                                            };

                                            window.scheduleSidebarCountRefresh = function (delay = 250) {
                                                clearTimeout(sidebarCountTimer);

                                                sidebarCountTimer = setTimeout(function () {
                                                    loadCustomerSidebarCounts();
                                                }, delay);
                                            };

                                            window.formatEuroSidebarAmount = function (value) {
                                                const number = Number(value || 0);

                                                return number.toLocaleString('de-DE', {
                                                    minimumFractionDigits: 2,
                                                    maximumFractionDigits: 2
                                                }) + ' €';
                                            };

                                            function getContextFromElement(el) {
                                                const customerId = el.dataset.customerId;
                                                const alternativeId = el.dataset.alternativeId;
                                                const productId = el.dataset.productId;

                                                if (!customerId || !alternativeId || !productId) {
                                                    return null;
                                                }

                                                return {
                                                    customer_id: customerId,
                                                    alternative_id: alternativeId,
                                                    product_id: productId,
                                                    key: customerId + '_' + alternativeId + '_' + productId
                                                };
                                            }

                                            function setBadgeLoading(badge) {
                                                badge.textContent = '…';
                                                badge.classList.remove('is-zero', 'is-error');
                                                badge.classList.add('is-loading');
                                            }

                                            function setBadgeValue(badge, value) {
                                                const number = Number(value || 0);

                                                badge.textContent = number;
                                                badge.classList.remove('is-loading', 'is-error');
                                                badge.classList.toggle('is-zero', number === 0);

                                                const parentButton = badge.closest('[data-sidebar-item], .sub-nav-btn, .nav-section-btn, button, a');

                                                if (parentButton) {
                                                    parentButton.classList.toggle('has-count', number > 0);
                                                    parentButton.classList.toggle('has-zero-count', number === 0);
                                                }
                                            }

                                            function setBadgeError(badge) {
                                                badge.textContent = '!';
                                                badge.classList.remove('is-loading', 'is-zero');
                                                badge.classList.add('is-error');
                                            }

                                            function setAmountLoading(amountLine) {
                                                const label = amountLine.dataset.sidebarAmountLabel || 'Gesamt';

                                                amountLine.textContent = label + ': …';
                                                amountLine.classList.remove('is-zero', 'is-error');
                                                amountLine.classList.add('is-loading');
                                            }

                                            function setAmountValue(amountLine, value) {
                                                const label = amountLine.dataset.sidebarAmountLabel || 'Gesamt';
                                                const number = Number(value || 0);

                                                amountLine.textContent = label + ': ' + window.formatEuroSidebarAmount(number);
                                                amountLine.classList.remove('is-loading', 'is-error');
                                                amountLine.classList.toggle('is-zero', number === 0);
                                            }

                                            function setAmountError(amountLine) {
                                                const label = amountLine.dataset.sidebarAmountLabel || 'Gesamt';

                                                amountLine.textContent = label + ': !';
                                                amountLine.classList.remove('is-loading', 'is-zero');
                                                amountLine.classList.add('is-error');
                                            }

                                            function buildGroups() {
                                                const badges = Array.from(document.querySelectorAll('.sidebar-count-badge[data-sidebar-count]'));
                                                const amountLines = Array.from(document.querySelectorAll('[data-sidebar-amount]'));

                                                const groups = {};

                                                badges.forEach(function (badge) {
                                                    const context = getContextFromElement(badge);
                                                    if (!context) return;

                                                    if (!groups[context.key]) {
                                                        groups[context.key] = {
                                                            customer_id: context.customer_id,
                                                            alternative_id: context.alternative_id,
                                                            product_id: context.product_id,
                                                            badges: [],
                                                            amounts: []
                                                        };
                                                    }

                                                    groups[context.key].badges.push(badge);
                                                    setBadgeLoading(badge);
                                                });

                                                amountLines.forEach(function (amountLine) {
                                                    const context = getContextFromElement(amountLine);
                                                    if (!context) return;

                                                    if (!groups[context.key]) {
                                                        groups[context.key] = {
                                                            customer_id: context.customer_id,
                                                            alternative_id: context.alternative_id,
                                                            product_id: context.product_id,
                                                            badges: [],
                                                            amounts: []
                                                        };
                                                    }

                                                    groups[context.key].amounts.push(amountLine);
                                                    setAmountLoading(amountLine);
                                                });

                                                return groups;
                                            }

                                            async function fetchSidebarCounts(group) {
                                                const url = new URL("{{ route('new-leads.sidebar-counts') }}", window.location.origin);

                                                url.searchParams.set('customer_id', group.customer_id);
                                                url.searchParams.set('alternative_id', group.alternative_id);
                                                url.searchParams.set('product_id', group.product_id);

                                                const response = await fetch(url.toString(), {
                                                    method: 'GET',
                                                    signal: sidebarCountController?.signal,
                                                    headers: {
                                                        'Accept': 'application/json',
                                                        'X-Requested-With': 'XMLHttpRequest'
                                                    }
                                                });

                                                if (!response.ok) {
                                                    throw new Error('Counts konnten nicht geladen werden.');
                                                }

                                                return response.json();
                                            }

                                            async function loadCustomerSidebarCounts() {
                                                const groups = buildGroups();

                                                if (!Object.keys(groups).length) {
                                                    return;
                                                }

                                                if (sidebarCountController) {
                                                    sidebarCountController.abort();
                                                }

                                                sidebarCountController = new AbortController();

                                                await Promise.allSettled(
                                                    Object.values(groups).map(async function (group) {
                                                        try {
                                                            const payload = await fetchSidebarCounts(group);
                                                            const counts = payload.counts || {};

                                                            group.badges.forEach(function (badge) {
                                                                const key = badge.dataset.sidebarCount;
                                                                setBadgeValue(badge, counts[key]);
                                                            });

                                                            group.amounts.forEach(function (amountLine) {
                                                                const key = amountLine.dataset.sidebarAmount;
                                                                setAmountValue(amountLine, counts[key]);
                                                            });
                                                        } catch (error) {
                                                            if (error.name === 'AbortError') {
                                                                return;
                                                            }

                                                            group.badges.forEach(setBadgeError);
                                                            group.amounts.forEach(setAmountError);
                                                        }
                                                    })
                                                );
                                            }
                                        })();
                                    </script>

                    <!-- Object Map and screenshot  -->
                     <script>
                        window.MayarObjectMaps = window.MayarObjectMaps || {
                            previews: {},
                            sidebars: {},
                            geocoder: null,
                        };

                        function maHasGoogleMaps() {
                            return typeof window.google !== 'undefined'
                                && typeof window.google.maps !== 'undefined';
                        }

                        function maGetLatLngFromElement(el) {
                            const lat = parseFloat(el?.dataset?.lat || '');
                            const lng = parseFloat(el?.dataset?.lng || '');

                            if (Number.isFinite(lat) && Number.isFinite(lng)) {
                                return { lat, lng };
                            }

                            return null;
                        }

                        function maGeocodeAddress(address) {
                            return new Promise((resolve, reject) => {
                                if (!maHasGoogleMaps()) {
                                    reject(new Error('Google Maps ist nicht geladen.'));
                                    return;
                                }

                                if (!address) {
                                    reject(new Error('Adresse fehlt.'));
                                    return;
                                }

                                window.MayarObjectMaps.geocoder = window.MayarObjectMaps.geocoder || new google.maps.Geocoder();

                                window.MayarObjectMaps.geocoder.geocode({ address }, (results, status) => {
                                    if (status === 'OK' && results && results[0]) {
                                        const loc = results[0].geometry.location;

                                        resolve({
                                            lat: loc.lat(),
                                            lng: loc.lng(),
                                        });

                                        return;
                                    }

                                    reject(new Error('Adresse konnte nicht gefunden werden.'));
                                });
                            });
                        }

                        async function maResolveMapCenter(el) {
                            const directLatLng = maGetLatLngFromElement(el);

                            if (directLatLng) {
                                return directLatLng;
                            }

                            return await maGeocodeAddress(el?.dataset?.address || '');
                        }

                        async function initObjectMiniMap(el) {
                            if (!el || el.dataset.mapReady === '1') return;
                            if (!maHasGoogleMaps()) return;

                            try {
                                const center = await maResolveMapCenter(el);

                                el.innerHTML = '';
                                el.dataset.mapReady = '1';

                                const map = new google.maps.Map(el, {
                                    center,
                                    zoom: 20,
                                    mapTypeId: 'satellite',
                                    disableDefaultUI: true,
                                    gestureHandling: 'none',
                                    clickableIcons: false,
                                    tilt: 0,
                                    heading: 0,
                                });

                                new google.maps.Marker({
                                    position: center,
                                    map,
                                });

                                window.MayarObjectMaps.previews[el.dataset.alternativeId] = map;
                            } catch (error) {
                                console.warn(error);

                                el.innerHTML = `
                                    <div class="ma-object-map-loading">
                                        Karte nicht verfügbar
                                    </div>
                                `;
                            }
                        }

                        function initObjectMiniMaps() {
                            if (!maHasGoogleMaps()) return;

                            document.querySelectorAll('.ma-object-map-preview').forEach((el) => {
                                initObjectMiniMap(el);
                            });
                        }

                       async function initSidebarObjectMap(alternativeId, sourceEl = null) {
                            if (!maHasGoogleMaps()) return;

                            const mapEl = document.getElementById(`mapContainer${alternativeId}`);
                            if (!mapEl) return;

                            const source = sourceEl || mapEl;

                            try {
                                const center = await maResolveMapCenter(source);
                                mapEl.innerHTML = '';

                                const map = new google.maps.Map(mapEl, {
                                    center,
                                    zoom: 20,
                                    mapTypeId: 'satellite',
                                    disableDefaultUI: false,
                                    streetViewControl: true,
                                    mapTypeControl: true,
                                    fullscreenControl: true,
                                    gestureHandling: 'greedy',
                                    tilt: 0,
                                    heading: 0,
                                });

                                new google.maps.Marker({
                                    position: center,
                                    map,
                                });

                                // In beiden Namespaces speichern, um die Kompatibilität zu bewahren
                                window.MayarObjectMaps.sidebars[alternativeId] = map;
                                window.googleMapsInstances[alternativeId] = map;

                                // --- BUGFIX: Gestaffelter Resize & Recenter ---
                                // Fängt CSS-Animationen, Transitions und verzögertes Rendering perfekt ab
                                const fixMapResize = () => {
                                    if (mapEl.clientWidth > 0 && mapEl.clientHeight > 0) {
                                        google.maps.event.trigger(map, 'resize');
                                        map.setCenter(center);
                                    }
                                };

                                // Mehrere Checks während und direkt nach dem Ende der CSS-Transition
                                setTimeout(fixMapResize, 100);
                                setTimeout(fixMapResize, 350);
                                setTimeout(fixMapResize, 600);
                                setTimeout(fixMapResize, 1000);

                                // --- BUGFIX: Automatische Überwachung per ResizeObserver ---
                                // Passt die Karte sofort an, sobald der Container sichtbar wird oder sich ändert
                                if ('ResizeObserver' in window) {
                                    const ro = new ResizeObserver(() => {
                                        if (mapEl.clientWidth > 0) {
                                            google.maps.event.trigger(map, 'resize');
                                            map.setCenter(center);
                                        }
                                    });
                                    ro.observe(mapEl);
                                }

                                // Handle map type / screenshot switcher
                                const select = document.getElementById(`screenshotMode${alternativeId}`);
                                if (select) {
                                    select.value = 'satellite';
                                    select.onchange = () => {
                                        const type = select.value;
                                        if (type === 'streetview') {
                                            const panorama = map.getStreetView();
                                            panorama.setPosition(map.getCenter());
                                            panorama.setVisible(true);
                                        } else {
                                            map.getStreetView().setVisible(false);
                                            map.setMapTypeId(type);
                                        }
                                    };
                                }
                            } catch (error) {
                                console.warn("Map Init Error:", error);
                                mapEl.innerHTML = `
                                    <div class="ma-object-map-loading text-muted p-3 text-center small">
                                        Karte konnte nicht geladen werden.
                                    </div>
                                `;
                            }
                        }

                        function openObjectMapSidebar(el) {
                            if (!el) return;

                            const alternativeId = el.dataset.alternativeId;
                            const gallery = document.getElementById(`sidebarGallery${alternativeId}`);

                            if (!gallery) return;

                            if (typeof window.openSidebarGallery === 'function') {
                                window.openSidebarGallery(el);
                            } else {
                                gallery.classList.add('active');
                            }

                            const modeSelect = document.getElementById(`screenshotMode${alternativeId}`);

                            if (modeSelect) {
                                modeSelect.value = 'satellite';
                            }

                            initSidebarObjectMap(alternativeId, el);
                        }

                        function changeObjectSidebarMapMode(alternativeId, mode) {
                            const map = window.MayarObjectMaps.sidebars[alternativeId];

                            if (!map) return;

                            if (mode === 'streetview') {
                                const center = map.getCenter();

                                const panorama = map.getStreetView();

                                panorama.setPosition(center);
                                panorama.setPov({
                                    heading: 0,
                                    pitch: 0,
                                });

                                panorama.setVisible(true);
                                return;
                            }

                            map.getStreetView().setVisible(false);
                            map.setMapTypeId(mode || 'satellite');
                        }

                        document.addEventListener('DOMContentLoaded', () => {
                            let tries = 0;

                            const timer = setInterval(() => {
                                tries++;

                                if (maHasGoogleMaps()) {
                                    clearInterval(timer);
                                    initObjectMiniMaps();
                                }

                                if (tries > 40) {
                                    clearInterval(timer);
                                }
                            }, 250);
                        });

                        window.initObjectMiniMaps = initObjectMiniMaps;
                        window.openObjectMapSidebar = openObjectMapSidebar;
                        window.initSidebarObjectMap = initSidebarObjectMap;
                        window.changeObjectSidebarMapMode = changeObjectSidebarMapMode;
                    </script>

                   <script>
                        // 🔥 GLOBAL STORE FOR MAP INSTANCES
                        window.googleMapsInstances = {};
                        window.MayarObjectMaps = window.MayarObjectMaps || {
                            previews: {},
                            sidebars: {},
                            geocoder: null,
                        };

                        // ============================================================
                        // 1. CORE MAPS RESOLVERS & HELPERS
                        // ============================================================
                        function maHasGoogleMaps() {
                            return typeof window.google !== 'undefined' && typeof window.google.maps !== 'undefined';
                        }

                        function maGetLatLngFromElement(el) {
                            const lat = parseFloat(el?.dataset?.lat || '');
                            const lng = parseFloat(el?.dataset?.lng || '');
                            if (Number.isFinite(lat) && Number.isFinite(lng)) {
                                return { lat, lng };
                            }
                            return null;
                        }

                        function maGeocodeAddress(address) {
                            return new Promise((resolve, reject) => {
                                if (!maHasGoogleMaps()) {
                                    return reject(new Error('Google Maps ist nicht geladen.'));
                                }
                                if (!address) {
                                    return reject(new Error('Adresse fehlt.'));
                                }
                                window.MayarObjectMaps.geocoder = window.MayarObjectMaps.geocoder || new google.maps.Geocoder();
                                window.MayarObjectMaps.geocoder.geocode({ address }, (results, status) => {
                                    if (status === 'OK' && results && results[0]) {
                                        const loc = results[0].geometry.location;
                                        return resolve({ lat: loc.lat(), lng: loc.lng() });
                                    }
                                    reject(new Error('Adresse konnte nicht gefunden werden.'));
                                });
                            });
                        }

                        async function maResolveMapCenter(el) {
                            const directLatLng = maGetLatLngFromElement(el);
                            if (directLatLng) {
                                return directLatLng;
                            }
                            return await maGeocodeAddress(el?.dataset?.address || '');
                        }

                        // ============================================================
                        // 2. UNIFIED SIDEBAR MAP INITIALIZER (Fixes Rectangle/Zoom Bug)
                        // ============================================================
                        async function initSidebarObjectMap(alternativeId, sourceEl = null) {
                            if (!maHasGoogleMaps()) return;
                            const mapEl = document.getElementById(`mapContainer${alternativeId}`);
                            if (!mapEl) return;
                            const source = sourceEl || mapEl;

                            try {
                                const center = await maResolveMapCenter(source);
                                mapEl.innerHTML = '';

                                // Use zoom 19 for maximum stable satellite resolution across all regions
                                const map = new google.maps.Map(mapEl, {
                                    center,
                                    zoom: 19,
                                    mapTypeId: 'satellite',
                                    disableDefaultUI: false,
                                    streetViewControl: true,
                                    mapTypeControl: true,
                                    fullscreenControl: true,
                                    gestureHandling: 'greedy',
                                    tilt: 0,
                                    heading: 0,
                                });

                                new google.maps.Marker({
                                    position: center,
                                    map,
                                });

                                window.MayarObjectMaps.sidebars[alternativeId] = map;
                                window.googleMapsInstances[alternativeId] = map;

                                // --- BUGFIX: Staggered Resize & Recenter Loop ---
                                // Guarantees full rendering when containers transition from hidden to visible
                                const enforceFullRendering = () => {
                                    if (mapEl.clientWidth > 0 && mapEl.clientHeight > 0) {
                                        google.maps.event.trigger(map, 'resize');
                                        map.setCenter(center);
                                        map.setZoom(19);
                                    }
                                };

                                // Fire across the entire duration of any side-drawer CSS animation
                                setTimeout(enforceFullRendering, 50);
                                setTimeout(enforceFullRendering, 200);
                                setTimeout(enforceFullRendering, 400);
                                setTimeout(enforceFullRendering, 800);

                                // Native ResizeObserver fallback
                                if ('ResizeObserver' in window) {
                                    const ro = new ResizeObserver(() => {
                                        if (mapEl.clientWidth > 0) {
                                            google.maps.event.trigger(map, 'resize');
                                            map.setCenter(center);
                                        }
                                    });
                                    ro.observe(mapEl);
                                }

                                // Handle map type / screenshot switcher
                                const select = document.getElementById(`screenshotMode${alternativeId}`);
                                if (select) {
                                    select.value = 'satellite';
                                    select.onchange = () => {
                                        const type = select.value;
                                        if (type === 'streetview') {
                                            const panorama = map.getStreetView();
                                            panorama.setPosition(map.getCenter());
                                            panorama.setVisible(true);
                                        } else {
                                            map.getStreetView().setVisible(false);
                                            map.setMapTypeId(type);
                                        }
                                    };
                                }
                            } catch (error) {
                                console.warn("Map Init Error:", error);
                                mapEl.innerHTML = `<div class="ma-object-map-loading text-muted p-3 text-center small">Karte konnte nicht geladen werden.</div>`;
                            }
                        }

                        // ============================================================
                        // 3. MINI PREVIEW MAPS INITIALIZER (Fixes Profile Blank Bug)
                        // ============================================================
                        async function initObjectMiniMap(el) {
                            if (!el || el.dataset.mapReady === '1') return;
                            if (!maHasGoogleMaps()) return;
                            try {
                                const center = await maResolveMapCenter(el);
                                el.innerHTML = '';
                                el.dataset.mapReady = '1';

                                const map = new google.maps.Map(el, {
                                    center,
                                    zoom: 19, // Safe maximum satellite zoom
                                    mapTypeId: 'satellite',
                                    disableDefaultUI: true,
                                    gestureHandling: 'none',
                                    clickableIcons: false,
                                    tilt: 0,
                                    heading: 0,
                                });

                                new google.maps.Marker({
                                    position: center,
                                    map,
                                });

                                window.MayarObjectMaps.previews[el.dataset.alternativeId] = map;

                                // Force immediate resize trigger
                                setTimeout(() => {
                                    if (el.clientWidth > 0) {
                                        google.maps.event.trigger(map, 'resize');
                                        map.setCenter(center);
                                    }
                                }, 150);
                            } catch (error) {
                                console.warn(error);
                                el.innerHTML = `<div class="ma-object-map-loading text-muted p-2 text-center small">Karte nicht verfügbar</div>`;
                            }
                        }

                        function initObjectMiniMaps() {
                            if (!maHasGoogleMaps()) return;
                            document.querySelectorAll('.ma-object-map-preview:not([data-map-ready="1"])').forEach((el) => {
                                initObjectMiniMap(el);
                            });
                        }

                        function openObjectMapSidebar(el) {
                            if (!el) return;
                            const alternativeId = el.dataset.alternativeId;
                            const gallery = document.getElementById(`sidebarGallery${alternativeId}`);
                            if (!gallery) return;

                            if (typeof window.openSidebarGallery === 'function') {
                                window.openSidebarGallery(el);
                            } else {
                                gallery.classList.add('active');
                                initSidebarObjectMap(alternativeId, el);
                            }
                        }

                        function changeObjectSidebarMapMode(alternativeId, mode) {
                            const map = window.MayarObjectMaps.sidebars[alternativeId];
                            if (!map) return;
                            if (mode === 'streetview') {
                                const center = map.getCenter();
                                const panorama = map.getStreetView();
                                panorama.setPosition(center);
                                panorama.setPov({ heading: 0, pitch: 0 });
                                panorama.setVisible(true);
                                return;
                            }
                            map.getStreetView().setVisible(false);
                            map.setMapTypeId(mode || 'satellite');
                        }

                        // ============================================================
                        // 4. AUTOMATIC BOOT & DYNAMIC AJAX OBSERVER
                        // ============================================================
                        document.addEventListener('DOMContentLoaded', () => {
                            let tries = 0;
                            const timer = setInterval(() => {
                                tries++;
                                if (maHasGoogleMaps()) {
                                    clearInterval(timer);
                                    initObjectMiniMaps();
                                }
                                if (tries > 40) {
                                    clearInterval(timer);
                                }
                            }, 250);

                            // --- BUGFIX: Dynamic DOM Observer ---
                            // Automatically detects when new profile items or dashboard objects are loaded via AJAX
                            const observer = new MutationObserver((mutations) => {
                                let shouldInit = false;
                                mutations.forEach((mutation) => {
                                    if (mutation.addedNodes.length) {
                                        mutation.addedNodes.forEach((node) => {
                                            if (node.nodeType === 1 && (node.classList?.contains('ma-object-map-preview') || node.querySelector?.('.ma-object-map-preview'))) {
                                                shouldInit = true;
                                            }
                                        });
                                    }
                                });
                                if (shouldInit && maHasGoogleMaps()) {
                                    setTimeout(initObjectMiniMaps, 100);
                                }
                            });

                            const targetNode = document.getElementById('mainContent') || document.body;
                            if (targetNode) {
                                observer.observe(targetNode, { childList: true, subtree: true });
                            }
                        });

                        // Expose APIs globally
                        window.initObjectMiniMaps = initObjectMiniMaps;
                        window.openObjectMapSidebar = openObjectMapSidebar;
                        window.initSidebarObjectMap = initSidebarObjectMap;
                        window.changeObjectSidebarMapMode = changeObjectSidebarMapMode;
                        </script>


    <!-- Review Crude  -->

     <script>
        /**
         * ============================================================
         * CUSTOMER REVIEWS AJAX CRUD
         * Target: #mainContent
         * View: admin.new_leads.layouts.review
         *
         * Features:
         * - AJAX load into #mainContent
         * - create / update / delete
         * - toggle "Neue Bewertung" form
         * - inline edit
         * - search and filters
         * - custom toast
         * - SweetAlert2 delete confirmation
         * - star selector
         * ============================================================
         */

        window.CustomerReviewAjax = {
            routes: {
                index: "{{ route('customer-reviews.index') }}",
                store: "{{ route('customer-reviews.store') }}",
                base: "{{ url('/customer-reviews') }}",
            },

            current: {
                customerId: null,
                alternativeId: null,
                productId: null,
            },

            csrf() {
                return document.querySelector('meta[name="csrf-token"]')?.getAttribute('content') || '';
            },

            mainContent() {
                return document.getElementById('mainContent');
            },

            root() {
                return document.querySelector('[data-customer-review-root]');
            },

            normalizeId(value) {
                if (
                    value === undefined ||
                    value === null ||
                    value === '' ||
                    value === 'null' ||
                    value === 'undefined'
                ) {
                    return '';
                }

                return value;
            },

            refreshIcons() {
                if (window.feather) {
                    window.feather.replace();
                }

                if (window.lucide && window.lucide.createIcons) {
                    window.lucide.createIcons();
                }
            },

            loadingHtml() {
                return `
                    <div style="padding:24px;">
                        <div style="
                            display:flex;
                            align-items:center;
                            gap:12px;
                            color:#6b7280;
                            font-weight:800;
                        ">
                            <span style="
                                width:20px;
                                height:20px;
                                border:3px solid #e5e7eb;
                                border-top-color:#f8ac00;
                                border-radius:999px;
                                display:inline-block;
                                animation: crSpin .8s linear infinite;
                            "></span>
                            Bewertungen werden geladen...
                        </div>

                        <style>
                            @keyframes crSpin {
                                from { transform: rotate(0deg); }
                                to { transform: rotate(360deg); }
                            }
                        </style>
                    </div>
                `;
            },

            errorHtml(message) {
                return `
                    <div style="
                        margin:16px;
                        padding:18px;
                        border-radius:18px;
                        border:1px solid rgba(229,6,86,.25);
                        background:rgba(229,6,86,.08);
                        color:#e50656;
                        font-weight:900;
                    ">
                        ${this.escapeHtml(message || 'Bewertungen konnten nicht geladen werden.')}
                    </div>
                `;
            },

            escapeHtml(value) {
                return String(value ?? '')
                    .replaceAll('&', '&amp;')
                    .replaceAll('<', '&lt;')
                    .replaceAll('>', '&gt;')
                    .replaceAll('"', '&quot;')
                    .replaceAll("'", '&#039;');
            },

            parseError(error) {
                if (!error) {
                    return 'Ein Fehler ist aufgetreten.';
                }

                if (typeof error === 'string') {
                    return error;
                }

                if (error.message) {
                    return error.message;
                }

                if (error.errors) {
                    return Object.values(error.errors).flat().join(' ');
                }

                return 'Ein Fehler ist aufgetreten.';
            },

            async request(url, options = {}) {
                const headers = {
                    'X-CSRF-TOKEN': this.csrf(),
                    'X-Requested-With': 'XMLHttpRequest',
                    'Accept': options.accept || 'application/json',
                    ...(options.headers || {}),
                };

                const response = await fetch(url, {
                    ...options,
                    headers,
                });

                if (options.responseType === 'html') {
                    const html = await response.text();

                    if (!response.ok) {
                        throw new Error('Fehler beim Laden der Bewertungen.');
                    }

                    return html;
                }

                const data = await response.json().catch(() => ({}));

                if (!response.ok) {
                    throw data;
                }

                return data;
            },

            buildParams(customerId, alternativeId = null, productId = null) {
                const params = new URLSearchParams();

                params.set('customer_id', this.normalizeId(customerId));
                params.set('alternative_id', this.normalizeId(alternativeId));
                params.set('product_id', this.normalizeId(productId));

                return params;
            },

            executeScripts(container) {
                const scripts = container.querySelectorAll('script');

                scripts.forEach(oldScript => {
                    const newScript = document.createElement('script');

                    Array.from(oldScript.attributes).forEach(attr => {
                        newScript.setAttribute(attr.name, attr.value);
                    });

                    newScript.textContent = oldScript.textContent;
                    oldScript.replaceWith(newScript);
                });
            },

            async load(customerId, alternativeId = null, productId = null) {
                const mainContent = this.mainContent();

                if (!mainContent) {
                    console.error('#mainContent not found.');
                    return;
                }

                this.current.customerId = this.normalizeId(customerId);
                this.current.alternativeId = this.normalizeId(alternativeId);
                this.current.productId = this.normalizeId(productId);

                mainContent.innerHTML = this.loadingHtml();

                try {
                    const params = this.buildParams(
                        this.current.customerId,
                        this.current.alternativeId,
                        this.current.productId
                    );

                    const html = await this.request(`${this.routes.index}?${params.toString()}`, {
                        method: 'GET',
                        responseType: 'html',
                        accept: 'text/html',
                    });

                    mainContent.innerHTML = html;

                    this.executeScripts(mainContent);
                    this.bind();
                    this.refreshIcons();
                } catch (error) {
                    mainContent.innerHTML = this.errorHtml(this.parseError(error));
                }
            },

            async reload() {
                if (!this.current.customerId) {
                    const root = this.root();

                    if (root) {
                        this.current.customerId = this.normalizeId(root.dataset.customerId);
                        this.current.alternativeId = this.normalizeId(root.dataset.alternativeId);
                        this.current.productId = this.normalizeId(root.dataset.productId);
                    }
                }

                if (!this.current.customerId) {
                    return;
                }

                await this.load(
                    this.current.customerId,
                    this.current.alternativeId,
                    this.current.productId
                );
            },

            ensureToastWrap() {
                let wrap = document.getElementById('customerReviewToastWrap');

                if (wrap) {
                    return wrap;
                }

                wrap = document.createElement('div');
                wrap.id = 'customerReviewToastWrap';
                wrap.className = 'cr-toast-wrap';

                document.body.appendChild(wrap);

                return wrap;
            },

            toast(type = 'success', title = '', message = '') {
                const wrap = this.ensureToastWrap();

                const item = document.createElement('div');
                item.className = `cr-toast ${type}`;

                item.innerHTML = `
                    <div class="cr-toast-icon">${type === 'success' ? '✓' : '!'}</div>
                    <div>
                        <div class="cr-toast-title">${this.escapeHtml(title)}</div>
                        <div class="cr-toast-msg">${this.escapeHtml(message)}</div>
                    </div>
                `;

                wrap.appendChild(item);

                window.setTimeout(() => {
                    item.style.opacity = '0';
                    item.style.transform = 'translateY(-8px)';
                    item.style.transition = '.18s ease';

                    window.setTimeout(() => {
                        item.remove();
                    }, 220);
                }, 3600);
            },

            async confirmDelete() {
                if (window.Swal) {
                    const result = await Swal.fire({
                        title: 'Bewertung löschen?',
                        text: 'Diese Bewertung wird gelöscht.',
                        icon: 'warning',
                        showCancelButton: true,
                        confirmButtonText: 'Ja, löschen',
                        cancelButtonText: 'Abbrechen',
                        reverseButtons: true,
                        focusCancel: true,
                        buttonsStyling: false,
                        customClass: {
                            popup: 'cr-swal-popup',
                            confirmButton: 'cr-swal-confirm',
                            cancelButton: 'cr-swal-cancel',
                        },
                    });

                    return result.isConfirmed;
                }

                return confirm('Diese Bewertung wirklich löschen?');
            },

            injectUtilityStyles() {
                if (document.getElementById('customerReviewAjaxUtilityStyles')) {
                    return;
                }

                const style = document.createElement('style');
                style.id = 'customerReviewAjaxUtilityStyles';
                style.textContent = `
                    .cr-toast-wrap {
                        position: fixed;
                        top: 18px;
                        right: 18px;
                        z-index: 99999;
                        display: grid;
                        gap: 10px;
                        width: min(360px, calc(100vw - 32px));
                        pointer-events: none;
                    }

                    .cr-toast {
                        pointer-events: auto;
                        border-radius: 18px;
                        background: #fff;
                        border: 1px solid #e5e7eb;
                        box-shadow: 0 16px 40px rgba(15,23,42,.16);
                        padding: 13px 14px;
                        display: flex;
                        gap: 10px;
                        align-items: flex-start;
                        animation: crToastIn .18s ease-out;
                    }

                    .cr-toast.success {
                        border-color: rgba(147,194,28,.35);
                    }

                    .cr-toast.error {
                        border-color: rgba(229,6,86,.35);
                    }

                    .cr-toast-icon {
                        width: 30px;
                        height: 30px;
                        border-radius: 999px;
                        display: inline-flex;
                        align-items: center;
                        justify-content: center;
                        font-weight: 900;
                        flex: 0 0 auto;
                    }

                    .cr-toast.success .cr-toast-icon {
                        background: rgba(147,194,28,.15);
                        color: #4d7c0f;
                    }

                    .cr-toast.error .cr-toast-icon {
                        background: rgba(229,6,86,.12);
                        color: #e50656;
                    }

                    .cr-toast-title {
                        font-size: 13px;
                        font-weight: 900;
                        color: #1f2937;
                        margin-bottom: 2px;
                    }

                    .cr-toast-msg {
                        font-size: 12px;
                        color: #6b7280;
                        line-height: 1.45;
                    }

                    @keyframes crToastIn {
                        from {
                            opacity: 0;
                            transform: translateY(-8px);
                        }
                        to {
                            opacity: 1;
                            transform: translateY(0);
                        }
                    }

                    .cr-swal-popup {
                        border-radius: 22px !important;
                        padding: 20px !important;
                    }

                    .cr-swal-confirm,
                    .cr-swal-cancel {
                        border: 0 !important;
                        border-radius: 14px !important;
                        padding: 10px 16px !important;
                        font-size: 13px !important;
                        font-weight: 900 !important;
                        cursor: pointer !important;
                        margin: 0 4px !important;
                    }

                    .cr-swal-confirm {
                        background: #e50656 !important;
                        color: #fff !important;
                    }

                    .cr-swal-cancel {
                        background: #f3f4f6 !important;
                        color: #1f2937 !important;
                    }
                `;

                document.head.appendChild(style);
            },

            setStars(scope, value) {
                value = parseInt(value || 1, 10);

                if (!Number.isFinite(value)) {
                    value = 1;
                }

                value = Math.max(1, Math.min(5, value));

                const input = scope.querySelector('input[name="stars"], [name="stars"]');
                const buttons = scope.querySelectorAll('.cr-star-btn');

                if (input) {
                    input.value = value;
                }

                buttons.forEach(btn => {
                    const star = parseInt(btn.dataset.star || '0', 10);
                    btn.classList.toggle('active', star <= value);
                });
            },

            bindStars(root) {
                root.querySelectorAll('[data-cr-stars]').forEach(group => {
                    if (group.dataset.bound === '1') {
                        return;
                    }

                    group.dataset.bound = '1';

                    const form = group.closest('form') || root;
                    const input = form.querySelector('input[name="stars"], [name="stars"]');

                    group.querySelectorAll('.cr-star-btn').forEach(button => {
                        button.addEventListener('click', () => {
                            this.setStars(form, button.dataset.star);
                        });
                    });

                    this.setStars(form, input?.value || 5);
                });
            },

            bindCreateToggle(root) {
                const card = root.querySelector('[data-cr-create-card]');
                const openBtn = root.querySelector('[data-cr-toggle-create]');
                const closeBtn = root.querySelector('[data-cr-close-create]');

                if (openBtn && openBtn.dataset.bound !== '1') {
                    openBtn.dataset.bound = '1';

                    openBtn.addEventListener('click', () => {
                        if (!card) {
                            return;
                        }

                        card.classList.toggle('is-open');

                        if (card.classList.contains('is-open')) {
                            card.scrollIntoView({
                                behavior: 'smooth',
                                block: 'start',
                            });
                        }

                        this.refreshIcons();
                    });
                }

                if (closeBtn && closeBtn.dataset.bound !== '1') {
                    closeBtn.dataset.bound = '1';

                    closeBtn.addEventListener('click', () => {
                        if (card) {
                            card.classList.remove('is-open');
                        }
                    });
                }
            },

            bindCreateForm(root) {
                const form = root.querySelector('#customerReviewForm');

                if (!form || form.dataset.bound === '1') {
                    return;
                }

                form.dataset.bound = '1';

                form.addEventListener('submit', async (event) => {
                    event.preventDefault();

                    const submitBtn = form.querySelector('[type="submit"]');
                    const originalText = submitBtn ? submitBtn.innerHTML : '';

                    if (submitBtn) {
                        submitBtn.disabled = true;
                        submitBtn.innerHTML = 'Speichern...';
                    }

                    try {
                        const data = await this.request(this.routes.store, {
                            method: 'POST',
                            body: new FormData(form),
                        });

                        this.toast('success', 'Gespeichert', data.message || 'Bewertung wurde gespeichert.');

                        await this.reload();
                    } catch (error) {
                        this.toast('error', 'Fehler', this.parseError(error));
                    } finally {
                        if (submitBtn) {
                            submitBtn.disabled = false;
                            submitBtn.innerHTML = originalText;
                        }
                    }
                });

                form.addEventListener('reset', () => {
                    window.setTimeout(() => {
                        this.setStars(form, 5);
                    }, 30);
                });
            },

            bindSearchAndFilters(root) {
                const search = root.querySelector('[data-cr-search]');
                const starFilter = root.querySelector('[data-cr-star-filter]');
                const criticalFilter = root.querySelector('[data-cr-critical-filter]');
                const clearBtn = root.querySelector('[data-cr-clear-filters]');
                const visibleCount = root.querySelector('[data-cr-visible-count]');
                const noResults = root.querySelector('[data-cr-no-results]');

                const applyFilters = () => {
                    const term = (search?.value || '').toLowerCase().trim();
                    const star = starFilter?.value || '';
                    const critical = criticalFilter?.value || '';

                    let shown = 0;

                    root.querySelectorAll('.cr-review').forEach(card => {
                        const text = (card.dataset.search || '').toLowerCase();
                        const cardStars = card.dataset.stars || '';
                        const cardCritical = card.dataset.critical || '';

                        const matchSearch = !term || text.includes(term);
                        const matchStar = !star || cardStars === star;
                        const matchCritical = !critical || cardCritical === critical;

                        const visible = matchSearch && matchStar && matchCritical;

                        card.classList.toggle('is-hidden', !visible);

                        if (visible) {
                            shown++;
                        }
                    });

                    if (visibleCount) {
                        visibleCount.textContent = shown;
                    }

                    if (noResults) {
                        noResults.classList.toggle('is-hidden', shown !== 0);
                    }
                };

                if (search && search.dataset.bound !== '1') {
                    search.dataset.bound = '1';
                    search.addEventListener('input', applyFilters);
                }

                if (starFilter && starFilter.dataset.bound !== '1') {
                    starFilter.dataset.bound = '1';
                    starFilter.addEventListener('change', applyFilters);
                }

                if (criticalFilter && criticalFilter.dataset.bound !== '1') {
                    criticalFilter.dataset.bound = '1';
                    criticalFilter.addEventListener('change', applyFilters);
                }

                if (clearBtn && clearBtn.dataset.bound !== '1') {
                    clearBtn.dataset.bound = '1';

                    clearBtn.addEventListener('click', () => {
                        if (search) search.value = '';
                        if (starFilter) starFilter.value = '';
                        if (criticalFilter) criticalFilter.value = '';

                        applyFilters();
                    });
                }

                applyFilters();
            },

            bindEditButtons(root) {
                root.querySelectorAll('[data-cr-edit]').forEach(button => {
                    if (button.dataset.bound === '1') {
                        return;
                    }

                    button.dataset.bound = '1';

                    button.addEventListener('click', () => {
                        const reviewCard = button.closest('[data-review-id]');

                        if (!reviewCard) {
                            return;
                        }

                        root.querySelectorAll('.cr-review.is-editing').forEach(card => {
                            if (card !== reviewCard) {
                                card.classList.remove('is-editing');
                            }
                        });

                        reviewCard.classList.toggle('is-editing');

                        if (reviewCard.classList.contains('is-editing')) {
                            reviewCard.scrollIntoView({
                                behavior: 'smooth',
                                block: 'center',
                            });
                        }

                        this.refreshIcons();
                    });
                });

                root.querySelectorAll('[data-cr-cancel-edit]').forEach(button => {
                    if (button.dataset.bound === '1') {
                        return;
                    }

                    button.dataset.bound = '1';

                    button.addEventListener('click', () => {
                        const reviewCard = button.closest('[data-review-id]');

                        if (reviewCard) {
                            reviewCard.classList.remove('is-editing');
                        }
                    });
                });
            },

            bindUpdateForms(root) {
                root.querySelectorAll('[data-cr-edit-form]').forEach(form => {
                    if (form.dataset.bound === '1') {
                        return;
                    }

                    form.dataset.bound = '1';

                    form.addEventListener('submit', async (event) => {
                        event.preventDefault();

                        const reviewCard = form.closest('[data-review-id]');
                        const reviewId = reviewCard?.dataset.reviewId;

                        if (!reviewId) {
                            this.toast('error', 'Fehler', 'Bewertung-ID fehlt.');
                            return;
                        }

                        const submitBtn = form.querySelector('[type="submit"]');
                        const originalText = submitBtn ? submitBtn.innerHTML : '';

                        if (submitBtn) {
                            submitBtn.disabled = true;
                            submitBtn.innerHTML = 'Aktualisieren...';
                        }

                        try {
                            const formData = new FormData(form);
                            formData.append('_method', 'PUT');

                            const data = await this.request(`${this.routes.base}/${reviewId}`, {
                                method: 'POST',
                                body: formData,
                            });

                            this.toast('success', 'Aktualisiert', data.message || 'Bewertung wurde aktualisiert.');

                            await this.reload();
                        } catch (error) {
                            this.toast('error', 'Fehler', this.parseError(error));
                        } finally {
                            if (submitBtn) {
                                submitBtn.disabled = false;
                                submitBtn.innerHTML = originalText;
                            }
                        }
                    });
                });
            },

            bindDeleteButtons(root) {
                root.querySelectorAll('[data-cr-delete]').forEach(button => {
                    if (button.dataset.bound === '1') {
                        return;
                    }

                    button.dataset.bound = '1';

                    button.addEventListener('click', async () => {
                        const reviewCard = button.closest('[data-review-id]');
                        const reviewId = reviewCard?.dataset.reviewId;

                        if (!reviewId) {
                            this.toast('error', 'Fehler', 'Bewertung-ID fehlt.');
                            return;
                        }

                        const confirmed = await this.confirmDelete();

                        if (!confirmed) {
                            return;
                        }

                        const originalText = button.innerHTML;

                        button.disabled = true;
                        button.innerHTML = 'Löschen...';

                        try {
                            const formData = new FormData();
                            formData.append('_method', 'DELETE');

                            const data = await this.request(`${this.routes.base}/${reviewId}`, {
                                method: 'POST',
                                body: formData,
                            });

                            this.toast('success', 'Gelöscht', data.message || 'Bewertung wurde gelöscht.');

                            await this.reload();
                        } catch (error) {
                            button.disabled = false;
                            button.innerHTML = originalText;

                            this.toast('error', 'Fehler', this.parseError(error));
                        }
                    });
                });
            },

            bind() {
                this.injectUtilityStyles();

                const root = this.root();

                if (!root) {
                    return;
                }

                this.current.customerId = this.current.customerId || this.normalizeId(root.dataset.customerId);
                this.current.alternativeId = this.current.alternativeId || this.normalizeId(root.dataset.alternativeId);
                this.current.productId = this.current.productId || this.normalizeId(root.dataset.productId);

                this.bindStars(root);
                this.bindCreateToggle(root);
                this.bindCreateForm(root);
                this.bindSearchAndFilters(root);
                this.bindEditButtons(root);
                this.bindUpdateForms(root);
                this.bindDeleteButtons(root);
                this.refreshIcons();
            },
        };

        window.loadCustomerReviews = function (customerId, alternativeId = null, productId = null) {
            return window.CustomerReviewAjax.load(customerId, alternativeId, productId);
        };

        window.deleteCustomerReview = async function (reviewId) {
            const confirmed = await window.CustomerReviewAjax.confirmDelete();

            if (!confirmed) {
                return;
            }

            try {
                const formData = new FormData();
                formData.append('_method', 'DELETE');

                const data = await window.CustomerReviewAjax.request(
                    `${window.CustomerReviewAjax.routes.base}/${reviewId}`,
                    {
                        method: 'POST',
                        body: formData,
                    }
                );

                window.CustomerReviewAjax.toast(
                    'success',
                    'Gelöscht',
                    data.message || 'Bewertung wurde gelöscht.'
                );

                await window.CustomerReviewAjax.reload();
            } catch (error) {
                window.CustomerReviewAjax.toast(
                    'error',
                    'Fehler',
                    window.CustomerReviewAjax.parseError(error)
                );
            }
        };

        document.addEventListener('DOMContentLoaded', function () {
            window.CustomerReviewAjax.bind();
        });
    </script>

    
    </script>

@endsection
 